LOCAL_HOSTS = {"127.0.0.1", "::1", "localhost", "testclient"}


def require_admin(req: Request) -> None:
    expected = get_settings().admin_token
    if expected:
        given = req.headers.get("x-admin-token") or req.query.get("token") or ""
        if not secrets.compare_digest(str(given), expected):
            raise HTTPError(401, "Admin token required")
        return
    # no token configured: the back-office is only reachable from this machine.
    # A request relayed by a proxy (hosting platform) is never "local", whatever its socket address.
    proxied = any(h in req.headers for h in ("x-forwarded-for", "x-real-ip", "forwarded"))
    if req.client_host not in LOCAL_HOSTS or proxied:
        raise HTTPError(403, "Set ADMIN_TOKEN to use the admin API remotely")


# --------------------------------------------------------------------------- export documents

def conversation_document(db: Session, conv: Conversation) -> dict[str, Any]:
    engine = ActionEngine(db, conv.user, conv)
    msgs = db.scalars(select(Message).where(Message.conversation_id == conv.id).order_by(Message.id)).all()
    txs = db.scalars(select(Transaction).where(Transaction.conversation_id == conv.id).order_by(Transaction.id)).all()
    out_msgs = []
    for m in msgs:
        meta = dict(m.meta or {})
        ui = meta.get("ui") or {}
        if ui:  # keep the directive type + ids, not the full rendered card
            meta["ui"] = {k: v for k, v in {
                "type": ui.get("type"), "service": ui.get("service"), "screen": ui.get("screen"),
                "awaiting": ui.get("awaiting"), "transaction": (ui.get("action") or {}).get("reference"),
                "schedule_id": (ui.get("schedule") or {}).get("id"),
            }.items() if v is not None}
        out_msgs.append({"id": m.id, "role": m.role, "channel": m.channel, "content": m.content,
                         "created_at": iso(m.created_at), "meta": meta})
    return {
        "id": conv.id, "title": conv.title, "status": conv.status, "department": conv.department, "channel": conv.channel,
        "user": {"name": conv.user.name, "phone": conv.user.phone},
        "created_at": iso(conv.created_at), "updated_at": iso(conv.updated_at),
        "message_count": len(out_msgs), "messages": out_msgs,
        "transactions": [{k: v for k, v in (engine.public_tx(t) or {}).items()
                          if k in ("reference", "service_name", "subtitle", "status", "amount_display",
                                   "total_display", "source", "created_at", "completed_at", "result")}
                         for t in txs],
    }


# --------------------------------------------------------------------------- routes

@route("GET", "/api/admin/stats", admin=True)
def stats(db, req):
    s = get_settings()
    completed = select(Transaction).where(Transaction.status == "completed").subquery()
    modes: dict[str, int] = {}
    latencies, cost = [], 0.0
    for meta in db.scalars(select(Message.meta).where(Message.role == "assistant")).all():
        meta = meta or {}
        mode = meta.get("mode", "unknown")
        modes[mode] = modes.get(mode, 0) + 1
        if meta.get("latency_ms") is not None and mode in ("llm", "offline", "rule", "offline_fallback", "safety"):
            latencies.append(meta["latency_ms"])
        cost += float(meta.get("cost_usd") or 0)
    latencies.sort()
    return {
        "conversations": db.scalar(select(func.count(Conversation.id))) or 0,
        "handover_open": db.scalar(select(func.count(Conversation.id)).where(Conversation.status == "handover")) or 0,
        "messages": db.scalar(select(func.count(Message.id)).where(Message.role.in_(["user", "assistant", "staff"]))) or 0,
        "voice_messages": db.scalar(select(func.count(Message.id)).where(Message.channel == "voice")) or 0,
        "transactions_completed": db.scalar(select(func.count()).select_from(completed)) or 0,
        "volume_iqd": db.scalar(select(func.coalesce(func.sum(completed.c.total_iqd), 0))) or 0,
        "assistant_transactions": db.scalar(select(func.count(Transaction.id)).where(
            Transaction.status == "completed", Transaction.source == "assistant")) or 0,
        "active_schedules": db.scalar(select(func.count(Schedule.id)).where(Schedule.status == "active")) or 0,
        "reply_modes": modes,
        "latency_p50_ms": latencies[len(latencies) // 2] if latencies else None,
        "latency_p95_ms": latencies[max(0, int(len(latencies) * 0.95) - 1)] if latencies else None,
        "llm_cost_usd": round(cost, 4),
        "agent": {"llm_enabled": s.llm_enabled, "model": s.llm_label if s.llm_enabled else None},
    }


@route("GET", "/api/admin/conversations", admin=True)
def conversations(db, req):
    limit = max(1, min(int(req.query.get("limit") or 100), 500))
    q = select(Conversation).order_by(Conversation.updated_at.desc()).limit(limit)
    if req.query.get("status"):
        q = q.where(Conversation.status == req.query["status"])
    out = []
    for c in db.scalars(q).all():
        last = db.scalar(select(Message).where(Message.conversation_id == c.id,
                                               Message.role.in_(["user", "assistant", "staff"]))
                         .order_by(Message.id.desc()))
        count = db.scalar(select(func.count(Message.id)).where(Message.conversation_id == c.id)) or 0
        tx_count = db.scalar(select(func.count(Transaction.id)).where(
            Transaction.conversation_id == c.id, Transaction.status == "completed")) or 0
        out.append({"id": c.id, "title": c.title, "status": c.status, "department": c.department, "channel": c.channel,
                    "messages": count, "transactions": tx_count,
                    "last_message": last.content[:140] if last else "", "last_role": last.role if last else None,
                    "created_at": iso(c.created_at), "updated_at": iso(c.updated_at)})
    return {"items": out}


def _conv(db, conv_id) -> Conversation:
    conv = db.get(Conversation, conv_id)
    if not conv:
        raise HTTPError(404, "not found")
    return conv


@route("GET", "/api/admin/conversations/{conv_id}", admin=True)
def conversation_detail(db, req, conv_id):
    conv = _conv(db, conv_id)
    engine = ActionEngine(db, conv.user, conv)
    txs = db.scalars(select(Transaction).where(Transaction.conversation_id == conv_id).order_by(Transaction.id)).all()
    return {"id": conv.id, "title": conv.title, "status": conv.status, "department": conv.department, "draft": conv.draft,
            "created_at": iso(conv.created_at), "user": engine.wallet_summary(),
            "messages": [m.public() for m in conv.messages],
            "transactions": [engine.public_tx(t) for t in txs]}


@route("POST", "/api/admin/conversations/{conv_id}/resume", admin=True)
def resume(db, req, conv_id):
    conv = _conv(db, conv_id)
    conv.status = "active"
    db.add(Message(conversation_id=conv.id, role="event", channel="ui", content="assistant resumed by staff"))
    db.add(Message(conversation_id=conv.id, role="assistant", content="رجعتلك، شلون أكدر أساعدك؟ / I'm back, how can I help?",
                   meta={"mode": "staff_resume", "ui": None, "tools": []}))
    conv.updated_at = utcnow()
    db.commit()
    return {"ok": True, "status": conv.status}


@route("POST", "/api/admin/conversations/{conv_id}/reply", admin=True)
def staff_reply(db, req, conv_id):
    conv = _conv(db, conv_id)
    text = (req.json().get("text") or "").strip()
    if not text or len(text) > 1000:
        raise HTTPError(422, "text is required (max 1000 characters)")
    db.add(Message(conversation_id=conv.id, role="staff", content=text))
    conv.updated_at = utcnow()
    db.commit()
    return {"ok": True}


