@route("GET", "/api/admin/llm/ping", admin=True)
def llm_ping(db, req):
    s = get_settings()
    if not s.llm_enabled:
        return {"ok": False, "error": "No LLM configured (set LLM_PROVIDER / LLM_MODEL / LLM_API_KEY) — offline agent in use"}
    try:
        return LLMClient(s).ping()
    except LLMError as exc:
        return {"ok": False, "error": str(exc)}


