AGENT_MODES = ("auto", "llm", "offline")


def _key_env(provider: str) -> Optional[str]:
    from .llm import PRESETS

    if provider == "custom":
        return "LLM_API_KEY"
    preset = PRESETS.get(provider)
    return preset[2] if preset else None


def _mask(key: str) -> str:
    key = key or ""
    return f"{key[:3]}…{key[-4:]}" if len(key) > 12 else ("••••" if key else "")


def _editable() -> None:
    import os

    if os.environ.get("STATIC_BUILD"):
        raise HTTPError(400, "API keys can only be added on the server, never in the browser build")


def _apply_llm_change() -> None:
    from . import llm as llm_mod

    get_settings.cache_clear()
    llm_mod._shared.clear()  # the next message builds a client from the new settings


def _provider(body: dict, field: str = "provider") -> str:
    from .llm import PRESETS

    p = str(body.get(field) or "").strip().lower()
    if p not in PRESETS:
        raise HTTPError(422, f"unknown provider '{p}'")
    return p


def _text(body: dict, field: str, max_len: int) -> str:
    v = body.get(field)
    if v is None:
        return ""
    if not isinstance(v, str) or len(v.strip()) > max_len:
        raise HTTPError(422, f"{field} is invalid")
    return v.strip()


def _base_url(body: dict) -> str:
    u = _text(body, "base_url", 300)
    if u and not re.fullmatch(r"https?://\S+", u):
        raise HTTPError(422, "base_url must start with http:// or https://")
    return u.rstrip("/")


def _api_key(body: dict) -> str:
    k = _text(body, "api_key", 512)
    if not k or len(k) < 8 or re.search(r"\s", k) or not k.isascii():
        raise HTTPError(422, "api_key looks invalid (8-512 characters, no spaces)")
    return k


def llm_admin_state() -> dict[str, Any]:
    import os

    from .config import read_llm_overrides
    from .llm import LOCAL, fallback_configs, get_client, resolve_config

    s = get_settings()
    ov = read_llm_overrides()
    admin_keys = ov.get("keys") or {}
    main = resolve_config(s)
    client = get_client(s)
    from .llm import PRESETS

    providers = []
    for pid, label, models in PROVIDER_INFO:
        env = _key_env(pid)
        key = s.env(env) if env else ""
        local = pid in LOCAL
        providers.append({"id": pid, "label": label, "models": models, "local": local,
                          "needs_key": not local and pid != "custom",
                          "key_set": bool(key), "key_hint": _mask(key),
                          "key_source": ("dashboard" if env in admin_keys else "env") if key else None,
                          **({"base_url": (s.env(f"{pid.upper()}_BASE_URL") or PRESETS[pid][0]).rstrip("/"),
                              "default_base_url": PRESETS[pid][0]} if local else {})})
    return {
        "editable": not os.environ.get("STATIC_BUILD"),
        "agent_mode": s.agent_mode,
        "llm_enabled": s.llm_enabled,
        "chain_source": "dashboard" if "llm_provider" in ov else "env",
        "primary": {"provider": main.provider, "model": main.model, "base_url": main.base_url} if main else None,
        "fallbacks": [f"{c.provider}:{c.model}" for c in fallback_configs(s)],
        "providers": providers,
        "health": client.health() if client is not None else [],
    }


@route("GET", "/api/admin/llm", admin=True)
def llm_state(db, req):
    return llm_admin_state()


@route("POST", "/api/admin/llm/key", admin=True)
def llm_save_key(db, req):
    """Save (optionally after a test call) an API key for one provider."""
    from .config import read_llm_overrides, write_llm_overrides

    _editable()
    body = req.json()
    provider = _provider(body)
    env = _key_env(provider)
    if not env:
        raise HTTPError(422, f"{provider} runs locally and needs no key")
    key = _api_key(body)
    if body.get("test"):
        res = _ping(provider, _text(body, "model", 120), key, _base_url(body))
        if not res["ok"]:
            return {**res, "saved": False}
    ov = read_llm_overrides()
    ov.setdefault("keys", {})[env] = key
    write_llm_overrides(ov)
    _apply_llm_change()
    return {"ok": True, "saved": True, "state": llm_admin_state()}


@route("POST", "/api/admin/llm/key/delete", admin=True)
def llm_delete_key(db, req):
    from .config import read_llm_overrides, write_llm_overrides

    _editable()
    env = _key_env(_provider(req.json()))
    ov = read_llm_overrides()
    if env and env in (ov.get("keys") or {}):
        del ov["keys"][env]
        write_llm_overrides(ov)
        _apply_llm_change()
    return {"ok": True, "state": llm_admin_state()}


@route("POST", "/api/admin/llm/chain", admin=True)
def llm_save_chain(db, req):
    """Primary model + ordered fallbacks + agent mode. Takes effect on the next message."""
    from .config import read_llm_overrides, write_llm_overrides
    from .llm import PRESETS

    _editable()
    body = req.json()
    provider = _provider(body)
    model = _text(body, "model", 120) or PRESETS[provider][1]
    base = _base_url(body)
    if provider == "custom" and (not base or not model):
        raise HTTPError(422, "custom needs base_url and model")
    fallbacks = body.get("fallbacks") or []
    if not isinstance(fallbacks, list) or len(fallbacks) > 6:
        raise HTTPError(422, "fallbacks must be a list (max 6)")
    clean_fb = []
    for item in fallbacks:
        if not isinstance(item, str) or len(item) > 140:
            raise HTTPError(422, "invalid fallback")
        p, _, m = item.strip().partition(":")
        p = p.lower()
        if p not in PRESETS or p == "custom":
            raise HTTPError(422, f"unknown fallback provider '{p}'")
        clean_fb.append(f"{p}:{m.strip() or PRESETS[p][1]}")
    mode = str(body.get("agent_mode") or "auto")
    if mode not in AGENT_MODES:
        raise HTTPError(422, "agent_mode must be auto, llm or offline")
    ov = read_llm_overrides()
    ov.update({"llm_provider": provider, "llm_model": model, "llm_base_url": base,
               "llm_fallbacks": ",".join(clean_fb), "agent_mode": mode,
               "deepseek_fallback_models": ""})  # the dashboard chain replaces the legacy DeepSeek list
    write_llm_overrides(ov)
    _apply_llm_change()
    return {"ok": True, "state": llm_admin_state()}


@route("POST", "/api/admin/llm/reset", admin=True)
def llm_reset(db, req):
    """Forget everything set from the dashboard (back to .env)."""
