def _ping(provider: str, model: str, key: str, base: str) -> dict[str, Any]:
    import time

    from .llm import PRESETS, LLMConfig

    preset = PRESETS[provider]
    from .llm import LOCAL

    local_base = get_settings().env(f"{provider.upper()}_BASE_URL") if provider in LOCAL else ""
    base = base or local_base or preset[0]
    cfg = LLMConfig(provider=provider, model=model or preset[1], base_url=base.rstrip("/"),
                    api_key=key, tool_mode=get_settings().llm_tool_mode)
    if not cfg.base_url or not cfg.model:
        return {"ok": False, "error": "base_url and model are required"}
    t0 = time.perf_counter()
    try:
        res = LLMClient(get_settings(), [cfg]).ping()
        return {**res, "latency_ms": int((time.perf_counter() - t0) * 1000)}
    except LLMError as exc:
        msg = str(exc).replace(key, _mask(key)) if key else str(exc)
        return {"ok": False, "model": f"{cfg.provider}:{cfg.model}", "error": msg[:300]}


