@route("POST", "/api/admin/llm/local/models", admin=True)
def llm_local_models(db, req):
    """Models installed on one server (local, or any OpenAI-compatible URL)."""
    from .llm import LOCAL, PRESETS, list_models

    _editable()
    body = req.json()
    provider = _provider(body)
    local_base = get_settings().env(f"{provider.upper()}_BASE_URL") if provider in LOCAL else ""
    base = _base_url(body) or local_base or PRESETS[provider][0]
    if not base:
        raise HTTPError(422, "base_url is required")
    env = _key_env(provider)
    key = "" if provider in LOCAL else (get_settings().env(env) if env else "")
    try:
        return {"ok": True, "base_url": base.rstrip("/"), "models": list_models(base, key)}
    except LLMError as exc:
        return {"ok": False, "base_url": base.rstrip("/"), "models": [], "error": str(exc)[:200]}


@route("POST", "/api/admin/llm/local/url", admin=True)
def llm_local_url(db, req):
    """Where a local provider runs (e.g. Ollama on another PC: http://192.168.1.20:11434/v1). Empty = default."""
    from .config import read_llm_overrides, write_llm_overrides
    from .llm import LOCAL

    _editable()
    body = req.json()
    provider = _provider(body)
    if provider not in LOCAL:
        raise HTTPError(422, "only local providers (ollama, lmstudio, vllm, llamacpp) have a server URL here")
    base = _base_url(body)
    ov = read_llm_overrides()
    urls = ov.setdefault("urls", {})
    env = f"{provider.upper()}_BASE_URL"
    if base:
        urls[env] = base
    else:
        urls.pop(env, None)
    write_llm_overrides(ov)
    _apply_llm_change()
    return {"ok": True, "state": llm_admin_state()}


@route("POST", "/api/admin/llm/test", admin=True)
def llm_test(db, req):
    """Ping one provider/model with the given key (or the saved one). Nothing is saved."""
    body = req.json()
    provider = _provider(body)
    env = _key_env(provider)
    key = _api_key(body) if body.get("api_key") else (get_settings().env(env) if env else "")
    return _ping(provider, _text(body, "model", 120), key, _base_url(body))

backend/agent/context.py:
"""Layer 3 of the orchestrator: dialogue state, so short replies are understood in context.

"الغي العملية" means the pending one if there is one, otherwise the operation that just completed
(which cannot be undone from chat, so the user is offered customer care). "نفس الشي لفاطمة" repeats the
last completed operation with a new receiver. "اي" after an offer accepts that offer.

Everything comes from the database (trusted), never from the model.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from datetime import timedelta
from typing import Any, Optional

from sqlalchemy import select

from ..engine import ActionEngine, fmt_money
from ..i18n import disp, tr
from ..models import Message, Transaction, utcnow

RECENT_COMPLETED = timedelta(hours=24)


@dataclass
class DialogueContext:
    lang: Optional[str] = None            # language of the previous assistant reply (sticky)
    prev_meta: dict = field(default_factory=dict)
    offer: Optional[dict] = None          # what the previous reply offered (e.g. hand-over to customer care)
    last_completed: Optional[Transaction] = None
    last_intent: Optional[str] = None

    def minutes_since_completed(self) -> Optional[int]:
        t = self.last_completed
        if t is None or t.completed_at is None:
            return None
        return max(0, int((utcnow() - t.completed_at).total_seconds() // 60))


def previous_assistant(db, conv) -> Optional[Message]:
    return db.scalar(select(Message).where(Message.conversation_id == conv.id, Message.role == "assistant")
                     .order_by(Message.id.desc()).limit(1))


def last_completed(db, engine: ActionEngine) -> Optional[Transaction]:
    conv = engine.conv
    if conv is not None:
        tx = db.scalar(select(Transaction).where(Transaction.conversation_id == conv.id,
                                                 Transaction.status == "completed")
                       .order_by(Transaction.completed_at.desc(), Transaction.id.desc()).limit(1))
        if tx is not None:
            return tx
    tx = db.scalar(select(Transaction).where(Transaction.user_id == engine.user.id, Transaction.status == "completed",
                                             Transaction.source == "assistant")
                   .order_by(Transaction.completed_at.desc(), Transaction.id.desc()).limit(1))
    if tx is not None and tx.completed_at and utcnow() - tx.completed_at <= RECENT_COMPLETED:
        return tx
    return None


def build(db, engine: ActionEngine) -> DialogueContext:
    prev = previous_assistant(db, engine.conv) if engine.conv is not None else None
    meta = (prev.meta or {}) if prev is not None else {}
    nlu = meta.get("nlu") or {}
    return DialogueContext(lang=meta.get("lang"), prev_meta=meta, offer=meta.get("offer"),
                           last_completed=last_completed(db, engine), last_intent=nlu.get("intent"))


def describe_tx(engine: ActionEngine, tx: Transaction) -> str:
    f = tx.fields or {}
    who = disp(f.get("recipient_name") or f.get("receiver_name") or f.get("biller") or f.get("provider") or "")
    amt = fmt_money(tx.amount, tx.currency)
    title = engine.title(tx)
    return f"{tx.reference} — {title} — {amt}" + (f" ({who})" if who and who not in title else "")


def summary_for_llm(engine: ActionEngine, ctx: DialogueContext) -> str:
    """Extra lines for the LLM state block."""
    lines = []
    if ctx.last_completed is not None:
        m = ctx.minutes_since_completed()
        lines.append(f"last_completed_operation: {describe_tx(engine, ctx.last_completed)}"
                     f"{f' — {m} min ago' if m is not None else ''} (completed operations cannot be cancelled from "
                     "chat; for a mistake/refund offer customer care)")
    if ctx.offer:
        lines.append(f"your_previous_reply_offered: {ctx.offer.get('type')} — a yes from the user accepts it")
    if ctx.last_intent:
        lines.append(f"previous_turn_intent: {ctx.last_intent}")
    return "\n".join(lines)


def repeat_fields(tx: Transaction) -> dict[str, Any]:
    """Fields of a completed operation that can be reused to prepare the same one again."""
    f = dict(tx.fields or {})
    out = {k: v for k, v in f.items() if k not in ("recipient_name", "is_new_recipient")
           and not (isinstance(v, str) and "*" in v)}
    if "amount" not in out:
        out["amount"] = tx.amount
    return out


def completed_cancel_reply(engine: ActionEngine, tx: Transaction) -> str:
    title = engine.title(tx)
    amt = fmt_money(tx.amount, tx.currency)
    return tr(f"العملية الأخيرة ({title}، {amt}، رقمها {tx.reference}) تنفذت وخلصت، فما أكدر ألغيها من هنا. "
              "إذا صار بيها غلط، تريد أحوّلك لخدمة العملاء حتى يتابعون استرجاعها؟",
              f"Your last operation ({title}, {amt}, reference {tx.reference}) is already completed, so I can't "
              "cancel it from here. If something went wrong, shall I pass you to customer care to follow up on a refund?")

