"""Deterministic detection of confirm / cancel replies (works the same with or without the LLM)."""
from __future__ import annotations

from typing import Optional

from ..textnorm import normalize

CONFIRM = {
    "نعم", "اي", "ايه", "ايوه", "ايي", "اكد", "اكده", "اكدها", "اكدلي", "تاكيد", "اكيد", "موافق",
    "موافقه", "تمام", "ماشي", "يلا", "يله", "اوكي", "اوك", "ok", "okay", "yes", "yeah", "yep",
    "confirm", "confirmed", "كونفيرم", "كنفرم", "صح", "صحيح", "سويها", "سوي", "دزها", "دز", "نفذ",
    "نفذها", "كمل", "كملها", "امشي", "مشيها", "توكل", "توكلنا", "خلص", "بلي", "اوافق", "حوله",
    "حولها", "ارسلها", "اشتري", "ادفع", "ادفعها", "اسحب", "اسحبها", "اشحن", "اشحنها",
    "sure", "go", "ahead", "proceed", "approve", "approved", "send", "pay", "yup", "do",
}
CANCEL = {
    "لا", "لاء", "كلا", "الغي", "الغيها", "الغاء", "الغيه", "الغ", "كنسل", "cancel", "no", "nope",
    "stop", "بطلت", "وقف", "تراجع", "لاتسوي", "ما", "اريد", "ماريد", "مااريد", "متريد", "مابيها",
    "انسى", "انساها", "اتركها", "اتركه", "خليها", "بعدين", "nevermind", "never", "mind", "dont", "don't",
}
FILLER = {
    "و", "هسه", "بس", "الله", "على", "عليك", "رجاء", "من", "فضلك", "العمليه", "ال", "يابه", "يا", "حجي",
    "حبيبي", "عمي", "خويه", "اخي", "اخوي", "شكرا", "زين", "رجاءا", "بالله", "اكيد", "خلي", "هاي", "هذي",
    "هيه", "الحواله", "التحويل", "العمليه", "تسوي", "سويت", "ياها", "بيها", "لله", "الحمد", "please",
    "it", "the", "now", "thanks", "thank", "you", "transfer", "payment", "this", "يخليك", "عيني", "عيوني",
    "حبي", "اغاتي", "that", "operation", "pls", "plz",
}
NEGATION = {"لا", "ما", "مو", "مش", "لاتسوي", "ماريد", "مااريد", "متريد", "بطلت", "الغي", "الغيها",
            "الغاء", "كنسل", "cancel", "no", "وقف", "dont", "don't", "never"}


# keyword sets must be compared in normalised form (ى->ي, ة->ه, أ->ا ...)
CONFIRM = {normalize(w) for w in CONFIRM}
CANCEL = {normalize(w) for w in CANCEL}
FILLER = {normalize(w) for w in FILLER}
NEGATION = {normalize(w) for w in NEGATION}


def quick_intent(text: str) -> Optional[str]:
    """Return 'confirm', 'cancel' or None for short, unambiguous replies."""
    n = normalize(text)
    if not n:
        return None
    tokens = n.split()
    if len(tokens) > 7:
        return None
    if any(ch.isdigit() for ch in n):
        return None
    joined = n.replace(" ", "")
    if joined in {"ماريد", "مااريد", "لاماريد", "لالا", "لاشكرا"}:
        return "cancel"
    has_neg = any(t in NEGATION for t in tokens)
    if not has_neg and all(t in CONFIRM or t in FILLER for t in tokens) and any(t in CONFIRM for t in tokens):
        return "confirm"
    if has_neg and all(t in CANCEL or t in FILLER or t in NEGATION for t in tokens):
        return "cancel"
    return None


def looks_affirmative(text: str) -> bool:
    """Looser check used to guard the LLM's confirm tool: the user must have said something affirmative."""
    tokens = normalize(text).split()
    if any(t in NEGATION for t in tokens):
        return False
    return any(t in CONFIRM for t in tokens)

