"""Offline rule-based agent (Iraqi Arabic + simple English).

Runs when no LLM is configured or every configured model is unreachable, so the app never breaks.
It understands the common phrasings for every service and does slot filling through the same
engine/tool executor as the LLM agent.
"""
from __future__ import annotations

import re
from typing import Optional

from ..catalog import (
    AGENT_SYNONYMS, AGENTS, BANK_SYNONYMS, BANKS, BILLER_SYNONYMS, BILLERS, CARD_PROVIDER_SYNONYMS,
    CARD_PROVIDERS, CARRIER_SYNONYMS, CARRIERS, COUNTRIES, COUNTRY_SYNONYMS, SERVICES,
    TOPUP_METHOD_SYNONYMS, TOPUP_METHODS, TRANSACTION_SERVICES,
)
from ..engine import SELF_WORDS
from ..i18n import tr
from ..textnorm import extract_phone, find_choice_in_text, normalize, parse_amount, phrase_in
from .tools import ToolExecutor


def _any(n: str, phrases) -> bool:
    return any(phrase_in(n, p) for p in phrases)


HUMAN = ["موظف", "خدمة العملاء", "انسان", "بشري", "شخص حقيقي", "شكوى", "اشتكي", "احتيال",
