         "human", "real person", "customer service", "support agent", "complaint", "fraud", "stolen"]
WU = ["ويسترن", "وسترن", "ويستيرن", "western", "يونيون", "union", "حوالة دولية", "حوالة للخارج",
      "للخارج", "برا العراق", "خارج العراق"]
TOPUP_VERBS = ["تعبئة", "تعبيه", "تعبية", "عبي", "عبيلي", "اعبي", "اشحن", "شحن", "اضيف", "اضافة", "ايداع",
               "اودع", "زود", "زيد", "top up", "topup", "recharge", "add", "load", "deposit", "fill"]
CARD_WORDS = ["بطاقة", "بطاقات", "كارت", "ببجي", "pubg", "شدات", "جوجل بلاي", "كوكل بلي", "كوكل بلاي",
              "بلايستيشن", "بلاي ستيشن", "ايتونز", "itunes", "playstation", "google play", "psn"]
MOBILE_OBJ = ["رصيد", "رصيدي", "خط", "خطي", "موبايل", "موبايلي", "تلفون", "تلفوني", "جوال", "كارت رصيد",
              "credit", "airtime", "phone", "mobile", "line"]
WITHDRAW = ["سحب", "اسحب", "اسحبلي", "نسحب", "كاش", "نقدي", "نقدا", "كاش اوت", "withdraw", "cash out", "cashout", "cash"]
BILL_WORDS = ["فاتورة", "فواتير", "فاتورتي", "فواتيري", "bill", "bills"]
PAY_VERBS = ["ادفع", "دفع", "سدد", "اسدد", "تسديد", "ادفعلي", "سددلي", "pay"]
BALANCE = ["رصيدي", "شكد عندي", "كم عندي", "شكد بالمحفظة", "شكد رصيد", "كم رصيد", "الرصيد", "شكد باقي",
           "شكد صار", "رصيد المحفظة", "balance", "my balance", "how much do i have", "how much money"]
HISTORY = ["عملياتي", "العمليات", "اخر العمليات", "سجل", "الحركات", "كشف", "اخر حوالة", "شنو سويت",
           "history", "transactions", "recent", "statement"]
CONTACTS = ["جهات الاتصال", "جهات اتصالي", "الاسماء", "الارقام المحفوظة", "contacts", "my contacts"]
TRANSFER = ["حول", "احول", "نحول", "حولي", "حوللي", "تحويل", "دز", "ادز", "دزلي", "ارسل", "ارسله",
            "ابعث", "ابعثله", "انطي", "انطيه", "اعطي", "بعث", "حوله", "حولها", "تحول",
            "send", "transfer", "give"]
GREETING = ["مرحبا", "هلو", "هلا", "السلام", "شلونك", "صباح الخير", "مساء الخير", "هاي", "hello", "hi", "hey",
            "good morning", "good evening"]
HELP = ["شتكدر", "شنو تكدر", "شنو تسوي", "مساعدة", "ساعدني", "help", "شلون استخدم", "what can you do"]

NAME_TRIGGERS = {"باسم", "اسمه", "اسمها", "للمستلم", "المستلم", "لاسم", "الاسم", "اسم", "لفلان", "to", "named", "name"}
NAME_STOP = {"ب", "في", "الى", "على", "مبلغ", "بمبلغ", "دولار", "بالدولار", "قيمه", "بقيمه", "و", "يم",
             "بدوله", "دوله", "ساكن", "يسكن", "موجود", "ويسترن", "يونيون", "in", "dollars", "usd", "via",
             "western", "union", "for", "of", "from", "is"}
NAME_FILLER = {"اسمه", "اسمها", "الاسم", "اسم", "هو", "هي", "المستلم", "اسمه الكامل", "الكامل", "يا", "باسم"}
NAME_TRIGGERS = {normalize(w) for w in NAME_TRIGGERS}
NAME_STOP = {normalize(w) for w in NAME_STOP}
NAME_FILLER = {normalize(w) for w in NAME_FILLER}


def detect_intent(n: str) -> Optional[str]:
    if _any(n, HUMAN):
        return "human"
    if _any(n, WU):
        return "western_union"
    if _any(n, ["محفظه", "محفظتي", "المحفظه", "wallet", "my wallet"]) and _any(n, TOPUP_VERBS):
        return "wallet_topup"
    if _any(n, ["ايداع", "اودع"]):
        return "wallet_topup"
    if _any(n, CARD_WORDS + ["gift card", "card"]) and not _any(n, ["كارت رصيد", "visa", "mastercard"]):
        return "buy_card"
    if _any(n, TOPUP_VERBS) and _any(n, MOBILE_OBJ):
        return "mobile_topup"
    if _any(n, WITHDRAW):
        named_agent = find_choice_in_text(n, AGENTS, AGENT_SYNONYMS) is not None
        return "agent_withdraw" if (named_agent or _any(n, ["وكيل", "الوكيل", "agent"])) else "cash_withdraw"
    has_bill = _any(n, BILL_WORDS)
    if (has_bill or _any(n, ["كهرباء", "الكهرباء", "الماء", "الماي", "المي", "انترنت الارضي", "electricity",
                             "water"])) and _any(n, PAY_VERBS):
        return "bill_payment"
    if has_bill:
        return "bills_info"
    if _any(n, BALANCE):
        return "balance"
    if _any(n, HISTORY):
        return "history"
    if _any(n, CONTACTS):
        return "contacts"
    if _any(n, TRANSFER):
        return "transfer"
    if _any(n, HELP):
        return "help"
    if _any(n, GREETING):
        return "greeting"
    return None


def _extract_name(text: str, awaiting: bool) -> Optional[str]:
    """Pull a person's full name out of a sentence (Western Union receiver)."""
    tokens = text.split()
    norm = [normalize(t) for t in tokens]

    def clean_run(start: int) -> list[str]:
        out = []
        for tok, nt in zip(tokens[start:], norm[start:]):
            if (nt in NAME_STOP or re.search(r"\d", nt) or parse_amount(nt)
                    or find_choice_in_text(nt, COUNTRIES, COUNTRY_SYNONYMS)):
                break
            out.append(re.sub(r"[^\w\-']", "", tok))
        return [t for t in out if t]

    for i, nt in enumerate(norm):
        if nt in NAME_TRIGGERS:
            run = clean_run(i + 1)
            if len(run) >= 2:
                return " ".join(run[:5])
    if awaiting:
        kept = [tok for tok, nt in zip(tokens, norm) if nt not in NAME_FILLER]
        run = []
        for tok in kept:
            nt = normalize(tok)
            if re.search(r"\d", nt) or find_choice_in_text(nt, COUNTRIES, COUNTRY_SYNONYMS):
                continue
            run.append(re.sub(r"[^\w\-']", "", tok))
        run = [t for t in run if t]
        return " ".join(run[:6]) if run else None
    return None


def extract_fields(service: str, text: str, awaiting: Optional[str], executor: ToolExecutor) -> dict:
    engine = executor.engine
    phone, rest = extract_phone(text)
    n = normalize(rest)
    fields: dict = {}
    amount = parse_amount(n)

    if service == "transfer":
        if phone:
            fields["wallet"] = phone
        else:
            found = engine.contact_in_text(n)
            if found:
                fields["contact_name"] = found[0].name
            elif awaiting == "wallet" and not amount:
                fields["contact_name"] = rest.strip()
        if amount:
            fields["amount"] = amount
        if awaiting == "note" and not fields:
            fields["note"] = text.strip()

    elif service == "western_union":
        country = find_choice_in_text(n, COUNTRIES, COUNTRY_SYNONYMS)
        if country:
            fields["country"] = country
        if amount:
            fields["amount"] = amount
        name = _extract_name(rest, awaiting == "receiver_name" and not country and not amount)
        if name:
            fields["receiver_name"] = name
        if awaiting == "country" and not country:
            fields["country"] = rest.strip()

    elif service in ("agent_withdraw", "cash_withdraw"):
        if service == "agent_withdraw":
            agent = find_choice_in_text(n, AGENTS, AGENT_SYNONYMS)
            if agent:
                fields["agent"] = agent
            elif awaiting == "agent":
                fields["agent"] = rest.strip()
        if amount:
            fields["amount"] = amount

    elif service == "buy_card":
        provider = find_choice_in_text(n, CARD_PROVIDERS, CARD_PROVIDER_SYNONYMS)
        if provider:
            fields["provider"] = provider
        elif awaiting == "provider":
            fields["provider"] = rest.strip()
        if amount:
            fields["amount"] = amount

    elif service == "wallet_topup":
        method = find_choice_in_text(n, TOPUP_METHODS, TOPUP_METHOD_SYNONYMS)
        if method:
            fields["method"] = method
        elif awaiting == "method":
            fields["method"] = rest.strip()
        agent = find_choice_in_text(n, AGENTS, AGENT_SYNONYMS)
        if agent:
            fields["agent"] = agent
        bank = find_choice_in_text(n, BANKS, BANK_SYNONYMS)
        if bank:
            fields["bank"] = bank
        if awaiting == "account":
            fields["account"] = rest.strip()
        elif awaiting == "agent" and not agent:
            fields["agent"] = rest.strip()
        elif awaiting == "bank" and not bank:
            fields["bank"] = rest.strip()
        if amount and awaiting != "account":
            fields["amount"] = amount

    elif service == "mobile_topup":
        if phone:
            fields["number"] = phone
        elif any(t in SELF_WORDS for t in n.split()) or phrase_in(n, "رقمي"):
            fields["number"] = "self"
        carrier = find_choice_in_text(n, CARRIERS, CARRIER_SYNONYMS)
        if carrier:
            fields["carrier"] = carrier
        elif awaiting == "carrier":
            fields["carrier"] = rest.strip()
        if amount:
            fields["amount"] = amount

    elif service == "bill_payment":
        biller = find_choice_in_text(n, BILLERS, BILLER_SYNONYMS)
        if biller:
            fields["biller"] = biller
        elif awaiting == "biller":
            fields["biller"] = rest.strip()
        if awaiting == "account":
            fields["account"] = text.strip()
        elif amount:
            fields["amount"] = amount

    # last resort: give the raw answer to the awaited money field so the engine can explain
    if awaiting == "amount" and "amount" not in fields and not fields:
        fields["amount"] = rest.strip()
    return fields


def GREETING_REPLY() -> str:
    return tr("هلا بيك! أكدر أحوّل فلوس، أرسل ويسترن يونيون، أدفع فواتير، أشحن رصيد، وأسحبلك كاش. بس كلّي شتريد.",
              "Hi! I can send money, Western Union, pay bills, add phone credit and get you cash. Just tell me what you need.")


def HELP_REPLY() -> str:
    return tr("كلّي شتريد بكلامك العادي، مثلاً: «حوّل 25 ألف لعلي»، «ادفع فاتورة الكهرباء»، "
              "«اشحن رصيدي 10 آلاف»، أو «ويسترن يونيون لتركيا 200 دولار».",
              "Just say what you need, e.g. «send 25,000 to Ali», «pay the electricity bill», "
              "«add 10,000 credit to my number», or «Western Union 200 dollars to Turkey».")


def FALLBACK_REPLY() -> str:
    return tr("ما فهمت عليك زين. تكدر تكلّي مثلاً: «حوّل 25 ألف لعلي» أو «شكد رصيدي» أو «ادفع فاتورة الماء».",
              "Sorry, I didn't get that. Try e.g. «send 25,000 to Ali», «my balance» or «pay the water bill».")


REMINDER_WORDS = ["ذكرني", "ذكرلي", "نبهني", "فكرني", "ذكريني", "نبهيني", "remind me"]
SCHED_WORDS = ["المجدولة", "المجدول", "مجدولة", "المتكررة", "المتكرر", "التلقائية", "التلقائي", "الشهري",
               "الشهرية", "الاسبوعي", "اليومي", "التذكير", "التذكيرات", "الجدولة", "الدفعة", "دفعاتي", "المنتظمة",
               "scheduled", "schedules", "recurring", "standing order", "reminders"]
STOP_WORDS = ["وقف", "اوقف", "وكف", "الغي", "الغاء", "بطل", "امسح", "احذف", "شيل", "stop", "cancel", "delete"]
NOTIF_WORDS = ["تنبيهات", "تنبيهاتي", "التنبيهات", "الاشعارات", "اشعاراتي", "اشعار", "notifications", "alerts"]


def _schedule_turn(text: str, n: str, intent: Optional[str], executor: ToolExecutor) -> Optional[str]:
    """Handle scheduling / reminders. Returns a reply, or None when the message is not about schedules."""
    from ..schedules import SCHEDULABLE, parse_date, parse_day, parse_frequency, parse_timing_text

    engine = executor.engine
    draft = engine.draft
    sched_draft = bool(draft and draft.get("mode") == "schedule")
    timing, rest = parse_timing_text(text)

    if _any(n, STOP_WORDS) and _any(n, SCHED_WORDS):
        items = executor.sched.list()
        if not items:
            return executor.run("show_info", {"topic": "schedules"})["message"]
        target = None
        if len(items) == 1:
            target = items[0]
        else:
            names = engine.contact_in_text(n)
            for s in items:
                f = s.fields or {}
                if names and f.get("wallet") in {c.wallet for c in names}:
                    target = s
                    break
                if f.get("biller") and find_choice_in_text(n, BILLERS, BILLER_SYNONYMS) == f.get("biller"):
                    target = s
                    break
        if target is None:
            executor.run("show_info", {"topic": "schedules"})
            return tr("عندك أكثر من وحدة مجدولة. يا وحدة تريد أوقّف؟ اختارها من الشاشة أو كلّي اسم الشخص.",
                      "You have more than one schedule. Which one should I stop? Pick it on screen or tell me the name.")
        return executor.run("manage_schedules", {"action": "cancel", "schedule_id": target.id})["message"]

    if _any(n, NOTIF_WORDS):
        return executor.run("show_info", {"topic": "notifications"})["message"]

    if _any(n, SCHED_WORDS) and not timing and intent in (None, "history", "balance") and not sched_draft:
        return executor.run("show_info", {"topic": "schedules"})["message"]

    if _any(n, REMINDER_WORDS) and not sched_draft:
        note = rest
        for w in REMINDER_WORDS:
            note = re.sub(rf"(?:^|\s){normalize(w)}(?=\s|$)", " ", note)
        note = re.sub(r"^\s*(?:ب|ان|اني|حتى|to|that|about)\s+", "", note).strip()
        return executor.run("create_reminder", {"note": note, **timing})["message"]

    if intent in SCHEDULABLE and timing and (not sched_draft or intent != draft.get("service")):
        fields = extract_fields(intent, rest, None, executor)
        return executor.run("schedule_payment", {"service": intent, "fields": fields, **timing})["message"]

    # "خليها كل شهر" while an immediate operation is being prepared -> convert it into a schedule
    if (timing and intent is None and draft and not sched_draft and draft.get("service") in SCHEDULABLE):
        fields = {**(draft.get("fields") or {}), **extract_fields(draft["service"], rest, None, executor)}
        return executor.run("schedule_payment", {"service": draft["service"], "fields": fields, **timing})["message"]

    if sched_draft and (intent is None or intent == draft.get("service") or intent in ("balance",)):
        awaiting = draft.get("awaiting")
        t = dict(timing)
        draft_freq = (draft.get("timing") or {}).get("frequency")
        if awaiting == "day" and draft_freq and t.get("frequency") == "once":
            t = {}  # "يوم 20" answers the day of the existing monthly schedule, not a one-off date
        freq = draft_freq or t.get("frequency")
        if awaiting == "frequency" and "frequency" not in t:
            f = parse_frequency(text)
            if f:
                t["frequency"] = f
            elif parse_date(text):
                t.update({"frequency": "once", "date": parse_date(text)})
        elif awaiting == "day" and "day" not in t:
            d = parse_day(text, freq)
            if d is not None:
                t["day"] = d
        elif awaiting == "date" and "date" not in t:
            d = parse_date(text) or parse_date(f"يوم {text}")
            if d:
                t["date"] = d
        if draft.get("kind") == "reminder":
            args = {"note": text.strip() if awaiting == "note" else draft.get("note"), **t}
            return executor.run("create_reminder", args)["message"]
        timing_keys = ("frequency", "day", "date")
        fields = extract_fields(draft["service"], rest, None if awaiting in timing_keys else awaiting, executor)
        if awaiting in timing_keys:
            fields.pop("amount", None)  # "يوم 5" is a day, not 5,000 dinars
        return executor.run("schedule_payment", {"service": draft["service"], "fields": fields, **t})["message"]
    return None


def handle(text: str, executor: ToolExecutor) -> str:
    engine = executor.engine
    n = normalize(text)
    intent = detect_intent(n)
    draft = engine.draft
    pending = engine.pending_transaction()

    if intent == "human":
        return executor.run("request_human_support", {"reason": text})["message"]

    sched_reply = _schedule_turn(text, n, intent, executor)
    if sched_reply is not None:
        return sched_reply
    draft = engine.draft

    if intent in TRANSACTION_SERVICES and (not draft or intent != draft.get("service")):
        fields = extract_fields(intent, text, None, executor)
        return executor.run("prepare_transaction", {"service": intent, "fields": fields})["message"]

    if draft and draft.get("mode") != "schedule" and draft.get("service") in SERVICES:
        service = draft["service"]
        awaiting = draft.get("awaiting") if not pending else None
        fields = extract_fields(service, text, awaiting, executor)
        if fields:
            return executor.run("prepare_transaction", {"service": service, "fields": fields})["message"]
        if pending and intent is None:
            executor.ui = {"type": "confirm", "action": engine.public_tx(pending)}
            executor.quick_replies = [tr("أكّد", "Confirm"), tr("إلغاء", "Cancel")]
            return tr("العملية جاهزة بالشاشة. إذا كلشي صحيح كول «أكّد»، أو «إلغاء» حتى ألغيها.",
                      "The operation is ready on screen. Say «confirm» if it's right, or «cancel».")

    if intent == "balance":
        return executor.run("show_info", {"topic": "balance"})["message"]
    if intent == "history":
        return executor.run("show_info", {"topic": "transactions"})["message"]
    if intent == "bills_info":
        return executor.run("show_info", {"topic": "bills"})["message"]
    if intent == "contacts":
        return executor.run("show_info", {"topic": "contacts"})["message"]
    if intent == "greeting":
        executor.quick_replies = [tr("حوّل فلوس", "Send money"), tr("ادفع فاتورة", "Pay a bill"), tr("شكد رصيدي", "My balance")]
        return GREETING_REPLY()
    if intent == "help":
        executor.quick_replies = [tr("حوّل 25 ألف لعلي", "Send 25,000 to Ali"), tr("ادفع فاتورة الكهرباء", "Pay the electricity bill"),
                                  tr("اشحن رصيدي 10 آلاف", "Add 10,000 credit to my number")]
        return HELP_REPLY()
    if draft and draft.get("service") in SERVICES and draft.get("mode") != "schedule":
        svc = SERVICES[draft["service"]]
        f = svc.field(draft.get("awaiting") or "")
        if f is not None:
            return f.ask_t
    executor.quick_replies = [tr("حوّل فلوس", "Send money"), tr("ويسترن يونيون", "Western Union"),
                              tr("ادفع فاتورة", "Pay a bill"), tr("شكد رصيدي", "My balance")]
    return FALLBACK_REPLY()

