"""Tools exposed to the LLM, and the executor that turns tool calls into engine actions + UI directives."""
from __future__ import annotations

from typing import Any, Optional

from ..catalog import PROVIDERS_LIST, SERVICES, TRANSACTION_SERVICES
from ..engine import ActionEngine, fmt_iqd
from ..i18n import disp, tr
from ..schedules import SCHEDULABLE, ScheduleManager, generate_reminders, unread_notifications
from ..models import iso, utcnow
from .intents import looks_affirmative

# where the facts returned by each tool come from (shown in the "how I know" trace)
TOOL_SOURCES = {
    "prepare_transaction": "engine.validate + catalog rules", "schedule_payment": "engine.schedules",
    "create_reminder": "engine.schedules", "manage_schedules": "database.schedules",
    "confirm_pending_transaction": "engine.confirm + database re-read", "cancel_pending_transaction": "engine.cancel",
    "show_info": "database (wallet, bills, contacts)", "request_human_support": "conversation status",
}

SCREENS = ["home", "transactions", "bills", "contacts", "providers", "services", "balance", "schedules",
           "notifications"]

_TIMING_PROPS = {
    "frequency": {"type": "string", "enum": ["once", "daily", "weekly", "monthly"],
                  "description": "once = a single future date; otherwise how often it repeats"},
    "day": {"type": "string", "description": "monthly: day of month 1-31 (31 = last day); weekly: weekday "
                                            "in Arabic (السبت، الأحد، ... الجمعة). Omit if unknown."},
    "date": {"type": "string", "description": "once: YYYY-MM-DD (compute from today_local in the state)"},
}

_FIELD_DOCS = {
    "wallet": "transfer: receiver wallet number, Iraqi mobile 07XXXXXXXXX",
    "contact_name": "transfer: name/relation of a saved contact (e.g. 'علي', 'ابني', 'أم علي') instead of a wallet",
    "amount": "Amount as a plain number. IQD for all services except western_union (USD)",
    "note": "transfer: optional note",
    "receiver_name": "western_union: receiver full name as on ID (first + father + surname)",
    "country": "western_union: destination country, Arabic name",
    "agent": "agent_withdraw / wallet_topup(agent): agent name or area (e.g. 'الكرادة')",
    "provider": "buy_card: card brand (زين إنترنت, ACCL, كورك, Google Play, PUBG UC, PlayStation, iTunes)",
    "method": "wallet_topup: 'وكيل' | 'فيزا' | 'مصرف'",
    "bank": "wallet_topup(bank): bank name",
    "account": "bill_payment: bill account/meter number; wallet_topup(bank): bank account number",
    "number": "mobile_topup: phone number to recharge, or 'self' for the user's own number",
    "carrier": "mobile_topup: زين | آسياسيل | كورك (normally auto-detected, omit)",
    "biller": "bill_payment: الكهرباء الوطنية | ماء بغداد | إنترنت الأرضي",
}

TOOLS: list[dict[str, Any]] = [
    {
        "type": "function",
        "function": {
            "name": "prepare_transaction",
            "description": (
                "Start or update a money operation and show it on the user's screen. Call it as soon as "
                "the user expresses an intent, with every field you can infer (partial is fine). Fields "
                "you pass are merged with what was collected before. Returns status: needs_info (ask for "
                "`awaiting` using `message`), ready (a confirmation card is on screen — ask the user to "
                "say أكّد), insufficient, needs_screen (user must type card details on screen), "
                "invalid_service."
            ),
            "parameters": {
                "type": "object",
                "properties": {
                    "service": {"type": "string", "enum": TRANSACTION_SERVICES},
                    "fields": {
                        "type": "object",
                        "properties": {
                            k: ({"type": "number", "description": d} if k == "amount"
                                else {"type": "string", "description": d})
                            for k, d in _FIELD_DOCS.items()
                        },
                    },
                },
                "required": ["service", "fields"],
            },
        },
    },
    {
        "type": "function",
        "function": {
            "name": "schedule_payment",
            "description": (
                "Create a recurring or future-dated payment (standing order) instead of paying now — use it "
                "whenever the user says كل شهر / كل أسبوع / يومياً / باجر / يوم 5 من كل شهر / أول كل شهر / "
                "تلقائياً. Only for: " + ", ".join(SCHEDULABLE) + ". Partial info is fine; fields and timing "
                "merge with what was collected. For bill_payment without an amount it pays whatever is due "
                "each time. Returns needs_info (ask for `awaiting`) or ready (confirmation card shown)."
            ),
            "parameters": {
                "type": "object",
                "properties": {
                    "service": {"type": "string", "enum": SCHEDULABLE},
                    "fields": {"type": "object", "properties": {
                        k: ({"type": "number", "description": d} if k == "amount" else {"type": "string", "description": d})
                        for k, d in _FIELD_DOCS.items() if k in ("wallet", "contact_name", "amount", "note", "number",
                                                                 "carrier", "biller", "account")}},
                    **_TIMING_PROPS,
                },
                "required": ["service"],
            },
        },
    },
    {
        "type": "function",
        "function": {
            "name": "create_reminder",
            "description": "A reminder without moving money (ذكرني / نبهني ...). note = what to remind about, "
                           "short Arabic phrase.",
            "parameters": {"type": "object", "properties": {"note": {"type": "string"}, **_TIMING_PROPS},
                           "required": ["note"]},
        },
    },
    {
        "type": "function",
        "function": {
            "name": "manage_schedules",
            "description": "List, stop (cancel), pause or resume the user's scheduled payments/reminders. Use the "
                           "schedule id from the state block.",
            "parameters": {
                "type": "object",
                "properties": {"action": {"type": "string", "enum": ["list", "cancel", "pause", "resume"]},
                               "schedule_id": {"type": "integer"}},
                "required": ["action"],
            },
        },
    },
    {
        "type": "function",
        "function": {
            "name": "confirm_pending_transaction",
            "description": "Execute the operation (or activate the schedule) waiting for confirmation. ONLY call "
                           "when the user's latest message explicitly confirms (أكد، نعم، اي، موافق، سويها...).",
            "parameters": {"type": "object", "properties": {}},
        },
    },
    {
        "type": "function",
        "function": {
            "name": "cancel_pending_transaction",
            "description": "Cancel the operation or schedule in progress (draft or waiting for confirmation).",
            "parameters": {"type": "object", "properties": {}},
        },
    },
    {
        "type": "function",
        "function": {
            "name": "show_info",
            "description": "Show information on screen and get the data: balance, transactions (history), "
                           "bills (due/paid), contacts, providers, services, home.",
            "parameters": {
                "type": "object",
                "properties": {"topic": {"type": "string", "enum": SCREENS}},
                "required": ["topic"],
            },
        },
    },
    {
        "type": "function",
        "function": {
            "name": "request_human_support",
            "description": "Hand the conversation to a human team. department=fraud for stolen money, a "
                           "transaction the user did not make, a hacked account or someone who scammed them; "
                           "department=customer_care for complaints, money that did not arrive, refunds, wrong "
                           "number, or when the user asks for a person or the problem needs follow-up.",
            "parameters": {
                "type": "object",
                "properties": {"reason": {"type": "string"},
                               "department": {"type": "string", "enum": ["customer_care", "fraud"]}},
                "required": ["reason"],
            },
        },
    },
]


class ToolExecutor:
    """Runs tools against the engine and records the resulting UI directive."""

    def __init__(self, engine: ActionEngine, user_text: str = ""):
        self.engine = engine
        self.user_text = user_text
        self.ui: Optional[dict] = None
        self.quick_replies: list[str] = []
        self.last_message: str = ""
        self.calls: list[dict] = []
        self.handover: bool = False
        self.department: Optional[str] = None
        self.sched = ScheduleManager(engine)

    def run(self, name: str, args: Optional[dict] = None) -> dict[str, Any]:
        args = args or {}
        try:
            result = self._dispatch(name, args)
        except Exception as exc:  # never let a tool crash the turn
            result = {"status": "error", "message": tr("صار خطأ بسيط، نعيد المحاولة؟", "Something went wrong, shall we try again?"),
                      "detail": str(exc)[:200]}
        self.calls.append({"name": name, "args": _safe_args(args), "status": result.get("status"),
                           "source": TOOL_SOURCES.get(name, "engine"), "at": iso(utcnow()),
                           **({"verified": result["verified"]} if result.get("verified") else {})})
        if result.get("message"):
            self.last_message = result["message"]
        return result

    # ------------------------------------------------------------------
    def _dispatch(self, name: str, args: dict) -> dict[str, Any]:
        e = self.engine
        if name == "prepare_transaction":
            fields = args.get("fields") if isinstance(args.get("fields"), dict) else {}
            fields = {k: v for k, v in fields.items() if k not in ("card_number", "cvv", "expiry")}
            res = e.prepare(args.get("service"), fields)
            self._ui_from_prepare(res)
            return _compact(res)

        if name in ("schedule_payment", "create_reminder"):
            timing = {k: args.get(k) for k in ("frequency", "day", "date")}
            if name == "create_reminder":
                res = self.sched.prepare(kind="reminder", note=args.get("note"), timing=timing)
            else:
                fields = args.get("fields") if isinstance(args.get("fields"), dict) else {}
                res = self.sched.prepare(kind="payment", service=args.get("service"), fields=fields, timing=timing)
            self._ui_from_schedule(res)
            return _compact_schedule(res)

        if name == "manage_schedules":
            action, sid = args.get("action") or "list", args.get("schedule_id")
            if action == "list" or not sid:
                return self._show_info("schedules")
            sid = int(sid)
            if action == "cancel":
                res = self.sched.cancel(sid)
            else:
                res = self.sched.set_paused(sid, action == "pause")
            self.ui = {"type": "screen", "screen": "schedules"}
            return _compact_schedule(res)

        if name == "confirm_pending_transaction":
            pending_s = self.sched.pending()
            if not e.pending_transaction() and not pending_s:
                return {"status": "no_pending", "message": tr("ماكو عملية بانتظار التأكيد.", "Nothing is waiting for confirmation.")}
            if self.user_text and not looks_affirmative(self.user_text):
                # code decides: the model may not execute anything unless the user's own words confirm
                return {"status": "not_confirmed_by_user",
                        "message": tr("المستخدم ما أكد صراحةً. اطلب منه يكول «أكّد» إذا كلشي صحيح.",
                                      "The user did not explicitly confirm. Ask them to say «confirm» if everything is right.")}
            if pending_s:
                res = self.sched.confirm(pending_s.id)
                self._ui_from_schedule(res)
                return _compact_schedule(res)
            res = e.confirm()
            self._ui_from_confirm(res)
            return _compact(res)

        if name == "cancel_pending_transaction":
            d = e.draft
            if self.sched.pending() or (d and d.get("mode") == "schedule"):
                res = self.sched.cancel()
            else:
                res = e.cancel()
            if res["status"] == "cancelled":
                self.ui = {"type": "home"}
            self.quick_replies = []
            return _compact(res)

        if name == "show_info":
            return self._show_info(args.get("topic") or "home")

        if name == "request_human_support":
            dept = args.get("department") if args.get("department") in ("customer_care", "fraud") else "customer_care"
            if dept == "fraud" and (e.pending_transaction() or e.draft):
                e.cancel()  # money safety: nothing stays ready to execute while fraud is being investigated
            if e.conv is not None:
                e.conv.status = "handover"
                e.conv.department = dept
                e.db.commit()
            self.handover = True
            self.department = dept
            self.ui = {"type": "handover", "department": dept}
            self.quick_replies = []
            if dept == "fraud":
                msg = tr("سلامتك، حوّلت محادثتك هسه لقسم مكافحة الاحتيال وراح يتابعون وياك بأسرع وقت. "
                         "لا تنطي أي رمز أو كلمة سر لأي أحد.",
                         "I'm sorry this happened. I've passed you to our fraud team and they'll follow up with you "
                         "very soon. Don't share any code or password with anyone.")
            else:
                msg = tr("تدلل، حوّلتك لموظف خدمة العملاء، راح يتابع وياك ويرد عليك هنا بأقرب وقت.",
                         "Sure, I've passed you to a customer-care agent; they'll follow up and reply here soon.")
            return {"status": "handed_over", "department": dept, "message": msg}

        return {"status": "unknown_tool", "message": ""}

    def _show_info(self, topic: str) -> dict[str, Any]:
        e = self.engine
        if topic in ("balance", "home"):
            s = e.wallet_summary()
            self.ui = {"type": "screen", "screen": "home"}
            return {"status": "ok", "balance": s["balance"], "balance_display": s["balance_display"],
                    "message": tr(f"رصيدك الحالي {s['balance_display']}.", f"Your balance is {s['balance_display']}.")}
        if topic == "transactions":
            items = e.recent_transactions(8)
            self.ui = {"type": "screen", "screen": "transactions"}
            if not items:
                return {"status": "ok", "items": [], "message": tr("ما عندك عمليات لحد الآن.", "You have no transactions yet.")}
            short = [f"{t['title']} {t['total_display']}" for t in items[:3]]
            return {"status": "ok", "items": items,
                    "message": tr("آخر عملياتك: ", "Your latest transactions: ") + "، ".join(short) + "."}
        if topic == "bills":
            bills = [b.public() for b in e.bills()]
            due = [b for b in bills if b["status"] == "due"]
            self.ui = {"type": "screen", "screen": "bills"}
            self.quick_replies = [tr(f"ادفع فاتورة {b['biller']}", f"Pay the {b['biller_label']} bill") for b in due][:3]
            if not due:
                return {"status": "ok", "bills": bills, "message": tr("كل فواتيرك مدفوعة.", "All your bills are paid.")}
            txt = "، ".join(f"{b['biller_label']} {fmt_iqd(b['amount_due'])}" for b in due)
            return {"status": "ok", "bills": bills, "message": tr(f"عندك فواتير مستحقة: {txt}.", f"Bills due: {txt}.")}
        if topic == "contacts":
            contacts = [c.public() for c in e.contacts()]
            self.ui = {"type": "screen", "screen": "contacts"}
            return {"status": "ok", "contacts": contacts,
                    "message": tr("جهات اتصالك: ", "Your contacts: ") + ", ".join(f"{c['name']} ({c['relation']})" for c in contacts) + "."}
        if topic == "schedules":
            items = [self.sched.public(s) for s in self.sched.list()]
            self.ui = {"type": "screen", "screen": "schedules"}
            if not items:
                self.quick_replies = [tr("حوّل لعلي 100 ألف أول كل شهر", "Send Ali 100,000 every month on day 1"),
                                      tr("ادفع الكهرباء كل شهر تلقائياً", "Pay electricity every month automatically")]
                return {"status": "ok", "schedules": [],
                        "message": tr("ما عندك دفعات مجدولة. تكدر تكلّي مثلاً: حوّل لعلي 100 ألف أول كل شهر.",
                                      "You have no scheduled payments. Try: send Ali 100,000 every month on day 1.")}
            short = "، ".join(f"{s['title']} {s['timing']}" for s in items[:3])
            return {"status": "ok", "schedules": [{k: s[k] for k in ("id", "title", "amount_display", "timing",
                                                                     "status", "next_run_display")} for s in items],
                    "message": tr(f"عندك {len(items)} مجدولة: {short}.", f"You have {len(items)} scheduled: {short}.")}
        if topic == "notifications":
            generate_reminders(e.db)
            items = unread_notifications(e.db, e.user.id, 5)
            self.ui = {"type": "screen", "screen": "notifications"}
            if not items:
                return {"status": "ok", "notifications": [], "message": tr("ما عندك تنبيهات جديدة.", "No new notifications.")}
            pubs = [n.public() for n in items]
            return {"status": "ok", "notifications": [{"title": n["title"], "body": n["body"]} for n in pubs],
                    "message": tr("تنبيهاتك: ", "Your notifications: ") + "، ".join(n["title"] for n in pubs[:3]) + "."}
        if topic == "providers":
            self.ui = {"type": "screen", "screen": "providers"}
            return {"status": "ok", "providers": [disp(p["name"]) for p in PROVIDERS_LIST],
                    "message": tr("هذني مزودي الخدمة.", "These are the service providers.")}
        self.ui = {"type": "screen", "screen": "home"}
        names = [SERVICES[k].name_t for k in TRANSACTION_SERVICES]
        return {"status": "ok", "services": names, "message": tr("أكدر أساعدك بـ: ", "I can help with: ") + ", ".join(names) + "."}

    def _ui_from_prepare(self, res: dict) -> None:
        st = res.get("status")
        if st == "ready":
            self.ui = {"type": "confirm", "action": res["action"]}
            self.quick_replies = [tr("أكّد", "Confirm"), tr("إلغاء", "Cancel")]
        elif st in ("needs_info", "insufficient", "needs_screen"):
            self.ui = {"type": "form", "service": res["service"], "fields": res.get("fields", {}),
                       "awaiting": res.get("awaiting"), "errors": res.get("errors", {}),
                       "secure_input": st == "needs_screen"}
            self.quick_replies = list(res.get("choices") or [])[:6]
            if tr("إلغاء", "Cancel") not in self.quick_replies:
                self.quick_replies.append(tr("إلغاء", "Cancel"))

    def _ui_from_schedule(self, res: dict) -> None:
        st = res.get("status")
        if st == "ready":
            self.ui = {"type": "confirm_schedule", "schedule": res["schedule"]}
            self.quick_replies = [tr("أكّد", "Confirm"), tr("إلغاء", "Cancel")]
        elif st == "needs_info":
            self.ui = {"type": "schedule_form", "kind": res.get("kind"), "service": res.get("service"),
                       "fields": res.get("fields", {}), "timing": res.get("timing", {}),
                       "awaiting": res.get("awaiting")}
            self.quick_replies = list(res.get("choices") or [])[:6] + [tr("إلغاء", "Cancel")]
        elif st == "activated":
            self.ui = {"type": "schedule_active", "schedule": res["schedule"]}
            self.quick_replies = [tr("مدفوعاتي المجدولة", "My scheduled payments")]

    def _ui_from_confirm(self, res: dict) -> None:
        if res.get("status") == "completed":
            self.ui = {"type": "receipt", "action": res["action"]}
            self.quick_replies = [tr("رصيدي", "My balance"), tr("آخر العمليات", "Recent transactions")]
        elif res.get("action"):
            self.ui = {"type": "confirm", "action": res["action"]}


def _compact(res: dict) -> dict:
    """Trim engine results before sending them back to the LLM."""
    out = {k: v for k, v in res.items() if k not in ("action",)}
    action = res.get("action")
    if action:
        out["action"] = {k: action.get(k) for k in ("reference", "service", "status", "amount_display",
                                                       "total_display", "balance_after_display", "warnings")}
        out["action"]["details"] = {line["label"]: line["value"] for line in action.get("lines", [])}
        if action.get("result"):
            out["action"]["result"] = {k: v for k, v in action["result"].items() if k != "balance_after"}
    return out


def _compact_schedule(res: dict) -> dict:
    out = {k: v for k, v in res.items() if k != "schedule"}
    s = res.get("schedule")
    if s:
        out["schedule"] = {k: s.get(k) for k in ("id", "title", "amount_display", "timing", "status",
                                                  "next_run_display")}
    return out


def _safe_args(args: dict) -> dict:
    """Never persist card details that might slip into tool arguments."""
    fields = dict(args.get("fields") or {}) if isinstance(args.get("fields"), dict) else None
    if fields is not None:
        for k in ("card_number", "cvv", "expiry"):
            if k in fields:
                fields[k] = "***"
        return {**args, "fields": fields}
    return dict(args)

backend/agent/voice.py:
"""Voice layer: choose the best speech-recognition hypothesis and fix common recognition slips.

Browsers return several alternatives for one utterance (n-best). The one the recogniser ranks first is not
always the one that makes sense for a wallet ("حول لعلي" vs "حول العلي"). Each hypothesis is scored with
the intent classifier and the domain vocabulary, and the clearest one wins (ties keep the recogniser's choice).

`correct()` then maps near-miss words onto the wallet vocabulary ("وسترن يونين" -> "ويسترن يونيون",
"فاتوره الكهربا" -> "فاتورة الكهرباء"). It only touches words of 5+ letters that are very close to a known
word, so ordinary words are left alone.
"""
from __future__ import annotations

from difflib import SequenceMatcher
from typing import Iterable, Optional

from ..catalog import (AGENT_SYNONYMS, BILLER_SYNONYMS, CARD_PROVIDER_SYNONYMS, COUNTRY_SYNONYMS)
from ..textnorm import normalize, parse_amount

DOMAIN_WORDS = [
    "ويسترن", "يونيون", "فاتوره", "فاتورة", "فواتير", "الكهرباء", "كهرباء", "الانترنت", "تحويل", "حوالة", "حواله",
    "رصيدي", "الرصيد", "المحفظه", "محفظتي", "اشحن", "اشحنلي", "اسحب", "اسحبلي", "الوكيل", "ادفعلي", "سددلي",
    "دولار", "دينار", "مليون", "تأكيد", "الغاء", "الغيها", "اكدها", "موافق", "بطاقة", "ببجي", "ايتونز",
    "بلايستيشن", "اسياسيل", "تنبيهات", "الاشعارات", "المجدولة", "تلقائيا", "احتيال", "موظف", "العملاء",
    "western", "union", "transfer", "balance", "confirm", "cancel", "electricity", "internet", "recharge",
]


def _lexicon(extra: Iterable[str] = ()) -> dict[str, str]:
    words: dict[str, str] = {}
    for group in (AGENT_SYNONYMS, BILLER_SYNONYMS, CARD_PROVIDER_SYNONYMS, COUNTRY_SYNONYMS):
        for key, syns in group.items():
            for w in [key, *syns]:
                for tok in str(w).split():
                    n = normalize(tok)
                    if len(n) >= 5:
                        words.setdefault(n, tok)
    for w in [*DOMAIN_WORDS, *extra]:
        for tok in str(w).split():
            n = normalize(tok)
            if len(n) >= 4:
                words.setdefault(n, tok)
    return words


_BASE: Optional[dict[str, str]] = None


def correct(text: str, extra_words: Iterable[str] = (), threshold: float = 0.84) -> tuple[str, list[list[str]]]:
    """Return (corrected text, [[heard, corrected], ...])."""
    global _BASE
    if _BASE is None:
        _BASE = _lexicon()
    lex = dict(_BASE)
    lex.update(_lexicon(extra_words))
    out, changes = [], []
    for tok in (text or "").split():
        n = normalize(tok)
        if len(n) < 5 or n in lex or any(ch.isdigit() for ch in n):
            out.append(tok)
            continue
        best, score = None, 0.0
        for cand_n, cand in lex.items():
            if abs(len(cand_n) - len(n)) > 2 or cand_n[0] != n[0]:
                continue
            r = SequenceMatcher(None, n, cand_n).ratio()
            if r > score:
                best, score = cand, r
        if best is not None and score >= threshold:
            out.append(best)
            changes.append([tok, best])
        else:
            out.append(tok)
    return " ".join(out), changes


def pick_best(primary: str, alternatives: Iterable[str]) -> tuple[str, list[dict]]:
    """Choose the clearest hypothesis. Returns (text, scored candidates)."""
    from .nlu import classify

    cands = []
    for i, t in enumerate([primary, *[a for a in alternatives if a]]):
        t = (t or "").strip()
        if not t or any(c["text"] == t for c in cands):
            continue
        p = classify(t)
        score = p.confidence + (0.15 if p.rule else 0.0) + (0.05 if parse_amount(t) else 0.0) + (0.06 if i == 0 else 0.0)
        cands.append({"text": t, "intent": p.intent, "confidence": round(p.confidence, 3), "score": round(score, 3)})
    if not cands:
        return primary, []
    best = max(cands, key=lambda c: c["score"])
    return best["text"], cands

backend/api.py:
"""The wallet API as plain Python: `dispatch(Request) -> (status, payload)`.

No web framework in here on purpose: the FastAPI server (main.py) and the in-browser build
(static_bridge.py) call the very same `dispatch`, so both run identical code, and the browser
does not have to download FastAPI / pydantic / starlette at startup.
"""
from __future__ import annotations

import re
from dataclasses import dataclass, field
from typing import Any, Callable, Optional

from sqlalchemy import select, update
from sqlalchemy.orm import Session

from . import __version__
from .agent.orchestrator import Assistant, get_or_create_conversation
from .catalog import public_catalog
from .config import get_settings
from .db import SessionLocal
from .engine import ActionEngine
from .i18n import lang as ui_lang, tr, using
from .models import Conversation, Message, Notification, Schedule, Transaction, User
from .schedules import SCHEDULABLE, ScheduleManager, generate_reminders
from .seed import get_demo_user


class HTTPError(Exception):
    def __init__(self, status: int, detail: str):
        super().__init__(detail)
        self.status, self.detail = status, detail


@dataclass
class Request:
    method: str
    path: str
    query: dict = field(default_factory=dict)
    body: Any = None
    headers: dict = field(default_factory=dict)  # lower-case keys
    client_host: str = "127.0.0.1"

    @property
    def lang(self) -> str:
        return self.query.get("lang") or self.headers.get("x-lang") or ""

    def json(self) -> dict:
        return self.body if isinstance(self.body, dict) else {}


ROUTES: list[tuple[str, re.Pattern, Callable, bool]] = []


def route(method: str, pattern: str, *, admin: bool = False):
    rx = re.compile("^" + re.sub(r"{(\w+)}", r"(?P<\1>[^/]+)", pattern) + "$")

    def deco(fn):
        ROUTES.append((method, rx, fn, admin))
        return fn
    return deco


def dispatch(req: Request) -> tuple[int, Any]:
    from .admin import require_admin  # noqa: F401  (registers the admin routes)

    with using(req.lang):
        for method, rx, fn, admin in ROUTES:
            m = rx.match(req.path)
            if not m or method != req.method.upper():
                continue
            try:
                if admin:
                    require_admin(req)
                with SessionLocal() as db:
                    return 200, fn(db, req, **m.groupdict())
            except HTTPError as e:
                return e.status, {"detail": e.detail}
        return 404, {"detail": "not found"}


# --------------------------------------------------------------------------- helpers

def _user(db: Session) -> User:
    return get_demo_user(db)


def _int(v: Any, default: int, lo: int, hi: int) -> int:
    try:
        return max(lo, min(int(v), hi))
    except (TypeError, ValueError):
        return default


def _str(body: dict, key: str, max_len: int, required: bool = False) -> Optional[str]:
    v = body.get(key)
    if v is None or v == "":
        if required:
            raise HTTPError(422, f"{key} is required")
        return None
    if not isinstance(v, str) or len(v) > max_len:
        raise HTTPError(422, f"{key} is invalid")
    return v


LOCAL_HOSTS = {"127.0.0.1", "::1", "localhost", "testclient"}


def _private_ok(req: Optional["Request"]) -> bool:
    """May a browser-chosen model point at a local / private address? Only on GitHub Pages (the request never
    leaves the browser) or when the server is used from its own machine."""
    import os

    if os.environ.get("STATIC_BUILD") or req is None:
        return True
    proxied = any(h in req.headers for h in ("x-forwarded-for", "x-real-ip", "forwarded"))
    return req.client_host in LOCAL_HOSTS and not proxied


def browser_llm(req: Optional["Request"]):
    """The model the visitor chose in the app (header X-LLM-Config, or X-LLM-Key from an older private link).
    Returns (mode, client): ('offline', None) = use the built-in agent, ('llm', client), or (None, None)."""
    from .llm import browser_client, browser_config

    if req is None:
        return None, None
    raw = req.headers.get("x-llm-config") or req.headers.get("x-llm-key") or ""
    if not raw:
        return None, None
    mode, configs = browser_config(raw, get_settings(), _private_ok(req))
    if mode == "llm":
        return mode, browser_client(get_settings(), configs)
    return mode, None


def agent_info(req: Optional["Request"] = None) -> dict[str, Any]:
    s = get_settings()
    from .agent import nlu
    from .llm import get_client

    client = get_client(s)
    mode, chosen = browser_llm(req)
    if mode == "llm":
        c = chosen.configs[0]
        return {"llm_enabled": True, "model": f"{c.provider} · {c.model}", "mode": "llm", "source": "browser",
                "stt_enabled": s.stt_enabled,
                "orchestrator": {"classifier": "loaded" if nlu.model() is not None else "rules only",
                                 "intents": len(nlu.INTENTS), "fast_path": s.orch_fast_path,
                                 "reply_language": s.reply_language, "llm_chain": chosen.health()}}
    if mode == "offline":
        client = None
    enabled = s.llm_enabled and mode != "offline"
    return {"llm_enabled": enabled, "model": s.llm_label if enabled else None,
            "mode": "llm" if enabled else "offline", "source": "server" if enabled else None,
            "stt_enabled": s.stt_enabled,
            "orchestrator": {"classifier": "loaded" if nlu.model() is not None else "rules only",
                             "intents": len(nlu.INTENTS), "fast_path": s.orch_fast_path,
                             "reply_language": s.reply_language,
                             "llm_chain": client.health() if client is not None else []}}


def _sched_payload(db: Session, user: User) -> dict[str, Any]:
    generate_reminders(db)
    sm = ScheduleManager(ActionEngine(db, user))
    notes = db.scalars(select(Notification).where(Notification.user_id == user.id)
                       .order_by(Notification.id.desc()).limit(30)).all()
    return {"schedules": [sm.public(s) for s in sm.list()],
            "notifications": [n.public() for n in notes],
            "unread": sum(1 for n in notes if not n.read)}


def _reply_payload(db: Session, user: User, res: dict) -> dict:
    db.refresh(user)
    return {**res, "reply": res["message"], "balance": user.balance}


# --------------------------------------------------------------------------- wallet

@route("GET", "/api/health")
def health(db, req):
    return {"status": "ok", "version": __version__, "agent": agent_info(req)}


@route("GET", "/api/bootstrap")
def bootstrap(db, req):
    s, user = get_settings(), _user(db)
    engine = ActionEngine(db, user)
    return {
        "app": {"name": s.app_name, "name_ar": s.app_name_ar, "version": __version__, "usd_to_iqd": s.usd_to_iqd},
        "user": engine.wallet_summary(),
        "catalog": public_catalog(),
        "transactions": engine.recent_transactions(20),
        "bills": [b.public() for b in engine.bills()],
        "contacts": [c.public() for c in engine.contacts()],
        "agent": agent_info(req),
        "schedulable": SCHEDULABLE,
        **_sched_payload(db, user),
    }


@route("GET", "/api/wallet")
def wallet(db, req):
    user = _user(db)
    engine = ActionEngine(db, user)
    return {**engine.wallet_summary(), "bills": [b.public() for b in engine.bills()],
            "transactions": engine.recent_transactions(20), **_sched_payload(db, user)}


@route("GET", "/api/transactions")
def transactions(db, req):
    return {"items": ActionEngine(db, _user(db)).recent_transactions(_int(req.query.get("limit"), 30, 1, 200))}


# --------------------------------------------------------------------------- manual (screen) actions

@route("POST", "/api/actions")
def create_action(db, req):
    body, user = req.json(), _user(db)
    service = _str(body, "service", 40, required=True)
    fields = body.get("fields") if isinstance(body.get("fields"), dict) else {}
    conv_id = _str(body, "conversation_id", 40)
    conv = db.get(Conversation, conv_id) if conv_id else None
    res = ActionEngine(db, user, conv).prepare(service, fields, merge=False, source="manual")
    if res["status"] == "invalid_service":
        raise HTTPError(400, res["message"])
    return res


def _tx_and_conv(db: Session, user: User, tx_id: str) -> tuple[Transaction, Optional[Conversation]]:
    tx = db.get(Transaction, _int(tx_id, 0, 0, 10**12))
    if not tx or tx.user_id != user.id:
        raise HTTPError(404, tr("العملية غير موجودة", "Operation not found"))
    return tx, (db.get(Conversation, tx.conversation_id) if tx.conversation_id else None)


@route("POST", "/api/actions/{tx_id}/confirm")
def confirm_action(db, req, tx_id):
    user = _user(db)
    tx, conv = _tx_and_conv(db, user, tx_id)
    res = ActionEngine(db, user, conv).confirm(tx.id)
    if conv is not None:
        Assistant(db, llm=False).log_event(conv, f"user confirmed {tx.reference} on screen", {"status": res["status"]})
        ui = {"type": "receipt", "action": res["action"]} if res["status"] == "completed" else None
        trace = [{"name": "screen_confirm", "status": res["status"], "source": "engine.confirm + database re-read",
                  **({"verified": res["verified"]} if res.get("verified") else {})}]
        db.add(Message(conversation_id=conv.id, role="assistant", content=res["message"],
                       meta={"ui": ui, "mode": "ui", "tools": trace, "lang": ui_lang()}))
        db.commit()
    return _reply_payload(db, user, res)


@route("POST", "/api/actions/{tx_id}/cancel")
def cancel_action(db, req, tx_id):
    user = _user(db)
    tx, conv = _tx_and_conv(db, user, tx_id)
    res = ActionEngine(db, user, conv).cancel(tx.id)
    if conv is not None and res["status"] == "cancelled":
        Assistant(db, llm=False).log_event(conv, f"user cancelled {tx.reference} on screen")
        db.add(Message(conversation_id=conv.id, role="assistant", content=res["message"],
                       meta={"ui": {"type": "home"}, "mode": "ui", "tools": [], "lang": ui_lang()}))
        db.commit()
    return _reply_payload(db, user, res)


@route("GET", "/api/actions/{tx_id}")
def get_action(db, req, tx_id):
    user = _user(db)
    tx, conv = _tx_and_conv(db, user, tx_id)
    return {"action": ActionEngine(db, user, conv).public_tx(tx), "balance": user.balance}


# --------------------------------------------------------------------------- schedules & notifications

def _sched_mgr(db: Session, user: User, sid: Optional[str] = None,
               conv_id: Optional[str] = None) -> tuple[ScheduleManager, Optional[Conversation]]:
    conv = None
    if sid:
        s = db.get(Schedule, _int(sid, 0, 0, 10**12))
        if not s or s.user_id != user.id:
            raise HTTPError(404, tr("الجدولة غير موجودة", "Schedule not found"))
        conv = db.get(Conversation, s.conversation_id) if s.conversation_id else None
    elif conv_id:
        conv = db.get(Conversation, conv_id)
    return ScheduleManager(ActionEngine(db, user, conv)), conv


@route("GET", "/api/schedules")
def list_schedules(db, req):
    sm, _ = _sched_mgr(db, _user(db))
    return {"items": [sm.public(s) for s in sm.list(req.query.get("include_inactive") in ("1", "true"))]}


@route("GET", "/api/schedules/{sid}")
def get_schedule(db, req, sid):
    sm, _ = _sched_mgr(db, _user(db), sid)
    return {"schedule": sm.public(sm.get(int(sid)))}


@route("POST", "/api/schedules")
def create_schedule(db, req):
    body, user = req.json(), _user(db)
    kind = body.get("kind") if body.get("kind") in ("payment", "reminder") else "payment"
    sm, _ = _sched_mgr(db, user, conv_id=_str(body, "conversation_id", 40))
    res = sm.prepare(kind=kind, service=_str(body, "service", 40),
                     fields=body.get("fields") if isinstance(body.get("fields"), dict) else {},
                     timing={"frequency": body.get("frequency"), "day": body.get("day"), "date": body.get("date")},
                     note=_str(body, "note", 200), merge=False, source="manual")
    if res["status"] == "invalid_service":
        raise HTTPError(400, res["message"])
    return res


@route("POST", "/api/schedules/{sid}/{action}")
def schedule_action(db, req, sid, action):
    user = _user(db)
    sm, conv = _sched_mgr(db, user, sid)
    sid_i = int(sid)
    if action == "confirm":
        res = sm.confirm(sid_i)
    elif action == "cancel":
        res = sm.cancel(sid_i)
    elif action in ("pause", "resume"):
        res = sm.set_paused(sid_i, action == "pause")
    elif action == "run-now":
        res = sm.run_now(sid_i)
    else:
        raise HTTPError(404, "unknown action")
    if conv is not None and action in ("confirm", "cancel") and res["status"] in ("activated", "cancelled"):
        Assistant(db, llm=False).log_event(conv, f"user {action}ed schedule #{sid} on screen")
        ui = {"type": "schedule_active", "schedule": res["schedule"]} if action == "confirm" else {"type": "home"}
        db.add(Message(conversation_id=conv.id, role="assistant", content=res["message"],
                       meta={"ui": ui, "mode": "ui", "tools": [], "lang": ui_lang()}))
        db.commit()
    return _reply_payload(db, user, res)


@route("GET", "/api/notifications")
def notifications(db, req):
    p = _sched_payload(db, _user(db))
    return {"items": p["notifications"], "unread": p["unread"]}


@route("POST", "/api/notifications/read")
def notifications_read(db, req):
    user = _user(db)
    db.execute(update(Notification).where(Notification.user_id == user.id, Notification.read.is_(False)).values(read=True))
    db.commit()
    return {"ok": True}


# --------------------------------------------------------------------------- assistant

@route("POST", "/api/assistant/conversations")
def new_conversation(db, req):
    conv = get_or_create_conversation(db, _user(db), None)
    return {"conversation_id": conv.id, "status": conv.status}


@route("GET", "/api/assistant/conversations/{conv_id}")
def get_conversation(db, req, conv_id):
    user = _user(db)
    conv = db.get(Conversation, conv_id)
    if not conv or conv.user_id != user.id:
        raise HTTPError(404, tr("المحادثة غير موجودة", "Conversation not found"))
    after = _int(req.query.get("after"), 0, 0, 10**12)
    msgs = db.scalars(select(Message).where(Message.conversation_id == conv_id, Message.id > after)
                      .order_by(Message.id)).all()
    engine = ActionEngine(db, user, conv)
    return {"conversation_id": conv.id, "status": conv.status,
            "messages": [m.public() for m in msgs if m.role != "event"],
            "pending": engine.public_tx(engine.pending_transaction())}


@route("POST", "/api/assistant/message")
def assistant_message(db, req):
    body = req.json()
    text = _str(body, "text", 1000, required=True)
    channel = body.get("channel") or "text"
    if channel not in ("text", "voice"):
        raise HTTPError(422, "channel must be text or voice")
    alts = body.get("alternatives")
    alts = [a for a in alts if isinstance(a, str)][:5] if isinstance(alts, list) and channel == "voice" else None
    conv = get_or_create_conversation(db, _user(db), _str(body, "conversation_id", 40))
    return assistant_for(db, req).handle_message(conv, text, channel=channel, alternatives=alts)


def assistant_for(db: Session, req: Optional["Request"]) -> Assistant:
    """The assistant with the model the visitor chose in the browser, else the server's own chain."""
    mode, client = browser_llm(req)
    if mode == "llm":
        return Assistant(db, llm=client)
    if mode == "offline":
        return Assistant(db, llm=False)
    return Assistant(db)


@route("POST", "/api/ai/test")
def ai_test(db, req):
    """«Test» button of the app's AI settings: one tiny call with the settings the browser just sent."""
    import time

    from .llm import LLMError

    from .llm import get_client

    mode, client = browser_llm(req)
    if mode is None and (req.headers.get("x-llm-config") or req.headers.get("x-llm-key")):
        raise HTTPError(422, tr("الإعدادات ناقصة: اختار المزود واكتب المفتاح.", "Incomplete settings: pick a provider and enter the key."))
    if mode is None:  # «this app's default»: the server's own chain, or the built-in agent
        client = get_client(get_settings())
        mode = "llm" if client is not None else "offline"
    if mode == "offline":
        return {"ok": True, "model": "offline", "reply": "ok"}
    single = type(client)(get_settings(), client.configs[:1])
    t0 = time.perf_counter()
    try:
        res = single.ping()
        return {**res, "latency_ms": int((time.perf_counter() - t0) * 1000)}
    except LLMError as exc:
        key = client.configs[0].api_key
        msg = str(exc).replace(key, "****") if key else str(exc)
        return {"ok": False, "model": f"{client.configs[0].provider}:{client.configs[0].model}", "error": msg[:300]}

backend/config.py:
"""Application settings from environment variables / the .env file (standard library only).

No pydantic-settings: the same module runs on the server and inside the browser (Pyodide),
and every dependency we drop makes the browser build start faster.
"""
from __future__ import annotations

import os
from dataclasses import dataclass, field, fields
from functools import lru_cache
from pathlib import Path

ROOT_DIR = Path(__file__).resolve().parent.parent
DATA_DIR = ROOT_DIR / "data"
FRONTEND_DIR = ROOT_DIR / "frontend"


def _read_env_file(path: Path) -> dict[str, str]:
    out: dict[str, str] = {}
    try:
        text = path.read_text(encoding="utf-8")
    except OSError:
        return out
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        k, v = line.split("=", 1)
        v = v.strip()
        if len(v) >= 2 and v[0] == v[-1] and v[0] in "'\"":
            v = v[1:-1]
        out[k.strip().upper()] = v
    return out


@dataclass
class Settings:
    # Branding
    app_name: str = "Pay Transfer Agent"
    app_name_ar: str = "باي ترانسفير"

    # Database (SQLite by default; any SQLAlchemy URL works, e.g. PostgreSQL)
    database_url: str = f"sqlite:///{(DATA_DIR / 'wallet.db').as_posix()}"
    sqlite_wal: bool = True

    # ---- LLM (any provider): see backend/llm.py for the provider list
    # LLM_PROVIDER: openai | deepseek | groq | openrouter | gemini | mistral | together | xai |
    #               anthropic | ollama | lmstudio | vllm | llamacpp | custom   (empty = auto-detect)
    llm_provider: str = ""
    llm_model: str = ""
    llm_api_key: str = ""
    llm_base_url: str = ""
    # Backup chain, tried in order when the main model fails:  "groq:llama-3.3-70b-versatile,ollama:qwen2.5:7b"
    # Keys come from <PROVIDER>_API_KEY (e.g. GROQ_API_KEY) or LLM_API_KEY.
    llm_fallbacks: str = ""
    # native = OpenAI-style tool calling; json = model answers with a JSON object we parse and validate
    # (for local / small models without tool support); auto = native, switching to json if rejected
    llm_tool_mode: str = "auto"
    llm_timeout_seconds: float = 40.0
    # Local models (Ollama, LM Studio, vLLM, llama.cpp) can be slow on a laptop CPU, especially the first answer
    llm_local_timeout_seconds: float = 120.0
    llm_temperature: float = 0.2
    llm_max_tokens: int = 700
    # Rough price per 1M tokens (USD) for the cost-per-request estimate in the admin / eval report
    llm_price_in_per_m: float = 0.0
    llm_price_out_per_m: float = 0.0

    # Legacy names (still honoured): DEEPSEEK_API_KEY / DEEPSEEK_MODEL / DEEPSEEK_BASE_URL
    deepseek_api_key: str = ""
    deepseek_model: str = ""
    deepseek_base_url: str = ""
    deepseek_fallback_models: str = ""

    # auto = LLM when configured, otherwise the built-in offline agent; llm = always try the LLM;
    # offline = never call an LLM
    agent_mode: str = "auto"
    history_window: int = 16

    # ---- Orchestrator (backend/agent/orchestrator.py)
    # auto = the assistant replies (text, chat cards, read-aloud) in the language of each message; the app UI keeps
    #        the language the user picked with the ع / EN button and never switches by itself. A message with no
    #        clear language ("ok", "👍", a number) keeps the conversation's language.
    # ui   = the assistant always replies in the app language, whatever the message language.
    reply_language: str = "auto"
    # Fast path: clear, high-confidence requests (balance, history, greetings, one-shot transfers the rules fully
    # understand, confirm/cancel, fraud reports) are handled in milliseconds without waiting for the LLM.
    orch_fast_path: bool = True
    # Minimum classifier confidence for the fast path and for automatic department hand-over
    orch_fast_confidence: float = 0.85
    orch_handover_confidence: float = 0.80
    # Ping every LLM endpoint at start-up and every N minutes so failover is instant (0 = off)
    llm_keepalive_minutes: int = 10

    # Speech-to-text for recorded voice notes (OpenAI-compatible /audio/transcriptions).
    # Leave empty to use the browser's built-in speech recognition instead.
    stt_api_key: str = ""
    stt_base_url: str = "https://api.groq.com/openai/v1"
    stt_model: str = "whisper-large-v3"

    # Admin dashboard protection. Empty = admin API reachable from localhost only.
    admin_token: str = ""
    # Comma-separated origins allowed to call the API from other sites (empty = same-origin only)
    cors_origins: str = ""
    # Max assistant messages / voice notes per client IP per minute (protects your LLM credit); 0 = off
    rate_limit_per_minute: int = 30

    # Business parameters (demo values)
    demo_user_name: str = "محمد تيمور"
    usd_to_iqd: int = 1310
    starting_balance: int = 1_500_000
    pending_ttl_minutes: int = 15

    # Scheduler (recurring payments & reminders). Times are Baghdad local time (UTC+3).
    scheduler_enabled: bool = True
    scheduler_interval_seconds: int = 30
    schedule_run_hour: int = 9
    bill_reminder_days: int = 3

    extra: dict = field(default_factory=dict, repr=False)  # every raw env value (provider keys etc.)

    # ------------------------------------------------------------------ derived
    def env(self, name: str, default: str = "") -> str:
        return self.extra.get(name.upper(), default)

    @property
    def llm(self):
        from .llm import resolve_config

        return resolve_config(self)

    @property
    def llm_enabled(self) -> bool:
        return self.agent_mode.lower() != "offline" and self.llm is not None

    @property
    def llm_label(self) -> str:
        c = self.llm
        return f"{c.provider} · {c.model}" if c else ""

    @property
    def stt_enabled(self) -> bool:
        return bool(self.stt_api_key.strip())

    @property
    def cors_origin_list(self) -> list[str]:
        return [o.strip() for o in self.cors_origins.split(",") if o.strip()]


def _coerce(raw: str, current):
    if isinstance(current, bool):
        return raw.strip().lower() in ("1", "true", "yes", "on")
    if isinstance(current, int):
        return int(float(raw))
    if isinstance(current, float):
        return float(raw)
    return raw


# ---- LLM settings edited from the admin dashboard (API keys, primary model, fallback chain).
# Stored on the server only (data/ is git-ignored), never sent back to a browser unmasked. They take precedence
# over .env so a change in the dashboard applies at once, without a restart.
LLM_OVERRIDABLE = ("llm_provider", "llm_model", "llm_base_url", "llm_fallbacks", "agent_mode",
                   "deepseek_fallback_models")


def llm_overrides_path() -> Path:
    return Path(os.environ.get("LLM_SETTINGS_FILE") or (DATA_DIR / "llm_settings.json"))


def read_llm_overrides() -> dict:
    if os.environ.get("STATIC_BUILD"):
        return {}
    try:
        import json

        data = json.loads(llm_overrides_path().read_text(encoding="utf-8"))
        return data if isinstance(data, dict) else {}
    except (OSError, ValueError):
        return {}


def write_llm_overrides(data: dict) -> None:
    import json

    path = llm_overrides_path()
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(".tmp")
    tmp.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
    try:
        os.chmod(tmp, 0o600)  # owner-only where the OS supports it
    except OSError:  # pragma: no cover
        pass
    os.replace(tmp, path)
    get_settings.cache_clear()


@lru_cache
def get_settings() -> Settings:
    values = {**_read_env_file(ROOT_DIR / ".env"), **{k.upper(): v for k, v in os.environ.items()}}
    overrides = read_llm_overrides()
    for group in ("keys", "urls"):  # API keys and local-server URLs (e.g. OLLAMA_BASE_URL)
        for k, v in (overrides.get(group) or {}).items():
            if isinstance(v, str):
                values[k.upper()] = v
    for k in LLM_OVERRIDABLE:
        if isinstance(overrides.get(k), str):
            values[k.upper()] = overrides[k]
    s = Settings(extra=values)
    for f in fields(Settings):
        if f.name == "extra":
            continue
        raw = values.get(f.name.upper())
        if raw is None:
            continue
        try:
            setattr(s, f.name, _coerce(raw, getattr(s, f.name)))
        except ValueError:
            pass  # keep the default on a malformed value
    return s

backend/engine.py:
"""Transaction engine — validation, drafts (slot filling), fees, confirmation and execution.

Both the AI agent and the manual screens go through this class, so business rules live in
exactly one place. Code decides: amounts, fees, balance checks and limits are computed here,
never by the language model. Money only moves inside `confirm()`, and only for a transaction
that is still pending after an atomic status claim.
"""
from __future__ import annotations

import random
import re
from datetime import timedelta
from typing import Any, Optional

from sqlalchemy import select, update
from sqlalchemy.orm import Session

from .catalog import SERVICES, TRANSACTION_SERVICES, Field, Service, fee_for, get_service
from .config import get_settings
from .i18n import disp, tr
from .models import Bill, Contact, Conversation, Schedule, Transaction, User, iso, utcnow
from .textnorm import (
    carrier_from_phone, luhn_ok, match_choice, normalize, parse_amount, phrase_in,
    similarity, to_ascii_digits, to_local_phone,
)

SELF_WORDS = {"self", "me", "mine", "my", "own", "my number", "رقمي", "رصيدي", "خطي", "الي", "لي", "انا", "نفسي",
              "لنفسي", "رقمي انا", "موبايلي", "تلفوني", "جوالي"}
SELF_WORDS = {normalize(w) for w in SELF_WORDS}

STATUS = {"pending": ("بانتظار التأكيد", "Waiting for confirmation"), "completed": ("مكتملة", "Completed"),
          "cancelled": ("ملغاة", "Cancelled"), "expired": ("منتهية الصلاحية", "Expired"),
          "failed": ("فشلت", "Failed"), "processing": ("قيد التنفيذ", "Processing")}


def status_label(status: str) -> str:
    ar, en = STATUS.get(status, (status, status))
    return tr(ar, en)


# --------------------------------------------------------------------------- formatting

def fmt_iqd(v: float) -> str:
    return f"{int(round(v)):,} " + tr("د.ع", "IQD")


def fmt_usd(v: float) -> str:
    s = f"{v:,.2f}"
    if s.endswith(".00"):
        s = s[:-3]
    return f"${s}"


def fmt_money(v: float, currency: str) -> str:
    return fmt_usd(v) if currency == "USD" else fmt_iqd(v)


def fmt_phone(p: str) -> str:
    return f"{p[:4]} {p[4:7]} {p[7:]}" if p and len(p) == 11 else (p or "")


def _digits(n: int) -> str:
    return "".join(random.choice("0123456789") for _ in range(n))


class ActionEngine:
    def __init__(self, db: Session, user: User, conversation: Optional[Conversation] = None):
        self.db = db
        self.user = user
        self.conv = conversation
        self.settings = get_settings()

    # ------------------------------------------------------------------ draft state
    @property
    def draft(self) -> Optional[dict]:
        return (self.conv.draft or None) if self.conv is not None else None

    def _save_draft(self, d: Optional[dict]) -> None:
        if self.conv is not None:
            self.conv.draft = dict(d) if d else None

    def clear_draft(self) -> None:
        self._save_draft(None)

    # ------------------------------------------------------------------ lookups
    def contacts(self) -> list[Contact]:
        return list(self.user.contacts)

    def contact_by_wallet(self, wallet: str) -> Optional[Contact]:
        return next((c for c in self.contacts() if c.wallet == wallet), None)

    def find_contacts(self, name: str) -> list[Contact]:
        q = normalize(name)
        if not q:
            return []
        scored: list[tuple[float, Contact]] = []
        for c in self.contacts():
            best = 0.0
            for cand in [c.name, c.relation, *c.aliases]:
                cn = normalize(cand)
                if not cn:
                    continue
                if cn == q or (q.startswith("ل") and q[1:] == cn):
                    score = 1.0
                elif phrase_in(q, cn) or phrase_in(cn, q):
                    score = 0.9
                else:
                    score = similarity(q, cn)
                best = max(best, score)
            if best >= 0.75:
                scored.append((best, c))
        scored.sort(key=lambda x: x[0], reverse=True)
        if not scored:
            return []
        top = scored[0][0]
        return [c for s, c in scored if s >= top - 0.001]

    def contact_in_text(self, text_norm: str) -> list[Contact]:
        """Contacts mentioned anywhere in a sentence (longest alias wins)."""
        best_len, found = 0, []
        for c in self.contacts():
            for cand in [c.name, *c.aliases]:
                if phrase_in(text_norm, cand):
                    ln = len(normalize(cand))
                    if ln > best_len:
                        best_len, found = ln, [c]
                    elif ln == best_len and c not in found:
                        found.append(c)
        return found

    def bills(self) -> list[Bill]:
        return list(self.user.bills)

    def bill_for(self, biller: str) -> Optional[Bill]:
        return next((b for b in self.bills() if b.biller == biller), None)

    def pending_transaction(self) -> Optional[Transaction]:
        if self.conv is None:
            return None
        tx = self.db.scalar(
            select(Transaction)
            .where(Transaction.conversation_id == self.conv.id, Transaction.status == "pending")
            .order_by(Transaction.id.desc())
        )
        if tx and tx.expires_at and tx.expires_at < utcnow():
            tx.status = "expired"
            self.db.commit()
            return None
        return tx

    def get_transaction(self, tx_id: int) -> Optional[Transaction]:
        tx = self.db.get(Transaction, tx_id)
        return tx if tx and tx.user_id == self.user.id else None

    # ------------------------------------------------------------------ prepare
    def prepare(self, service_key: Optional[str], fields: Optional[dict] = None, *,
                merge: bool = True, source: str = "assistant") -> dict[str, Any]:
        svc = get_service(service_key)
        if not svc or svc.kind != "transaction":
            return {"status": "invalid_service",
                    "message": tr("ما عرفت يا خدمة تقصد. أكدر أحوّل فلوس، ويسترن يونيون، سحب، بطاقات، تعبئة، رصيد هاتف، وفواتير.",
                                  "I didn't get which service you mean. I can send money, Western Union, withdrawals, "
                                  "cards, top-ups, phone credit and bills."),
                    "valid_services": TRANSACTION_SERVICES}

        incoming = {k: v for k, v in (fields or {}).items()
                    if v is not None and not isinstance(v, (dict, list)) and str(v).strip() != ""}
        draft = self.draft
        base: dict[str, Any] = {}
        context: dict[str, Any] = {}
        same_flow = draft and draft.get("service") == svc.key and draft.get("mode") != "schedule"
        if merge and same_flow:
            base = dict(draft.get("fields") or {})
            context = dict(draft.get("context") or {})
        elif draft and not same_flow:
            self._cancel_pending_silently()
            self.clear_draft()

        r = self.resolve(svc, base, incoming, context)
        clean, errors, missing, info, choices = r["clean"], r["errors"], r["missing"], r["info"], r["choices"]
        open_keys, non_sensitive_open = r["open_keys"], r["non_sensitive_open"]

        if open_keys:
            if non_sensitive_open or source != "assistant":
                awaiting = (non_sensitive_open or open_keys)[0]
                f = svc.field(awaiting)
                message = errors.get(awaiting) or f.ask_t
                if info and awaiting not in errors:
                    message = f"{info} {message}"
                status = "needs_info"
                if not choices:
                    choices = self._choices_for(svc, f)
            else:  # only sensitive card details left -> must be typed on screen
                awaiting = open_keys[0]
                status = "needs_screen"
                message = tr("حتى تبقى معلومات بطاقتك بأمان، دخّل رقم البطاقة وتاريخ الانتهاء والـCVV "
                             "بنفسك بالشاشة، وبعدين اضغط «متابعة».",
                             "To keep your card safe, type the card number, expiry date and CVV yourself on "
                             "the screen, then press «Continue».")
            self._save_draft({"service": svc.key, "fields": self._storable(svc, clean),
                              "awaiting": awaiting, "context": context})
            self._commit()
            return {"status": status, "service": svc.key, "service_name": svc.name_t,
                    "fields": self._storable(svc, clean), "missing": missing, "errors": errors,
                    "awaiting": awaiting, "message": message, "choices": choices[:8]}

        # ---------------------------------------------------------------- ready
        amounts = self._compute(svc, clean)
        if svc.direction == "debit" and amounts["total_iqd"] > self.user.balance:
            self._save_draft({"service": svc.key, "fields": self._storable(svc, clean),
                              "awaiting": "amount", "context": context})
            self._commit()
            return {"status": "insufficient", "service": svc.key, "service_name": svc.name_t,
                    "fields": self._storable(svc, clean), "awaiting": "amount",
                    "balance": self.user.balance, "required": amounts["total_iqd"],
                    "message": tr(f"رصيدك {fmt_iqd(self.user.balance)} وما يكفي لهاي العملية "
                                  f"(تحتاج {fmt_iqd(amounts['total_iqd'])}). تريد تقلل المبلغ؟",
                                  f"Your balance is {fmt_iqd(self.user.balance)}, not enough for this "
                                  f"(it needs {fmt_iqd(amounts['total_iqd'])}). Do you want a smaller amount?"),
                    "choices": [tr("إلغاء", "Cancel")]}

        self._cancel_pending_silently()
        stored = self._storable(svc, clean, mask=True)
        stored.update({k: v for k, v in context.items() if k in ("recipient_name", "is_new_recipient")})
        tx = Transaction(
            reference=self._new_reference(), user_id=self.user.id,
            conversation_id=self.conv.id if self.conv is not None else None,
            service=svc.key, source=source, direction=svc.direction, fields=stored,
            amount=amounts["amount"], currency=svc.currency, fee=amounts["fee"],
            amount_iqd=amounts["amount_iqd"], fee_iqd=amounts["fee_iqd"], total_iqd=amounts["total_iqd"],
            status="pending", expires_at=utcnow() + timedelta(minutes=self.settings.pending_ttl_minutes),
        )
        self.db.add(tx)
        self.db.flush()
        self._save_draft({"service": svc.key, "fields": self._storable(svc, clean), "awaiting": None,
                          "context": context, "pending_tx": tx.id})
        self._commit()
        action = self.public_tx(tx)
        message = tr(f"{self.summary(tx)} إذا كلشي صحيح كول «أكّد»، وإذا تريد تغيّر شي كلّي.",
                     f"{self.summary(tx)} If everything is right say «confirm», or tell me what to change.")
        if action["warnings"]:
            message = f"{action['warnings'][0]} {message}"
        return {"status": "ready", "service": svc.key, "service_name": svc.name_t, "action": action,
                "message": message, "choices": [tr("أكّد", "Confirm"), tr("إلغاء", "Cancel")]}

    def resolve(self, svc: Service, base: dict, incoming: dict, context: dict) -> dict[str, Any]:
        """Merge + validate fields for a service without side effects (shared by schedules)."""
        base = dict(base)
        if svc.key == "bill_payment" and "biller" in incoming and base.get("biller"):
            new_biller = match_choice(str(incoming["biller"]), svc.field("biller").options,
                                      svc.field("biller").synonyms)
            if new_biller != base["biller"]:  # switching bill -> forget the old bill's details
                base.pop("account", None)
                base.pop("amount", None)
                context.pop("auto_amount", None)

        values = {**base, **incoming}
        errors: dict[str, str] = {}
        choices: list[str] = []
        self._pre_resolve(svc, values, incoming, errors, context, choices)

        clean: dict[str, Any] = {}
        for f in svc.fields:
            if not f.applies(clean) or f.key not in values or f.key in errors:
                continue
            ok, val, err = self._validate_field(svc, f, values[f.key])
            if ok:
                clean[f.key] = val
            else:
                errors[f.key] = err

        info = self._post_resolve(svc, clean, incoming, errors, context)
        applicable = [f for f in svc.fields if f.applies(clean)]
        errors = {k: v for k, v in errors.items() if any(f.key == k for f in applicable)}
        missing = [f.key for f in applicable if f.required and f.key not in clean]
        open_keys = [f.key for f in applicable if f.key in errors or f.key in missing]
        non_sensitive_open = [k for k in open_keys if not svc.field(k).sensitive]
        return {"clean": clean, "errors": errors, "missing": missing, "info": info, "choices": choices,
                "open_keys": open_keys, "non_sensitive_open": non_sensitive_open}

    # ------------------------------------------------------------------ hooks
    def _pre_resolve(self, svc: Service, values: dict, incoming: dict, errors: dict,
                     context: dict, choices: list) -> None:
        if svc.key == "transfer":
            contact_name = values.pop("contact_name", None) or values.pop("recipient_name", None)
            wallet_raw = values.get("wallet")
            if wallet_raw is not None and not re.search(r"\d", to_ascii_digits(str(wallet_raw))):
                contact_name, wallet_raw = str(wallet_raw), None
                values.pop("wallet", None)
            if contact_name and ("wallet" not in incoming or wallet_raw is None):
                matches = self.find_contacts(str(contact_name))
                if len(matches) == 1:
                    values["wallet"] = matches[0].wallet
                    context["recipient_name"] = matches[0].name
                elif len(matches) > 1:
                    values.pop("wallet", None)
                    names = [disp(m.name) for m in matches]
                    errors["wallet"] = tr(f"عندك أكثر من شخص بهذا الاسم: {' أو '.join(names)}؟",
                                          f"You have more than one person with that name: {' or '.join(names)}?")
                    choices.extend(names)
                else:
                    values.pop("wallet", None)
                    errors["wallet"] = tr(f"ما لكيت «{contact_name}» بجهات اتصالك. كلّي رقم محفظته (يبدي بـ07).",
                                          f"I couldn't find «{contact_name}» in your contacts. Tell me their "
                                          "wallet number (starts with 07).")
            elif "wallet" in incoming:
                context.pop("recipient_name", None)
        elif svc.key == "mobile_topup":
            num = values.get("number")
            if num is not None and normalize(str(num)) in SELF_WORDS:
                values["number"] = self.user.phone
                if "carrier" not in incoming:
                    values.pop("carrier", None)
            elif "number" in incoming and "carrier" not in incoming:
                values.pop("carrier", None)  # re-infer for the new number

    def _post_resolve(self, svc: Service, clean: dict, incoming: dict, errors: dict,
                      context: dict) -> str:
        info = ""
        if svc.key == "transfer" and "wallet" in clean:
            if clean["wallet"] == self.user.phone:
                del clean["wallet"]
                errors["wallet"] = tr("هذا رقم محفظتك انت. كلّي رقم الشخص اللي تريد تحوله.",
                                      "That is your own wallet number. Tell me the number of the person you want to pay.")
            else:
                c = self.contact_by_wallet(clean["wallet"])
                if c:
                    context["recipient_name"] = c.name
                    context["is_new_recipient"] = False
                else:
                    context.pop("recipient_name", None)
                    context["is_new_recipient"] = True
        elif svc.key == "mobile_topup" and "number" in clean and "carrier" not in clean:
            inferred = carrier_from_phone(clean["number"])
            if inferred:
                clean["carrier"] = inferred
        elif svc.key == "bill_payment" and "biller" in clean:
            bill = self.bill_for(clean["biller"])
            if bill:
                clean.setdefault("account", bill.account)
                if "amount" not in clean and "amount" not in errors:
                    if bill.status == "due" and bill.amount_due > 0:
                        clean["amount"] = bill.amount_due
                        context["auto_amount"] = True
                    else:
                        info = tr(f"فاتورة {bill.biller} مدفوعة وما عليها مبلغ مستحق.",
                                  f"The {disp(bill.biller)} bill is already paid; nothing is due.")
        return info

    # ------------------------------------------------------------------ validation
    def _validate_field(self, svc: Service, f: Field, raw: Any) -> tuple[bool, Any, str]:
        text = to_ascii_digits(str(raw)).strip()
        if f.type == "phone":
            p = to_local_phone(text)
            if not p:
                return False, None, tr("الرقم مو صحيح. لازم يبدي بـ07 ويكون 11 رقم، مثل 07801234567.",
                                       "That number isn't valid. It must start with 07 and have 11 digits, e.g. 07801234567.")
            return True, p, ""

        if f.type == "money":
            v = parse_amount(raw)
            if v is None:
                return False, None, tr("ما فهمت المبلغ. كلّي ياه بالأرقام، مثلاً 25 ألف.",
                                       "I didn't get the amount. Please give it in numbers, e.g. 25,000.")
            if svc.currency == "IQD" and v < 1000:
                v *= 1000  # Iraqi colloquial: "حوّل خمسة وعشرين" = 25,000
            if f.options:
                if v not in f.options:
                    opts = "، ".join(fmt_money(o, svc.currency) for o in f.options)
                    return False, None, tr(f"هاي الفئة غير متوفرة. الفئات المتوفرة: {opts}.",
                                           f"That value isn't available. Available values: {opts}.")
            if svc.currency == "IQD":
                v = int(round(v))
            else:
                v = round(float(v), 2)
            if f.min is not None and v < f.min:
                return False, None, tr(f"أقل مبلغ لهاي الخدمة {fmt_money(f.min, svc.currency)}.",
                                       f"The minimum for this service is {fmt_money(f.min, svc.currency)}.")
            if f.max is not None and v > f.max:
                return False, None, tr(f"أعلى مبلغ لهاي الخدمة {fmt_money(f.max, svc.currency)}.",
                                       f"The maximum for this service is {fmt_money(f.max, svc.currency)}.")
            if f.step and v % f.step != 0:
                return False, None, tr(f"المبلغ لازم يكون من مضاعفات {int(f.step)} دينار.",
                                       f"The amount must be a multiple of {int(f.step)} IQD.")
            return True, v, ""

        if f.type == "choice":
            m = match_choice(text, f.options, f.synonyms)
            if m is None:
                opts = "، ".join(disp(o) for o in f.options[:8])
                return False, None, tr(f"اختار وحدة من هذني: {opts}.", f"Please choose one of: {opts}.")
            return True, m, ""

        if f.type == "name":
            name = re.sub(r"[^\w\s\-']", " ", text)
            name = re.sub(r"\d", "", name)
            name = re.sub(r"\s+", " ", name).strip()
            if len(name.split()) < 2:
                return False, None, tr("أحتاج الاسم الكامل للمستلم (الاسم الأول واسم الأب على الأقل) "
                                       "مثل ما بالهوية، حتى يكدر يستلم الحوالة.",
                                       "I need the receiver's full name (at least first and father's name) "
                                       "as on their ID, so they can collect the money.")
            if len(name) > 70:
                return False, None, tr("الاسم طويل كلش، كلّي الاسم الثلاثي بس.", "That name is too long; first, father and surname only.")
            return True, name, ""

        if f.type == "text":
            if not text or len(text) > 120:
                return False, None, f.ask_t or tr("القيمة غير صحيحة.", "Invalid value.")
            return True, text, ""

        if f.type == "card_number":
            digits = re.sub(r"\D", "", text)
            if not luhn_ok(digits):
                return False, None, tr("رقم البطاقة غير صحيح.", "The card number is not valid.")
            return True, digits, ""

        if f.type == "expiry":
            m = re.fullmatch(r"(\d{1,2})\s*/\s*(\d{2}|\d{4})", text)
            if not m:
                return False, None, tr("تاريخ الانتهاء لازم يكون بالشكل MM/YY.", "The expiry date must look like MM/YY.")
            month, year = int(m.group(1)), int(m.group(2)[-2:])
            now = utcnow()
            if not 1 <= month <= 12 or (2000 + year, month) < (now.year, now.month):
                return False, None, tr("البطاقة منتهية أو التاريخ غلط.", "The card is expired or the date is wrong.")
            return True, f"{month:02d}/{year:02d}", ""

        if f.type == "cvv":
            if not re.fullmatch(r"\d{3,4}", text):
                return False, None, tr("رمز CVV لازم يكون 3 أو 4 أرقام.", "The CVV must be 3 or 4 digits.")
            return True, text, ""

        return True, text, ""

    def _choices_for(self, svc: Service, f: Field) -> list[str]:
        if f.type == "choice":
            return [disp(o) for o in f.options]
        if f.type == "money" and f.options:
            return [fmt_money(o, svc.currency) for o in f.options]
        if svc.key == "transfer" and f.key == "wallet":
            return [disp(c.name) for c in self.contacts()]
        if svc.key == "mobile_topup" and f.key == "number":
            return [tr("رقمي", "My number")]
        if f.type == "money" and svc.currency == "IQD":
            presets = [10000, 25000, 50000, 100000]
            return [fmt_iqd(p) for p in presets if (f.min or 0) <= p <= (f.max or 1e12)]
        if f.type == "money" and svc.currency == "USD":
            return ["$100", "$200", "$500"]
        return []

    @staticmethod
    def _storable(svc: Service, clean: dict, mask: bool = False) -> dict:
        out = {}
        for k, v in clean.items():
            f = svc.field(k)
            if f and f.sensitive:
                if mask and f.type == "card_number":
                    out["card_last4"] = str(v)[-4:]
                continue
            out[k] = v
        return out

    def _compute(self, svc: Service, clean: dict) -> dict:
        amount = clean["amount"]
        fee = fee_for(svc.key, amount, clean)
        if svc.currency == "USD":
            rate = self.settings.usd_to_iqd
            amount_iqd, fee_iqd = round(amount * rate), round(fee * rate)
            total = amount_iqd + fee_iqd
        else:
            amount_iqd, fee_iqd = int(amount), int(fee)
            total = amount_iqd + fee_iqd if svc.direction == "debit" else amount_iqd - fee_iqd
        return {"amount": amount, "fee": fee, "amount_iqd": amount_iqd, "fee_iqd": fee_iqd,
                "total_iqd": total}

    def _new_reference(self) -> str:
        while True:
            ref = f"TX{utcnow():%y%m%d}{_digits(6)}"
            if not self.db.scalar(select(Transaction.id).where(Transaction.reference == ref)):
                return ref

    def _cancel_pending_silently(self) -> None:
        tx = self.pending_transaction()
        if tx:
            tx.status = "cancelled"
        if self.conv is not None:  # only one item may wait for confirmation at a time
            for s in self.db.scalars(select(Schedule).where(Schedule.conversation_id == self.conv.id,
                                                            Schedule.status == "pending")).all():
                s.status = "cancelled"

    def _commit(self) -> None:
        self.db.commit()

    # ------------------------------------------------------------------ confirm / cancel
    def confirm(self, tx_id: Optional[int] = None) -> dict[str, Any]:
        tx = self.get_transaction(tx_id) if tx_id else self.pending_transaction()
        if not tx:
            return {"status": "no_pending", "message": tr("ماكو عملية بانتظار التأكيد حالياً. شنو تحب أسوي؟",
                                                          "Nothing is waiting for confirmation. What would you like to do?")}
        if tx.status != "pending":
            return {"status": "not_pending", "action": self.public_tx(tx),
                    "message": tr(f"هاي العملية {status_label(tx.status)}.", f"This operation is {status_label(tx.status).lower()}.")}
        if tx.expires_at and tx.expires_at < utcnow():
            tx.status = "expired"
            self._clear_draft_for(tx)
            self._commit()
            return {"status": "expired", "action": self.public_tx(tx),
                    "message": tr("انتهت مدة التأكيد لهاي العملية. نعيدها من جديد؟",
                                  "The confirmation time for this operation ran out. Shall we start again?")}
        if tx.direction == "debit" and tx.total_iqd > self.user.balance:
            return {"status": "insufficient", "action": self.public_tx(tx),
                    "message": tr(f"رصيدك {fmt_iqd(self.user.balance)} ما يكفي لهاي العملية.",
                                  f"Your balance of {fmt_iqd(self.user.balance)} is not enough for this.")}

        # atomic claim: protects against double confirmation (button + voice at the same time)
        claimed = self.db.execute(
            update(Transaction).where(Transaction.id == tx.id, Transaction.status == "pending")
            .values(status="processing")
        ).rowcount
        if not claimed:
            self.db.rollback()
            self.db.refresh(tx)
            return {"status": "not_pending", "action": self.public_tx(tx),
                    "message": tr(f"هاي العملية {status_label(tx.status)}.", f"This operation is {status_label(tx.status).lower()}.")}
        self.db.refresh(tx)

        if tx.direction == "debit":
            self.user.balance -= tx.total_iqd
        else:
            self.user.balance += tx.total_iqd
        result = self._result_for(tx)
        result["balance_after"] = self.user.balance
        tx.result = result
        tx.status = "completed"
        tx.completed_at = utcnow()
        if tx.service == "bill_payment":
            bill = self.bill_for(tx.fields.get("biller", ""))
            if bill and bill.account == tx.fields.get("account"):
                bill.status, bill.amount_due = "paid", 0
        self._clear_draft_for(tx)
        self._commit()
        verified = self.verify(tx.id)
        if not verified["ok"]:  # never report success the database does not show
            return {"status": "failed", "action": self.public_tx(tx), "verified": verified,
                    "message": tr("ما قدرت أتأكد من حالة العملية. راجع سجل العمليات أو كلّم الدعم.",
                                  "I could not verify the operation status. Check your history or contact support.")}
        return {"status": "completed", "action": self.public_tx(tx), "message": self._result_message(tx),
                "balance": self.user.balance, "verified": verified}

    def verify(self, tx_id: int) -> dict[str, Any]:
        """Re-read the transaction from the database: the evidence behind any 'it worked' message."""
        fresh = self.db.execute(select(Transaction.status, Transaction.reference, Transaction.total_iqd)
                                .where(Transaction.id == tx_id)).first()
        ok = bool(fresh and fresh.status == "completed")
        return {"ok": ok, "source": "database.transactions", "reference": fresh.reference if fresh else None,
                "status": fresh.status if fresh else None, "checked_at": iso(utcnow())}

    def cancel(self, tx_id: Optional[int] = None) -> dict[str, Any]:
        tx = self.get_transaction(tx_id) if tx_id else self.pending_transaction()
        had_draft = bool(self.draft) and tx_id is None
        cancelled = None
        if tx and tx.status == "pending":
            tx.status = "cancelled"
            cancelled = tx
            self._clear_draft_for(tx)
        if had_draft:
            self.clear_draft()
        self._commit()
        if cancelled is None and not had_draft:
            if tx:
                return {"status": "not_pending", "action": self.public_tx(tx),
                        "message": tr(f"هاي العملية {status_label(tx.status)}.", f"This operation is {status_label(tx.status).lower()}.")}
            return {"status": "nothing", "message": tr("ماكو شي بانتظار التأكيد حتى ألغيه.", "There is nothing waiting to cancel.")}
        return {"status": "cancelled", "action": self.public_tx(cancelled),
                "message": tr("تم الإلغاء وما انخصم أي مبلغ. أكو شي ثاني أساعدك بيه؟",
                              "Cancelled. No money was taken. Anything else I can help with?")}

    def _clear_draft_for(self, tx: Transaction) -> None:
        d = self.draft
        if d and (d.get("pending_tx") in (None, tx.id)):
            self.clear_draft()

    # ------------------------------------------------------------------ results & display
    def _result_for(self, tx: Transaction) -> dict[str, Any]:
        """Codes generated at execution time (stored with the transaction)."""
        s = tx.service
        if s == "western_union":
            mtcn = _digits(10)
            return {"code": f"{mtcn[:3]}-{mtcn[3:6]}-{mtcn[6:]}", "code_kind": "mtcn"}
        if s == "agent_withdraw":
            return {"code": _digits(6), "code_kind": "withdraw"}
        if s == "cash_withdraw":
            code = _digits(8)
            return {"code": f"{code[:4]} {code[4:]}", "code_kind": "cash"}
        if s == "buy_card":
            pin = _digits(16)
            return {"code": " ".join(pin[i:i + 4] for i in range(0, 16, 4)), "code_kind": "pin", "serial": _digits(10)}
        if s == "bill_payment":
            return {"code": _digits(9), "code_kind": "receipt"}
        return {}

    def _result_message(self, tx: Transaction) -> str:
        f, r = tx.fields or {}, tx.result or {}
        amt = fmt_money(tx.amount, tx.currency)
        s, code = tx.service, r.get("code", "")
        if s == "transfer":
            name = disp(f.get("recipient_name")) or fmt_phone(f.get("wallet", ""))
            return tr(f"تم تحويل {amt} إلى {name} بنجاح.", f"{amt} sent to {name} successfully.")
        if s == "western_union":
            return tr(f"تم إرسال الحوالة. رقم MTCN هو {code}. خلّي {f.get('receiver_name')} يستلمها من أي فرع "
                      f"ويسترن يونيون في {f.get('country')} بهويته.",
                      f"Transfer sent. The MTCN is {code}. {f.get('receiver_name')} can collect it at any Western "
                      f"Union branch in {disp(f.get('country'))} with their ID.")
        if s == "agent_withdraw":
            return tr(f"كود السحب هو {code}. روح لـ{f.get('agent')} وانطيه الكود، صالح 24 ساعة.",
                      f"Your withdrawal code is {code}. Show it at {disp(f.get('agent'))}; valid for 24 hours.")
        if s == "cash_withdraw":
            return tr(f"كود السحب هو {code}. تكدر تستلم {amt} من أي وكيل خلال 24 ساعة.",
                      f"Your withdrawal code is {code}. Collect {amt} at any agent within 24 hours.")
        if s == "buy_card":
            return tr(f"تم شراء بطاقة {f.get('provider')} فئة {amt}. الرقم السري موجود بالشاشة.",
                      f"{disp(f.get('provider'))} card of {amt} purchased. The PIN is on the screen.")
        if s == "wallet_topup":
            return tr(f"تمت إضافة {fmt_iqd(tx.total_iqd)} لرصيدك.", f"{fmt_iqd(tx.total_iqd)} added to your balance.")
        if s == "mobile_topup":
            return tr(f"تم شحن {amt} رصيد {f.get('carrier')} للرقم {fmt_phone(f.get('number', ''))}.",
                      f"{amt} of {disp(f.get('carrier'))} credit added to {fmt_phone(f.get('number', ''))}.")
        if s == "bill_payment":
            return tr(f"تم دفع فاتورة {f.get('biller')} بمبلغ {amt}. رقم الوصل {code}.",
                      f"{disp(f.get('biller'))} bill of {amt} paid. Receipt number {code}.")
        return tr("تمت العملية بنجاح.", "Done successfully.")

    def summary(self, tx: Transaction) -> str:
        f = tx.fields
        amt = fmt_money(tx.amount, tx.currency)
        fee = fmt_money(tx.fee, tx.currency) if tx.fee else tr("بدون رسوم", "no fee")
        s = tx.service
        if s == "transfer":
            who = disp(f.get("recipient_name")) or tr("رقم جديد", "a new number")
            return tr(f"راح أحوّل {amt} إلى {who} على الرقم {fmt_phone(f.get('wallet', ''))}، بدون رسوم.",
                      f"I'll send {amt} to {who} at {fmt_phone(f.get('wallet', ''))}, no fee.")
        if s == "western_union":
            return tr(f"حوالة ويسترن يونيون بمبلغ {amt} إلى {f.get('receiver_name')} في {f.get('country')}. "
                      f"الرسوم {fee}، والمجموع {fmt_iqd(tx.total_iqd)} ينخصم من رصيدك.",
                      f"Western Union transfer of {amt} to {f.get('receiver_name')} in {disp(f.get('country'))}. "
                      f"Fee {fee}; {fmt_iqd(tx.total_iqd)} in total is taken from your balance.")
        if s == "agent_withdraw":
            return tr(f"سحب {amt} من {f.get('agent')}، والرسوم {fee}.", f"Withdraw {amt} at {disp(f.get('agent'))}, fee {fee}.")
        if s == "cash_withdraw":
            return tr(f"سحب نقدي بمبلغ {amt}، والرسوم {fee}.", f"Cash withdrawal of {amt}, fee {fee}.")
        if s == "buy_card":
            return tr(f"شراء بطاقة {f.get('provider')} فئة {amt}.", f"Buy a {disp(f.get('provider'))} card of {amt}.")
        if s == "wallet_topup":
            return tr(f"تعبئة المحفظة بمبلغ {amt} عن طريق {f.get('method')}، {('الرسوم ' + fee) if tx.fee else 'بدون رسوم'}.",
                      f"Top up {amt} via {disp(f.get('method'))}, {('fee ' + fee) if tx.fee else 'no fee'}.")
        if s == "mobile_topup":
            return tr(f"شحن {amt} رصيد {f.get('carrier')} للرقم {fmt_phone(f.get('number', ''))}.",
                      f"Add {amt} of {disp(f.get('carrier'))} credit to {fmt_phone(f.get('number', ''))}.")
        if s == "bill_payment":
            return tr(f"دفع فاتورة {f.get('biller')} للحساب {f.get('account')} بمبلغ {amt}.",
                      f"Pay the {disp(f.get('biller'))} bill, account {f.get('account')}, {amt}.")
        return tr(f"عملية بمبلغ {amt}.", f"Operation of {amt}.")

    def title(self, tx: Transaction) -> str:
        f = tx.fields
        s = tx.service
        if s == "transfer":
            return tr("تحويل إلى ", "Transfer to ") + (disp(f.get("recipient_name")) or fmt_phone(f.get("wallet", "")))
        if s == "western_union":
            return f"{tr('ويسترن يونيون', 'Western Union')} - {f.get('receiver_name', '')}"
        if s == "buy_card":
            return tr(f"بطاقة {f.get('provider', '')}", f"{disp(f.get('provider', ''))} card")
        if s == "mobile_topup":
            num = f.get("number", "")
            carrier = disp(f.get("carrier", ""))
            if num == self.user.phone:
                return tr(f"رصيد {carrier} لرقمك", f"{carrier} credit for your number")
            c = self.contact_by_wallet(num)
            return tr(f"رصيد {carrier} - ", f"{carrier} credit - ") + (disp(c.name) if c else fmt_phone(num))
        if s == "bill_payment":
            return tr(f"فاتورة {f.get('biller', '')}", f"{disp(f.get('biller', ''))} bill")
        if s == "agent_withdraw":
            return tr(f"سحب من {f.get('agent', 'وكيل')}", f"Withdrawal at {disp(f.get('agent', 'agent'))}")
        return SERVICES[s].name_t if s in SERVICES else s

    CODE_LABELS = {"mtcn": ("رقم الحوالة (MTCN)", "Transfer number (MTCN)"), "withdraw": ("كود السحب", "Withdrawal code"),
                   "cash": ("كود السحب النقدي", "Cash withdrawal code"), "pin": ("الرقم السري للبطاقة", "Card PIN"),
                   "receipt": ("رقم الوصل", "Receipt number")}

    def public_tx(self, tx: Optional[Transaction]) -> Optional[dict[str, Any]]:
        if tx is None:
            return None
        svc = SERVICES.get(tx.service)
        f = tx.fields or {}
        lines: list[dict[str, str]] = []
        if tx.service == "transfer":
            lines.append({"label": tr("المستلم", "Receiver"), "value": disp(f.get("recipient_name")) or tr("مستلم جديد", "New receiver")})
            lines.append({"label": tr("رقم المحفظة", "Wallet number"), "value": fmt_phone(f.get("wallet", ""))})
            if f.get("note"):
                lines.append({"label": tr("ملاحظة", "Note"), "value": f["note"]})
        elif svc:
            for fld in svc.fields:
                if fld.key == "amount":
                    continue
                if fld.type == "card_number" and f.get("card_last4"):
                    lines.append({"label": fld.label_t, "value": f"•••• {f['card_last4']}"})
                elif fld.key in f and not fld.sensitive:
                    val = f[fld.key]
                    lines.append({"label": fld.label_t, "value": fmt_phone(val) if fld.type == "phone" else disp(val)})
        lines.append({"label": tr("المبلغ", "Amount"), "value": fmt_money(tx.amount, tx.currency), "kind": "amount"})
        if tx.currency == "USD":
            lines.append({"label": tr("رسوم ويسترن يونيون", "Western Union fee"), "value": fmt_usd(tx.fee)})
            lines.append({"label": tr("سعر الصرف", "Exchange rate"), "value": f"$1 = {self.settings.usd_to_iqd:,} " + tr("د.ع", "IQD")})
        else:
            lines.append({"label": tr("الرسوم", "Fee"), "value": fmt_iqd(tx.fee) if tx.fee else tr("مجاناً", "Free")})

        warnings = []
        if tx.service == "transfer" and f.get("is_new_recipient"):
            warnings.append(tr("تنبيه: هذا الرقم مو من جهات اتصالك. تأكد منه زين قبل التأكيد.",
                               "Note: this number is not in your contacts. Double-check it before confirming."))
        if tx.service in ("transfer", "western_union") and tx.total_iqd >= 1_000_000:
            warnings.append(tr("تنبيه أمان: إذا أحد اتصل بيك وطلب منك تحوّل فلوس، لا تأكد العملية.",
                               "Safety note: if someone called and asked you to send money, do not confirm."))

        if tx.status == "completed" and tx.result:
            balance_after = tx.result.get("balance_after")
        else:
            balance_after = (self.user.balance - tx.total_iqd if tx.direction == "debit"
                             else self.user.balance + tx.total_iqd)
        result = None
        if tx.result:
            result = {k: v for k, v in tx.result.items()}
            kind = result.get("code_kind")
            if kind in self.CODE_LABELS:
                result["code_label"] = tr(*self.CODE_LABELS[kind])
            if tx.status == "completed":
                result["message"] = self._result_message(tx)
        return {
            "id": tx.id, "reference": tx.reference, "service": tx.service,
            "service_name": svc.name_t if svc else tx.service,
            "title": svc.confirm_title_t if (svc and tx.status == "pending") else self.title(tx),
            "subtitle": self.title(tx), "status": tx.status,
            "status_label": status_label(tx.status), "direction": tx.direction,
            "source": tx.source, "lines": lines, "warnings": warnings,
            "amount": tx.amount, "currency": tx.currency,
            "amount_display": fmt_money(tx.amount, tx.currency),
            "total_iqd": tx.total_iqd, "total_display": fmt_iqd(tx.total_iqd),
            "total_label": tr("المجموع اللي ينخصم من رصيدك", "Total taken from your balance") if tx.direction == "debit"
            else tr("المبلغ اللي يضاف لرصيدك", "Amount added to your balance"),
            "balance_after": balance_after, "balance_after_display": fmt_iqd(balance_after),
            "result": result,
            "created_at": iso(tx.created_at), "expires_at": iso(tx.expires_at),
            "completed_at": iso(tx.completed_at),
        }

    # ------------------------------------------------------------------ info
    def recent_transactions(self, limit: int = 10, include_pending: bool = False) -> list[dict]:
        q = select(Transaction).where(Transaction.user_id == self.user.id)
        if not include_pending:
            q = q.where(Transaction.status == "completed")
        txs = self.db.scalars(q.order_by(Transaction.id.desc()).limit(limit)).all()
        return [{
            "id": t.id, "reference": t.reference, "service": t.service,
            "service_name": SERVICES[t.service].name_t if t.service in SERVICES else t.service,
            "title": self.title(t), "direction": t.direction, "status": t.status,
            "status_label": status_label(t.status),
            "amount_display": fmt_money(t.amount, t.currency), "total_iqd": t.total_iqd,
            "total_display": fmt_iqd(t.total_iqd), "created_at": iso(t.created_at),
            "icon": SERVICES[t.service].icon if t.service in SERVICES else "list",
        } for t in txs]

    def wallet_summary(self) -> dict[str, Any]:
        return {
            "name": self.user.name, "phone": self.user.phone, "balance": self.user.balance,
            "balance_display": fmt_iqd(self.user.balance),
        }

