"""Model-agnostic LLM layer: every model call in the project goes through `LLMClient.chat()`.

Supported out of the box (one env var to switch):
- Any OpenAI-compatible API: OpenAI, DeepSeek, Groq, OpenRouter, Google Gemini (OpenAI endpoint),
  Mistral, Together, xAI, Cerebras, ...
- Local models: Ollama, LM Studio, vLLM, llama.cpp server (no API key needed)
- Anthropic Claude (native Messages API, converted to/from the OpenAI message format here)

Tool calling works in two ways:
- native: OpenAI-style `tools` / `tool_calls`
- json:   for models without tool support, the model answers with one JSON object
          {"tool": "...", "args": {...}} or {"reply": "..."}; we parse and validate it in code.
`LLM_TOOL_MODE=auto` starts native and switches to json automatically if the endpoint rejects tools.

A backup chain (`LLM_FALLBACKS`) is tried in order when a model fails, and the offline rule-based
agent is the last fallback, so the app never breaks when a free tier runs out.

Only the standard library is used (urllib), so this file also runs inside the browser build.
"""
from __future__ import annotations

import json
import logging
import re
import time
import urllib.error
import urllib.request
from dataclasses import dataclass
from typing import Any, Optional

log = logging.getLogger("llm")

# provider -> (default base URL, default model, API-key env var or None for local servers)
PRESETS: dict[str, tuple[str, str, Optional[str]]] = {
    "openai": ("https://api.openai.com/v1", "gpt-4o-mini", "OPENAI_API_KEY"),
    "deepseek": ("https://api.deepseek.com", "deepseek-chat", "DEEPSEEK_API_KEY"),
    "groq": ("https://api.groq.com/openai/v1", "llama-3.3-70b-versatile", "GROQ_API_KEY"),
    "openrouter": ("https://openrouter.ai/api/v1", "meta-llama/llama-3.3-70b-instruct:free", "OPENROUTER_API_KEY"),
    "gemini": ("https://generativelanguage.googleapis.com/v1beta/openai", "gemini-2.0-flash", "GEMINI_API_KEY"),
    "mistral": ("https://api.mistral.ai/v1", "mistral-small-latest", "MISTRAL_API_KEY"),
    "together": ("https://api.together.xyz/v1", "meta-llama/Llama-3.3-70B-Instruct-Turbo", "TOGETHER_API_KEY"),
    "xai": ("https://api.x.ai/v1", "grok-2-latest", "XAI_API_KEY"),
    "cerebras": ("https://api.cerebras.ai/v1", "llama-3.3-70b", "CEREBRAS_API_KEY"),
    "anthropic": ("https://api.anthropic.com/v1", "claude-opus-5-5", "ANTHROPIC_API_KEY"),
    "ollama": ("http://localhost:11434/v1", "qwen2.5:7b", None),
    "lmstudio": ("http://localhost:1234/v1", "local-model", None),
    "vllm": ("http://localhost:8000/v1", "local-model", None),
    "llamacpp": ("http://localhost:8080/v1", "local-model", None),
    "custom": ("", "", None),
}
LOCAL = {"ollama", "lmstudio", "vllm", "llamacpp"}
LOCAL_LABELS = {"ollama": "Ollama", "lmstudio": "LM Studio", "vllm": "vLLM", "llamacpp": "llama.cpp server"}
_LOCAL_HOSTS = {"localhost", "127.0.0.1", "::1", "0.0.0.0", "host.docker.internal"}


def is_local(cfg: "LLMConfig") -> bool:
    """A model served from this machine / the local network (slower first token, no key, no internet)."""
    from urllib.parse import urlparse

    if cfg.provider in LOCAL:
        return True
    host = (urlparse(cfg.base_url).hostname or "").lower()
    return host in _LOCAL_HOSTS or host.endswith(".local") or host.startswith(("192.168.", "10."))


class LLMError(RuntimeError):
    pass


@dataclass(frozen=True)
class LLMConfig:
    provider: str
    model: str
    base_url: str
    api_key: str = ""
    tool_mode: str = "auto"  # auto | native | json


def _one(settings, provider: str, model: str = "", key: str = "", base: str = "") -> Optional[LLMConfig]:
    provider = (provider or "").strip().lower()
    preset = PRESETS.get(provider, PRESETS["custom"])
    # Local servers only: <PROVIDER>_BASE_URL (e.g. OLLAMA_BASE_URL=http://192.168.1.20:11434/v1) moves them to
    # another host, also when they are only a fallback. Not for cloud providers: variables such as
    # ANTHROPIC_BASE_URL / OPENAI_BASE_URL are often set for other tools with a different path layout.
    local_base = settings.env(f"{provider.upper()}_BASE_URL") if provider in LOCAL else ""
    base = (base or local_base or preset[0]).rstrip("/")
    key = key or (settings.env(preset[2]) if preset[2] else "")
    model = model or preset[1]
    if not base or not model:
        return None
    if provider not in LOCAL and provider != "custom" and not key:
        return None  # a cloud provider without a key is not usable
    return LLMConfig(provider=provider or "custom", model=model, base_url=base, api_key=key,
                     tool_mode=(settings.llm_tool_mode or "auto").lower())


def resolve_config(settings) -> Optional[LLMConfig]:
    """The main model from LLM_* (or the legacy DEEPSEEK_* variables), or None for offline mode."""
    provider = settings.llm_provider.strip().lower()
    if not provider:  # auto-detect from whatever is configured
        if settings.llm_base_url and not settings.llm_api_key:
            provider = "custom"
        elif settings.deepseek_api_key and not settings.llm_api_key:
            provider = "deepseek"
        else:
            provider = next((p for p, (_, _, env) in PRESETS.items() if env and settings.env(env)), "")
            if not provider and settings.llm_api_key:
                provider = "openai"
    if not provider:
        return None
    if provider == "deepseek" and not settings.llm_api_key:
        return _one(settings, "deepseek", settings.llm_model or settings.deepseek_model,
                    settings.deepseek_api_key, settings.llm_base_url or settings.deepseek_base_url)
    return _one(settings, provider, settings.llm_model, settings.llm_api_key, settings.llm_base_url)


def fallback_configs(settings) -> list[LLMConfig]:
    out = []
    if settings.deepseek_api_key and not settings.llm_api_key:  # legacy DEEPSEEK_FALLBACK_MODELS
        for m in (settings.deepseek_fallback_models or "").split(","):
            cfg = _one(settings, "deepseek", m.strip(), settings.deepseek_api_key, settings.deepseek_base_url)
            if m.strip() and cfg:
                out.append(cfg)
    for item in (settings.llm_fallbacks or "").split(","):
        item = item.strip()
        if not item:
            continue
        provider, _, model = item.partition(":")
        cfg = _one(settings, provider, model.strip())
        if cfg:
            out.append(cfg)
    return out


# --------------------------------------------------------------------------- transport

def _browser_post_json(url: str, headers: dict, payload: dict, timeout: float) -> tuple[int, str]:
    """Inside the browser build (Pyodide in a Web Worker) urllib has no network: use the browser's own
    XMLHttpRequest. Synchronous is fine (and allowed) in a worker; it only blocks the backend thread."""
    from js import XMLHttpRequest  # type: ignore[import-not-found]  (Pyodide only)

    xhr = XMLHttpRequest.new()
    xhr.open("POST", url, False)
    try:
        xhr.timeout = int(timeout * 1000)
    except Exception:  # pragma: no cover - some browsers refuse timeouts on sync requests
        pass
    for k, v in {**headers, "Content-Type": "application/json"}.items():
        xhr.setRequestHeader(k, v)
    try:
        xhr.send(json.dumps(payload))
    except Exception as e:  # network down, CORS refused, timeout
        raise LLMError(f"network error: {e}") from None
    if not xhr.status:
        raise LLMError("network error: no response (offline or blocked)")
    return int(xhr.status), str(xhr.responseText or "")


def http_post_json(url: str, headers: dict, payload: dict, timeout: float) -> tuple[int, str]:
    """POST JSON, return (status, body)."""
    import sys

    if sys.platform == "emscripten":
        return _browser_post_json(url, headers, payload, timeout)
    req = urllib.request.Request(url, data=json.dumps(payload).encode("utf-8"),
                                 headers={**headers, "Content-Type": "application/json"}, method="POST")
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:  # noqa: S310 - URL comes from config
            return r.status, r.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode("utf-8", "replace")
    except (urllib.error.URLError, TimeoutError, OSError) as e:
        raise LLMError(f"network error: {e}") from None


def http_get_json(url: str, headers: Optional[dict] = None, timeout: float = 3.0) -> Any:
    req = urllib.request.Request(url, headers=headers or {}, method="GET")
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:  # noqa: S310 - URL comes from admin config
            return json.loads(r.read().decode("utf-8", "replace"))
    except urllib.error.HTTPError as e:
        raise LLMError(f"HTTP {e.code}") from None
    except (urllib.error.URLError, TimeoutError, OSError, ValueError) as e:
        raise LLMError(f"not reachable: {getattr(e, 'reason', e)}") from None


# --------------------------------------------------------------------------- local models

def list_models(base_url: str, api_key: str = "", timeout: float = 3.0) -> list[str]:
    """Models a server offers: OpenAI-compatible GET /models (Ollama, LM Studio, vLLM, llama.cpp, LocalAI...),
    with Ollama's native /api/tags as a second try."""
    base = (base_url or "").rstrip("/")
    headers = {"Authorization": f"Bearer {api_key}"} if api_key else {}
    try:
        data = http_get_json(f"{base}/models", headers, timeout)
        ids = [m.get("id") for m in (data.get("data") or data.get("models") or []) if isinstance(m, dict)]
        ids = [i for i in ids if isinstance(i, str)]
        if ids:
            return sorted(set(ids))
    except LLMError as exc:
        # Ollama's native API is only worth a try when a server answered (HTTP error), not when nothing listens
        if not base.endswith("/v1") or not str(exc).startswith("HTTP"):
            raise
    root = base[:-3] if base.endswith("/v1") else base
    data = http_get_json(f"{root}/api/tags", headers, timeout)  # Ollama
    return sorted({m.get("name") for m in data.get("models") or [] if isinstance(m, dict) and m.get("name")})


def discover_local(settings=None, timeout: float = 0.8) -> list[dict[str, Any]]:
    """Look for local model servers on their default ports (and any <PROVIDER>_BASE_URL that is set)."""
    from concurrent.futures import ThreadPoolExecutor

    targets = []
    for provider in ("ollama", "lmstudio", "vllm", "llamacpp"):
        urls = [PRESETS[provider][0]]
        custom = settings.env(f"{provider.upper()}_BASE_URL") if settings is not None else ""
        if custom and custom.rstrip("/") not in urls:
            urls.insert(0, custom.rstrip("/"))
        targets += [(provider, url) for url in urls]

    def probe(target: tuple[str, str]) -> dict[str, Any]:
        provider, url = target
        base = {"provider": provider, "label": LOCAL_LABELS[provider], "base_url": url}
        try:
            return {**base, "running": True, "models": list_models(url, timeout=timeout)}
        except LLMError as exc:
            return {**base, "running": False, "models": [], "error": str(exc)[:120]}

    # in parallel: on Windows a closed port takes ~2 s to refuse, one after another would be slow
    with ThreadPoolExecutor(max_workers=len(targets)) as pool:
        return list(pool.map(probe, targets))


# --------------------------------------------------------------------------- JSON tool mode

def _json_mode_instructions(tools: list[dict]) -> str:
    lines = []
    for t in tools:
        f = t["function"]
        props = ", ".join(f"{k}: {v.get('type', 'any')}" for k, v in (f.get("parameters", {}).get("properties") or {}).items())
        lines.append(f"- {f['name']}({props}) — {f.get('description', '')[:220]}")
    return ("TOOLS (you cannot call functions natively). Answer with EXACTLY ONE JSON object and nothing else:\n"
            '{"tool": "<name>", "args": {...}}  to use a tool, or  {"reply": "<text for the user>"}  to answer.\n'
            "After a tool runs you receive its result and answer again in the same JSON format.\n" + "\n".join(lines))


def parse_json_reply(text: str, tool_names: set[str]) -> dict[str, Any]:
    """Turn a JSON-mode answer into an OpenAI-style message. Invalid output never runs a tool."""
    m = re.search(r"\{.*\}", text or "", re.S)
    data = None
    if m:
        try:
            data = json.loads(m.group(0))
        except json.JSONDecodeError:
            data = None
    if isinstance(data, dict) and data.get("tool") in tool_names:
        args = data.get("args") if isinstance(data.get("args"), dict) else {}
        return {"content": "", "tool_calls": [{"id": f"json_{int(time.time() * 1000)}", "type": "function",
                                               "function": {"name": data["tool"],
                                                            "arguments": json.dumps(args, ensure_ascii=False)}}]}
    if isinstance(data, dict) and isinstance(data.get("reply"), str):
        return {"content": data["reply"]}
    return {"content": (text or "").strip()}  # plain text: treat as the reply, never as an action


def _to_json_mode(messages: list[dict]) -> list[dict]:
    """Rewrite tool turns as plain text for models without native tool calling."""
    out = []
    for m in messages:
        if m["role"] == "tool":
            out.append({"role": "user", "content": f"TOOL RESULT: {m['content']}"})
        elif m["role"] == "assistant" and m.get("tool_calls"):
            calls = [{"tool": c["function"]["name"], "args": json.loads(c["function"].get("arguments") or "{}")}
                     for c in m["tool_calls"]]
            out.append({"role": "assistant", "content": json.dumps(calls[0], ensure_ascii=False)})
        else:
            out.append({"role": m["role"], "content": m.get("content") or ""})
    return out


# --------------------------------------------------------------------------- Anthropic adapter

def _anthropic_payload(model: str, messages: list[dict], tools: Optional[list[dict]], max_tokens: int) -> dict:
    system = "\n\n".join(m["content"] for m in messages if m["role"] == "system")
    conv: list[dict] = []
    for m in messages:
        if m["role"] == "system":
            continue
        if m["role"] == "tool":
            block = {"type": "tool_result", "tool_use_id": m.get("tool_call_id", ""), "content": m["content"]}
            if conv and conv[-1]["role"] == "user" and isinstance(conv[-1]["content"], list):
                conv[-1]["content"].append(block)  # all results of one turn in a single user message
            else:
                conv.append({"role": "user", "content": [block]})
        elif m["role"] == "assistant" and m.get("tool_calls"):
            blocks: list[dict] = [{"type": "text", "text": m["content"]}] if m.get("content") else []
            for c in m["tool_calls"]:
                blocks.append({"type": "tool_use", "id": c["id"], "name": c["function"]["name"],
                               "input": json.loads(c["function"].get("arguments") or "{}")})
            conv.append({"role": "assistant", "content": blocks})
        else:
            conv.append({"role": m["role"], "content": m.get("content") or ""})
    payload: dict[str, Any] = {"model": model, "max_tokens": max(max_tokens, 4000), "system": system,
                               "messages": conv, "output_config": {"effort": "low"}}
    if tools:
        payload["tools"] = [{"name": t["function"]["name"], "description": t["function"].get("description", ""),
                             "input_schema": t["function"].get("parameters") or {"type": "object", "properties": {}}}
                            for t in tools]
        payload["tool_choice"] = {"type": "auto"}
    return payload


def _anthropic_message(data: dict) -> dict:
    if data.get("stop_reason") == "refusal":
        raise LLMError("model declined the request (refusal)")
    text, calls = [], []
    for b in data.get("content") or []:
        if b.get("type") == "text":
            text.append(b.get("text", ""))
        elif b.get("type") == "tool_use":
            calls.append({"id": b["id"], "type": "function",
                          "function": {"name": b["name"], "arguments": json.dumps(b.get("input") or {}, ensure_ascii=False)}})
    msg: dict[str, Any] = {"content": "".join(text)}
    if calls:
        msg["tool_calls"] = calls
    u = data.get("usage") or {}
    return {"message": msg, "usage": {"prompt_tokens": u.get("input_tokens", 0), "completion_tokens": u.get("output_tokens", 0)}}


# --------------------------------------------------------------------------- client

@dataclass
class _Health:
    """Per-endpoint circuit breaker: a model that keeps failing is skipped for a while (fast failover)."""
    ok: int = 0
    failures: int = 0  # consecutive
    down_until: float = 0.0
    last_error: str = ""
    last_latency_ms: int = 0
    last_ok_at: float = 0.0

    def public(self, now: float) -> dict[str, Any]:
        return {"state": "open" if self.down_until > now else ("degraded" if self.failures else "healthy"),
                "ok": self.ok, "consecutive_failures": self.failures, "last_latency_ms": self.last_latency_ms,
                "retry_in_s": max(0, int(self.down_until - now)), "last_error": self.last_error[:160]}


BREAKER_AFTER = 2          # consecutive failures before an endpoint is skipped
BREAKER_BASE_S = 20.0      # first cool-down; doubles on every further failure
BREAKER_MAX_S = 300.0


class LLMClient:
    def __init__(self, settings, configs: Optional[list[LLMConfig]] = None):
        self.settings = settings
        main = resolve_config(settings)
        chain = configs if configs is not None else ([main] if main else []) + fallback_configs(settings)
        seen: set[tuple[str, str, str]] = set()
        self.configs = []
        for c in chain:  # the same model listed twice (e.g. legacy + new settings) is tried only once
            if (c.provider, c.model, c.base_url) not in seen:
                seen.add((c.provider, c.model, c.base_url))
                self.configs.append(c)
        self._json_only: set[tuple[str, str]] = set()  # endpoints that rejected native tools
        self.last_used: Optional[LLMConfig] = None
        self._health: dict[tuple[str, str], _Health] = {}

    @property
    def model(self) -> str:
        c = self.last_used or (self.configs[0] if self.configs else None)
        return f"{c.provider}:{c.model}" if c else ""

    def _h(self, cfg: LLMConfig) -> _Health:
        return self._health.setdefault((cfg.provider, cfg.model), _Health())

    def health(self) -> list[dict[str, Any]]:
        now = time.time()
        return [{"model": f"{c.provider}:{c.model}", "role": "primary" if i == 0 else f"fallback {i}",
                 **self._h(c).public(now)} for i, c in enumerate(self.configs)]

    def chat(self, messages: list[dict], tools: Optional[list[dict]] = None) -> dict[str, Any]:
        """Return {'message': {...OpenAI format...}, 'model': 'provider:model', 'usage': {...}}.

        Endpoints are tried in order; one whose circuit breaker is open is skipped (unless every endpoint is
        open, then all are tried anyway: a half-open probe).
        """
        errors = []
        now = time.time()
        order = [c for c in self.configs if self._h(c).down_until <= now] or list(self.configs)
        for cfg in order:
            h = self._h(cfg)
            t0 = time.perf_counter()
            try:
                res = self._chat_one(cfg, messages, tools)
            except LLMError as exc:
                h.failures += 1
                h.last_error = str(exc)
                if h.failures >= BREAKER_AFTER:
                    h.down_until = time.time() + min(BREAKER_MAX_S, BREAKER_BASE_S * 2 ** (h.failures - BREAKER_AFTER))
                errors.append(f"{cfg.provider}:{cfg.model}: {exc}")
                log.warning("LLM %s:%s failed (%d in a row): %s", cfg.provider, cfg.model, h.failures, exc)
                continue
            h.ok += 1
            h.failures, h.down_until, h.last_ok_at = 0, 0.0, time.time()
            h.last_latency_ms = int((time.perf_counter() - t0) * 1000)
            self.last_used = cfg
            return {**res, "model": f"{cfg.provider}:{cfg.model}"}
        raise LLMError(" | ".join(errors) or "no LLM configured")

    def complete(self, system: str, user: str) -> str:
        """One plain completion (no tools), e.g. for the language guard's translation."""
        res = self.chat([{"role": "system", "content": system}, {"role": "user", "content": user}])
        return (res["message"].get("content") or "").strip()

    def _chat_one(self, cfg: LLMConfig, messages: list[dict], tools: Optional[list[dict]]) -> dict[str, Any]:
        json_mode = bool(tools) and (cfg.tool_mode == "json" or (cfg.provider, cfg.model) in self._json_only)
        if json_mode:
            return self._json_call(cfg, messages, tools)
        try:
            return self._raw(cfg, messages, tools)
        except LLMError as exc:
            if tools and cfg.tool_mode == "auto" and "tool" in str(exc).lower():
                self._json_only.add((cfg.provider, cfg.model))
                log.info("%s:%s has no native tool calling, switching to JSON mode", cfg.provider, cfg.model)
                return self._json_call(cfg, messages, tools)
            raise

    def _json_call(self, cfg: LLMConfig, messages: list[dict], tools: list[dict]) -> dict[str, Any]:
        msgs = _to_json_mode(messages)
        msgs.insert(1 if msgs and msgs[0]["role"] == "system" else 0,
                    {"role": "system", "content": _json_mode_instructions(tools)})
        res = self._raw(cfg, msgs, None)
        names = {t["function"]["name"] for t in tools}
        return {**res, "message": parse_json_reply(res["message"].get("content") or "", names)}

    def _raw(self, cfg: LLMConfig, messages: list[dict], tools: Optional[list[dict]]) -> dict[str, Any]:
        s = self.settings
        if cfg.provider == "anthropic":
            url = f"{cfg.base_url}/messages"
            headers = {"x-api-key": cfg.api_key, "anthropic-version": "2023-06-01"}
            import sys

            if sys.platform == "emscripten":  # Claude called straight from the visitor's browser (their own key)
                headers["anthropic-dangerous-direct-browser-access"] = "true"
            payload = _anthropic_payload(cfg.model, messages, tools, s.llm_max_tokens)
        else:
            url = f"{cfg.base_url}/chat/completions"
            headers = {"Authorization": f"Bearer {cfg.api_key}"} if cfg.api_key else {}
            payload = {"model": cfg.model, "messages": messages, "temperature": s.llm_temperature,
                       "max_tokens": s.llm_max_tokens}
            if tools:
                payload["tools"] = tools
                payload["tool_choice"] = "auto"
        last = ""
        timeout = s.llm_local_timeout_seconds if is_local(cfg) else s.llm_timeout_seconds
        for attempt in range(3):
            status, body = http_post_json(url, headers, payload, timeout)
            if status == 200:
                try:
                    data = json.loads(body)
                except json.JSONDecodeError:
                    raise LLMError("invalid JSON from the model endpoint") from None
                if cfg.provider == "anthropic":
                    return _anthropic_message(data)
                try:
                    msg = data["choices"][0]["message"]
                except (KeyError, IndexError, TypeError):
                    raise LLMError(f"unexpected response: {body[:200]}") from None
                return {"message": msg, "usage": data.get("usage") or {}}
            last = f"HTTP {status}: {body[:300]}"
            if status in (429, 500, 502, 503, 504):
                time.sleep(0.7 * (attempt + 1))
                continue
            break  # 4xx: retrying the same request will not help
        raise LLMError(last)

    def ping(self) -> dict[str, Any]:
        res = self.chat([{"role": "user", "content": "Reply with the single word: ok"}])
        return {"ok": True, "model": res["model"], "reply": (res["message"].get("content") or "").strip()}


_shared: dict[str, LLMClient] = {}


def get_client(settings) -> Optional[LLMClient]:
    if not settings.llm_enabled:
        return None
    key = repr((resolve_config(settings), fallback_configs(settings)))
    if key not in _shared:
        _shared.clear()
        _shared[key] = LLMClient(settings)
    return _shared[key]


# --------------------------------------------------------------------------- model chosen in the browser
# The app's «AI settings» (or a private link) keep {provider, model, key} in the visitor's browser and send it
# with each request (header X-LLM-Config). Nothing is configured on the server. On GitHub Pages the request
# never leaves the browser (the backend runs in a worker); on a server it is used for that request only.

BROWSER_FALLBACK = {"deepseek": ["deepseek-chat"]}  # same key, tried when the chosen model fails
_browser_clients: dict[str, "LLMClient"] = {}


def browser_config(raw: Any, settings, allow_private: bool) -> tuple[Optional[str], Optional[list[LLMConfig]]]:
    """Validate the browser's choice. Returns (mode, configs): mode 'offline' (the visitor chose the built-in
    agent), 'llm' with the configs, or (None, None) when nothing usable was sent (server defaults apply)."""
    if isinstance(raw, str):
        try:
            raw = json.loads(raw) if raw.strip().startswith("{") else {"provider": "deepseek", "key": raw}
        except ValueError:
            return None, None
    if not isinstance(raw, dict):
        return None, None
    provider = str(raw.get("provider") or "").strip().lower()
    if provider in ("offline", "local_agent", "none"):
        return "offline", None
    if provider not in PRESETS:
        return None, None
    model = str(raw.get("model") or "").strip()[:120]
    key = str(raw.get("key") or "").strip()
    base = str(raw.get("base_url") or "").strip().rstrip("/")
    if key and (len(key) > 400 or not key.isascii() or re.search(r"\s", key)):
        return None, None
    if base and not re.fullmatch(r"https?://[^\s]{3,300}", base):
        return None, None
    preset = PRESETS[provider]
    base = base if provider in LOCAL or provider == "custom" else ""
    cfg = LLMConfig(provider=provider, model=model or preset[1], base_url=(base or preset[0]).rstrip("/"),
                    api_key=key, tool_mode=(settings.llm_tool_mode or "auto").lower())
    if not cfg.base_url or not cfg.model or (provider not in LOCAL and provider != "custom" and not key):
        return None, None
    if is_local(cfg) and not allow_private:
        return None, None  # a public server must not be made to call machines on its own network
    configs = [cfg] + [LLMConfig(provider, m, cfg.base_url, key, cfg.tool_mode)
                       for m in BROWSER_FALLBACK.get(provider, []) if m != cfg.model]
    return "llm", configs


def browser_client(settings, configs: list[LLMConfig]) -> "LLMClient":
    """One client per distinct choice, so its circuit breaker and JSON-mode memory survive between messages."""
    import hashlib

    k = hashlib.sha256(repr(configs).encode()).hexdigest()
    if k not in _browser_clients:
        if len(_browser_clients) > 50:
            _browser_clients.clear()
        _browser_clients[k] = LLMClient(settings, configs)
    return _browser_clients[k]


def warmup(settings) -> list[dict[str, Any]]:
    """Ping every configured endpoint once (server start / keep-alive) so health is known before users arrive.

    Each endpoint is pinged on its own, so a broken fallback is discovered early instead of during a turn.
    """
    client = get_client(settings)
    if client is None:
        return []
    for cfg in client.configs:
        single = LLMClient(settings, [cfg])
        single._health = client._health  # share the breaker state
        try:
            single.chat([{"role": "user", "content": "Reply with the single word: ok"}])
        except LLMError:
            pass
    return client.health()

backend/schedules.py:
"""Recurring / future payments (standing orders), reminders and notifications.

- Creating a schedule follows the same rule as any money operation: it is prepared, shown on a
  confirmation card, and only becomes active after the user explicitly confirms.
- Each run then executes automatically through the normal ActionEngine (balance checks, fees,
  bill lookups), and the user is notified one day before and after every run.
- All times are Baghdad local time (UTC+3, no DST); stored as naive UTC.
"""
from __future__ import annotations

