log = logging.getLogger("scheduler")

LOCAL_TZ = timezone(timedelta(hours=3))
SCHEDULABLE = ["transfer", "bill_payment", "mobile_topup"]
FREQUENCIES = ["once", "daily", "weekly", "monthly"]
FREQ = {"once": ("مرة وحدة", "once"), "daily": ("يومياً", "daily"), "weekly": ("أسبوعياً", "weekly"),
        "monthly": ("شهرياً", "monthly")}
STATUS = {"pending": ("بانتظار التأكيد", "Waiting for confirmation"), "active": ("فعّالة", "Active"),
          "paused": ("متوقفة مؤقتاً", "Paused"), "completed": ("منتهية", "Finished"), "cancelled": ("ملغاة", "Cancelled")}
WEEKDAYS_AR = ["الاثنين", "الثلاثاء", "الأربعاء", "الخميس", "الجمعة", "السبت", "الأحد"]  # datetime.weekday()
WEEKDAYS_EN = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]
MONTHS_AR = ["كانون الثاني", "شباط", "آذار", "نيسان", "أيار", "حزيران", "تموز", "آب", "أيلول",
             "تشرين الأول", "تشرين الثاني", "كانون الأول"]
MONTHS_EN = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]


def freq_label(f: str) -> str:
    return tr(*FREQ.get(f, (f, f)))


def status_label(s: str) -> str:
    return tr(*STATUS.get(s, (s, s)))


def weekday(i: int) -> str:
    return (WEEKDAYS_EN if is_en() else WEEKDAYS_AR)[i]


def month(i: int) -> str:
    return (MONTHS_EN if is_en() else MONTHS_AR)[i]
FREQ_SYN = {
    "monthly": ["monthly", "month", "every month", "شهري", "شهريا", "شهرياً", "كل شهر", "بالشهر", "كل اول شهر", "كل بداية شهر"],
    "weekly": ["weekly", "week", "every week", "اسبوعي", "اسبوعيا", "أسبوعياً", "كل اسبوع", "بالاسبوع"],
    "daily": ["daily", "every day", "يومي", "يوميا", "يومياً", "كل يوم"],
    "once": ["once", "مرة", "مره وحده", "مرة وحدة", "مرة واحدة", "بس مرة"],
}

def FREQ_ASK() -> str:
    return tr("كل شكد تريدها تتكرر؟ مرة وحدة، كل يوم، كل أسبوع، لو كل شهر؟",
              "How often should it repeat? Once, daily, weekly or monthly?")


def DAY_ASK_MONTHLY() -> str:
