def DAY_ASK_WEEKLY() -> str:
    return tr("يا يوم من الأسبوع؟", "Which day of the week?")


def DATE_ASK() -> str:
    return tr("يا يوم تريدها؟ مثلاً باجر، لو يوم 20.", "Which day? e.g. tomorrow, or the 20th.")


def DATE_PAST() -> str:
