# --------------------------------------------------------------------------- time helpers

def local_now() -> datetime:
    return datetime.now(LOCAL_TZ)


def to_utc_naive(dt_local: datetime) -> datetime:
    return dt_local.astimezone(timezone.utc).replace(tzinfo=None)


def to_local(dt_utc_naive: datetime) -> datetime:
    return dt_utc_naive.replace(tzinfo=timezone.utc).astimezone(LOCAL_TZ)


def fmt_local(dt_utc_naive: Optional[datetime]) -> str:
    if not dt_utc_naive:
        return ""
    d = to_local(dt_utc_naive)
    hour = d.hour % 12 or 12
    if is_en():
        return f"{weekday(d.weekday())} {d.day} {month(d.month - 1)}, {hour}:{d.minute:02d} {'AM' if d.hour < 12 else 'PM'}"
    ampm = "صباحاً" if d.hour < 12 else "مساءً"
    return f"{weekday(d.weekday())} {d.day} {month(d.month - 1)}، الساعة {hour}:{d.minute:02d} {ampm}"


def _at_run_hour(d: date) -> datetime:
    return datetime(d.year, d.month, d.day, get_settings().schedule_run_hour, 0, tzinfo=LOCAL_TZ)


def _month_day(year: int, month: int, day: int) -> date:
    return date(year, month, min(day, calendar.monthrange(year, month)[1]))


def compute_next_run(frequency: str, day: Optional[int], start_date: Optional[str],
                     after: Optional[datetime] = None) -> Optional[datetime]:
    """Next run strictly after `after` (local aware). Returns local aware datetime or None."""
    after = after or local_now()
    today = after.date()
    if frequency == "daily":
        cand = _at_run_hour(today)
        return cand if cand > after else _at_run_hour(today + timedelta(days=1))
    if frequency == "weekly":
        ahead = (int(day) - today.weekday()) % 7
        cand = _at_run_hour(today + timedelta(days=ahead))
        return cand if cand > after else cand + timedelta(days=7)
    if frequency == "monthly":
        cand = _at_run_hour(_month_day(today.year, today.month, int(day)))
        if cand > after:
            return cand
        y, m = (today.year + 1, 1) if today.month == 12 else (today.year, today.month + 1)
        return _at_run_hour(_month_day(y, m, int(day)))
    if frequency == "once":
        d = date.fromisoformat(start_date)
        cand = _at_run_hour(d)
        if cand > after:
            return cand
        if d == today:  # "today" after the run hour -> a minute from now
            return after + timedelta(minutes=1)
        return None
    return None


def describe_timing(frequency: str, day: Optional[int], start_date: Optional[str]) -> str:
    hour = get_settings().schedule_run_hour
    if is_en():
        at = f"at {hour % 12 or 12} {'AM' if hour < 12 else 'PM'}"
        if frequency == "daily":
            return f"Daily {at}"
        if frequency == "weekly" and day is not None:
            return f"Every {weekday(int(day))} {at}"
        if frequency == "monthly" and day is not None:
            return "Monthly on the last day " + at if int(day) == 31 else f"Monthly on day {int(day)} {at}"
        if frequency == "once" and start_date:
            d = date.fromisoformat(start_date)
            return f"Once on {weekday(d.weekday())} {d.day} {month(d.month - 1)} {at}"
        return freq_label(frequency)
    at = f"الساعة {hour % 12 or 12} {'صباحاً' if hour < 12 else 'مساءً'}"
    if frequency == "daily":
        return f"يومياً {at}"
    if frequency == "weekly" and day is not None:
        return f"كل يوم {weekday(int(day))} {at}"
    if frequency == "monthly" and day is not None:
        return f"شهرياً يوم {int(day)} من كل شهر {at}"
    if frequency == "once" and start_date:
        d = date.fromisoformat(start_date)
        return f"مرة وحدة يوم {weekday(d.weekday())} {d.day} {month(d.month - 1)} {at}"
    return freq_label(frequency)


# --------------------------------------------------------------------------- parsing

_WD_CORES = {0: ["اثنين", "تنين"], 1: ["ثلاثاء", "ثلاثا"], 2: ["اربعاء", "اربعا"], 3: ["خميس"],
             4: ["جمعه"], 5: ["سبت"], 6: ["احد"]}
_WD_EN = {"monday": 0, "tuesday": 1, "wednesday": 2, "thursday": 3, "friday": 4, "saturday": 5, "sunday": 6}
_WD_ALT = "|".join(c for cores in _WD_CORES.values() for c in cores)
# a weekday only counts with "ال"/"يوم"/"كل" before it ("احد" alone means "someone", "اثنين" means "two")
_WD_RE = re.compile(r"(?:^|\s)(?:[وبل]?ال|يوم\s+(?:ال)?|كل\s+(?:ال)?)(" + _WD_ALT + r")(?=\s|$)")


_EN_TIMING = [
    (r"\b(?:the )?day after tomorrow\b", " بعد باجر "), (r"\btomorrow\b", " باجر "), (r"\btoday\b", " اليوم "),
    (r"\bin (\d+) days?\b", r" بعد \1 ايام "),
    (r"\b(?:on )?(?:the )?(?:first|1st|start|beginning) of (?:every|each|the) month\b", " اول كل شهر "),
    (r"\b(?:on )?(?:the )?(?:last day|end) of (?:every|each|the) month\b", " اخر كل شهر "),
    (r"\b(?:on )?(?:the )?(?:day )?(\d{1,2})(?:st|nd|rd|th)?(?: day)? of (?:every|each) month\b", r" يوم \1 من كل شهر "),
    (r"\b(?:every|each) month\b|\bmonthly\b", " كل شهر "), (r"\b(?:every|each) week\b|\bweekly\b", " كل اسبوع "),
    (r"\b(?:every|each) day\b|\bdaily\b", " كل يوم "),
    (r"\bon (?:the )?(?:day )?(\d{1,2})(?:st|nd|rd|th)?\b|\bday (\d{1,2})\b", lambda m: f" يوم {m.group(1) or m.group(2)} "),
]
_EN_WD = {"monday": "الاثنين", "tuesday": "الثلاثاء", "wednesday": "الاربعاء", "thursday": "الخميس",
          "friday": "الجمعه", "saturday": "السبت", "sunday": "الاحد"}


def _en_to_ar(n: str) -> str:
    """Rewrite English timing phrases into the Arabic forms the parsers below understand."""
    if not re.search(r"[a-z]", n):
        return n
    for en, ar in _EN_WD.items():
        n = re.sub(rf"\b(?:every|each) {en}s?\b", f" كل {ar} ", n)
        n = re.sub(rf"\b(?:on )?{en}s?\b", f" يوم {ar} ", n)
    for pat, rep in _EN_TIMING:
        n = re.sub(pat, rep, n)
    return re.sub(r"\s+", " ", n).strip()


def _core_to_weekday(core: str) -> Optional[int]:
    return next((i for i, cores in _WD_CORES.items() if core in cores), None)


def _weekday_in(n: str) -> Optional[int]:
    m = _WD_RE.search(n)
    return _core_to_weekday(m.group(1)) if m else None


def _weekday_value(value: Any) -> Optional[int]:
    n = normalize(str(value))
    if n in _WD_EN:
        return _WD_EN[n]
    n = re.sub(r"^(?:يوم\s+|كل\s+)", "", n)
    n = n[2:] if n.startswith("ال") else n
    return _core_to_weekday(n) if n else None


def parse_frequency(value: Any) -> Optional[str]:
    n = normalize(str(value or ""))
    if not n:
        return None
    if n in FREQUENCIES:
        return n
    for key, words in FREQ_SYN.items():
        if any(normalize(w) == n or phrase_in(n, w) for w in words):
            return key
    return None


def parse_day(value: Any, frequency: Optional[str]) -> Optional[int]:
    if value is None or value == "":
        return None
    if frequency == "weekly":
        if isinstance(value, int) and not isinstance(value, bool) and 0 <= value <= 6:
            return value
        if re.fullmatch(r"[0-6]", to_ascii_digits(str(value)).strip()):  # from the screen form
            return int(to_ascii_digits(str(value)).strip())
        return _weekday_value(value) if _weekday_value(value) is not None else _weekday_in(normalize(str(value)))
    n = _en_to_ar(normalize(str(value)))
    if phrase_in(n, "اول") or phrase_in(n, "بداية") or phrase_in(n, "first"):
        return 1
    if phrase_in(n, "نص") or phrase_in(n, "منتصف"):
        return 15
    if phrase_in(n, "اخر") or phrase_in(n, "نهاية") or phrase_in(n, "last") or phrase_in(n, "end"):
        return 31
    v = value if isinstance(value, (int, float)) and not isinstance(value, bool) else parse_amount(n)
    if v is None:
        return None
    v = int(v)
    return v if 1 <= v <= 31 else None


def parse_date(value: Any, today: Optional[date] = None) -> Optional[str]:
    today = today or local_now().date()
    s = to_ascii_digits(str(value or "")).strip()
    m = re.search(r"(\d{4})-(\d{1,2})-(\d{1,2})", s)
    if m:
        try:
            return date(int(m.group(1)), int(m.group(2)), int(m.group(3))).isoformat()
        except ValueError:
            return None
    n = _en_to_ar(normalize(s))
    if not n:
        return None
    if phrase_in(n, "بعد باجر") or phrase_in(n, "عقب باجر") or phrase_in(n, "بعد بكره"):
        return (today + timedelta(days=2)).isoformat()
    if phrase_in(n, "day after tomorrow"):
        return (today + timedelta(days=2)).isoformat()
    if any(phrase_in(n, w) for w in ("باجر", "بكره", "بكرا", "غدا", "غدوه", "tomorrow")):
        return (today + timedelta(days=1)).isoformat()
    if re.search(r"(?:^|\s)(?:اليوم|هسه|today)(?=\s|$)", n):
        return today.isoformat()
    m = re.search(r"بعد\s+(\S+)\s+(?:ايام|يوم)", n)
    if m:
        k = parse_amount(m.group(1))
        if k:
            return (today + timedelta(days=int(k))).isoformat()
    wd = _weekday_in(n)
    if wd is not None:
        ahead = (wd - today.weekday()) % 7 or 7
        return (today + timedelta(days=ahead)).isoformat()
    m = re.search(r"(?:^|\s)(?:يوم|بيوم)\s+(\S+)", n)
    k = parse_amount(m.group(1)) if m else None
    if k and 1 <= int(k) <= 31:
        d = int(k)
        cand = _month_day(today.year, today.month, d)
        if cand < today:
            y, mo = (today.year + 1, 1) if today.month == 12 else (today.year, today.month + 1)
            cand = _month_day(y, mo, d)
        return cand.isoformat()
    return None


_TIMING_PATTERNS = [
    r"(?:يوم|بيوم)\s+\S+\s+(?:من\s+)?(?:كل\s+)?(?:شهر|الشهر)",
    r"(?:اول|بدايه|نص|منتصف|اخر|نهايه)\s+(?:كل\s+)?(?:شهر|الشهر)",
    r"كل\s+(?:اول\s+)?(?:شهر|اسبوع|يوم)", r"كل\s+\S+",  # كل جمعه / كل شهر
    r"(?:شهريا|اسبوعيا|يوميا|شهري|اسبوعي|يومي|تلقاييا|تلقايي|بشكل\s+دوري|بالشهر|بالاسبوع)",
    r"بعد\s+باجر", r"عقب\s+باجر", r"(?:باجر|بكره|بكرا|غدا)", r"بعد\s+\S+\s+(?:ايام|يوم)",
    r"(?:يوم|بيوم)\s+\S+", r"\d{4}-\d{1,2}-\d{1,2}",
]


def parse_timing_text(text: str) -> tuple[dict, str]:
    """Extract {frequency, day, date} from a sentence; returns (timing, text_without_timing)."""
    n = _en_to_ar(normalize(text))
    timing: dict[str, Any] = {}
    freq = None
    if re.search(r"كل\s+(?:اول\s+|بدايه\s+)?شهر|شهريا|شهري|بالشهر|(?:يوم\s+\S+\s+)?من\s+كل\s+شهر", n):
        freq = "monthly"
    elif re.search(r"كل\s+اسبوع|اسبوعيا|اسبوعي|بالاسبوع|كل\s+(?:ال)?(?:" + _WD_ALT + r")(?=\s|$)", n):
        freq = "weekly"
    elif re.search(r"كل\s+يوم|يوميا|يومي", n):
        freq = "daily"
    elif re.search(r"(?:اول|بدايه|نص|منتصف|اخر|نهايه)\s+(?:الشهر|شهر)", n):
        freq = "monthly"
    if freq:
        timing["frequency"] = freq
    if freq == "monthly":
        m = re.search(r"(?:^|\s)(?:يوم|بيوم)\s+(\S+)", n)
        day = parse_day(m.group(1), "monthly") if m else None
        if day is None:
            m2 = re.search(r"(اول|بدايه|نص|منتصف|اخر|نهايه)\s+(?:كل\s+)?(?:الشهر|شهر)", n)
            day = parse_day(m2.group(1), "monthly") if m2 else None
        if day:
            timing["day"] = day
    elif freq == "weekly":
        wd = _weekday_in(n)
        if wd is not None:
            timing["day"] = wd
    elif not freq:
        d = parse_date(n)
        explicit = (re.search(r"(?:^|\s)(?:باجر|بكره|بكرا|غدا)(?=\s|$)|بعد\s+باجر|بعد\s+\S+\s+(?:ايام|يوم)(?=\s|$)"
                              r"|(?:^|\s)ب?يوم\s+\d+|\d{4}-\d", n) or _weekday_in(n) is not None)
        if d and explicit:
            timing = {"frequency": "once", "date": d}
    rest = n
    if timing:
        for p in _TIMING_PATTERNS:
            rest = re.sub(p, " ", rest)
    return timing, re.sub(r"\s+", " ", rest).strip()


# --------------------------------------------------------------------------- notifications

def _both(fn) -> dict:
    """Evaluate a text-producing function once per language."""
    with using("ar"):
        ar = fn()
    with using("en"):
        en = fn()
    return {"ar": ar, "en": en}


def notify(db: Session, user_id: int, kind: str, title: dict, body: dict, key: Optional[str] = None,
           meta: Optional[dict] = None) -> Optional[Notification]:
    """title / body are {"ar": ..., "en": ...} (see i18n.both): shown in the reader's language later."""
    if key and db.scalar(select(Notification.id).where(Notification.user_id == user_id, Notification.key == key)):
        return None
    meta = {**(meta or {}), "en": {"title": title["en"], "body": body["en"]}}
    n = Notification(user_id=user_id, kind=kind, title=title["ar"], body=body["ar"], key=key, meta=meta)
    db.add(n)
    try:
        db.commit()
    except IntegrityError:  # raced with another worker
        db.rollback()
        return None
    return n


def unread_notifications(db: Session, user_id: int, limit: int = 20) -> list[Notification]:
    return list(db.scalars(select(Notification).where(Notification.user_id == user_id,
                                                      Notification.read.is_(False))
                           .order_by(Notification.id.desc()).limit(limit)).all())


# --------------------------------------------------------------------------- manager

class ScheduleManager:
    def __init__(self, engine: ActionEngine):
        self.e = engine
        self.db = engine.db
        self.user = engine.user
        self.conv = engine.conv

    # ---------------------------------------------------------------- queries
    def pending(self) -> Optional[Schedule]:
        if self.conv is None:
            return None
        return self.db.scalar(select(Schedule).where(Schedule.conversation_id == self.conv.id,
                                                     Schedule.status == "pending").order_by(Schedule.id.desc()))

    def get(self, sid: int) -> Optional[Schedule]:
        s = self.db.get(Schedule, sid)
        return s if s and s.user_id == self.user.id else None

    def list(self, include_inactive: bool = False) -> list[Schedule]:
        q = select(Schedule).where(Schedule.user_id == self.user.id)
        statuses = ["active", "paused"] + (["completed", "cancelled"] if include_inactive else [])
        q = q.where(Schedule.status.in_(statuses)).order_by(Schedule.next_run_at.is_(None), Schedule.next_run_at)
        return list(self.db.scalars(q).all())

    # ---------------------------------------------------------------- prepare
    def prepare(self, *, kind: str = "payment", service: Optional[str] = None, fields: Optional[dict] = None,
                timing: Optional[dict] = None, note: Optional[str] = None, merge: bool = True,
                source: str = "assistant") -> dict[str, Any]:
        e = self.e
        kind = "reminder" if kind == "reminder" else "payment"
        svc = get_service(service) if kind == "payment" else None
        if kind == "payment" and (not svc or svc.key not in SCHEDULABLE):
            names = "، ".join(SERVICES[k].name_t for k in SCHEDULABLE)
            return {"status": "invalid_service",
                    "message": tr(f"أكدر أجدول بس: {names}. أو أسويلك تذكير.",
                                  f"I can only schedule: {names}. Or I can set a reminder.")}

        incoming = {k: v for k, v in (fields or {}).items()
                    if v is not None and not isinstance(v, (dict, list)) and str(v).strip() != ""}
        timing_in = {k: v for k, v in (timing or {}).items() if v not in (None, "")}
        draft = e.draft
        same = (draft and draft.get("mode") == "schedule" and draft.get("kind") == kind
                and draft.get("service") == (svc.key if svc else None))
        base, context, base_timing, base_note = {}, {}, {}, ""
        if merge and same:
            base = dict(draft.get("fields") or {})
            context = dict(draft.get("context") or {})
            base_timing = dict(draft.get("timing") or {})
            base_note = draft.get("note") or ""
        elif draft and not same:
            e._cancel_pending_silently()
            e.clear_draft()
        note = (note or base_note or "").strip()[:200]

        # ---- payment fields
        clean: dict[str, Any] = {}
        errors: dict[str, str] = {}
        choices: list[str] = []
        awaiting: Optional[str] = None
        message = ""
        auto_amount = False
        if svc:
            r = e.resolve(svc, base, incoming, context)
            clean, errors, missing, choices = r["clean"], r["errors"], r["missing"], r["choices"]
            if svc.key == "bill_payment":
                # recurring bills pay whatever is due each time unless a fixed amount was given
                if "amount" not in incoming and ("amount" not in base or context.get("auto_amount")):
                    if context.get("auto_amount") or "amount" in missing:
                        clean.pop("amount", None)
                        missing = [k for k in missing if k != "amount"]
                        errors.pop("amount", None)
                        auto_amount = True
            open_keys = [f.key for f in svc.fields if f.applies(clean) and (f.key in errors or f.key in missing)]
            if open_keys:
                awaiting = open_keys[0]
                f = svc.field(awaiting)
                message = errors.get(awaiting) or f.ask_t
                if not choices:
                    choices = e._choices_for(svc, f)
        elif not note:
            awaiting, message = "note", tr("شنو تريدني أذكّرك بيه؟", "What should I remind you about?")

        # ---- timing
        t, terr = self._clean_timing({**base_timing, **timing_in})
        if not awaiting:
            if terr:
                awaiting, message = terr
            elif "frequency" not in t:
                awaiting, message = "frequency", FREQ_ASK()
                choices = [tr("مرة وحدة", "Once"), tr("كل أسبوع", "Every week"), tr("كل شهر", "Every month")]
            elif t["frequency"] == "monthly" and "day" not in t:
                awaiting, message = "day", DAY_ASK_MONTHLY()
                choices = [tr("يوم 1", "Day 1"), tr("يوم 15", "Day 15"), tr("آخر الشهر", "End of month")]
            elif t["frequency"] == "weekly" and "day" not in t:
                awaiting, message, choices = "day", DAY_ASK_WEEKLY(), [weekday(4), weekday(5), weekday(6)]
            elif t["frequency"] == "once" and "date" not in t:
                awaiting, message = "date", DATE_ASK()
                choices = [tr("باجر", "Tomorrow"), tr("بعد باجر", "Day after tomorrow")]

        stored = ActionEngine._storable(svc, clean) if svc else {}
        if auto_amount:
            context["auto_amount"] = True
        draft_doc = {"mode": "schedule", "kind": kind, "service": svc.key if svc else None,
                     "fields": stored, "context": context, "timing": t, "note": note}

        if awaiting:
            e._save_draft({**draft_doc, "awaiting": awaiting})
            self.db.commit()
            return {"status": "needs_info", "mode": "schedule", "kind": kind,
                    "service": svc.key if svc else None, "service_name": svc.name_t if svc else tr("تذكير", "Reminder"),
                    "fields": stored, "timing": t, "awaiting": awaiting, "errors": errors,
                    "message": message, "choices": [c for c in choices][:6]}

        next_local = compute_next_run(t["frequency"], t.get("day"), t.get("date"))
        if next_local is None:
            e._save_draft({**draft_doc, "awaiting": "date"})
            self.db.commit()
            return {"status": "needs_info", "mode": "schedule", "kind": kind,
                    "service": svc.key if svc else None, "service_name": svc.name_t if svc else tr("تذكير", "Reminder"),
                    "fields": stored, "timing": t, "awaiting": "date", "errors": {},
                    "message": DATE_PAST(), "choices": [tr("باجر", "Tomorrow"), tr("بعد باجر", "Day after tomorrow")]}

        e._cancel_pending_silently()
        sfields = dict(stored)
        if svc:
            sfields.update({k: v for k, v in context.items() if k in ("recipient_name", "is_new_recipient")})
            if auto_amount:
                sfields["auto_amount"] = True
        s = Schedule(user_id=self.user.id, conversation_id=self.conv.id if self.conv is not None else None,
                     kind=kind, service=svc.key if svc else None, fields=sfields, note=note,
                     frequency=t["frequency"], day=t.get("day"), start_date=t.get("date"),
                     status="pending", source=source, next_run_at=to_utc_naive(next_local))
        self.db.add(s)
        self.db.flush()
        e._save_draft({**draft_doc, "awaiting": None, "pending_schedule": s.id})
        self.db.commit()
        pub = self.public(s)
        amount = ""
        if auto_amount:
            amount = tr(" بالمبلغ المستحق كل مرة", " for whatever is due each time")
        elif pub["amount_display"]:
            amount = tr(f" بمبلغ {pub['amount_display']}", f" of {pub['amount_display']}")
        msg = tr(f"راح أجدول {pub['title']}{amount}، {pub['timing']}. أول مرة {pub['next_run_display']}. "
                 "كول «أكّد» حتى أفعّلها.",
                 f"I'll schedule {pub['title']}{amount}, {pub['timing']}. First run {pub['next_run_display']}. "
                 "Say «confirm» to activate it.")
        return {"status": "ready", "mode": "schedule", "schedule": pub, "message": msg,
                "choices": [tr("أكّد", "Confirm"), tr("إلغاء", "Cancel")]}

    def _clean_timing(self, raw: dict) -> tuple[dict, Optional[tuple[str, str]]]:
        t: dict[str, Any] = {}
        freq = parse_frequency(raw.get("frequency")) if raw.get("frequency") else None
        if raw.get("frequency") and not freq:
            return t, ("frequency", FREQ_ASK())
        if freq:
            t["frequency"] = freq
        if freq in ("monthly", "weekly") and raw.get("day") not in (None, ""):
            d = parse_day(raw["day"], freq)
            if d is None:
                return t, ("day", DAY_ASK_WEEKLY() if freq == "weekly" else DAY_ASK_MONTHLY())
            t["day"] = d
        if freq == "once":
            src = raw.get("date") or raw.get("day")
            if src not in (None, ""):
                d = parse_date(src)
                if not d:
                    return t, ("date", DATE_ASK())
                if date.fromisoformat(d) < local_now().date():
                    return t, ("date", DATE_PAST())
                t["date"] = d
        return t, None

    # ---------------------------------------------------------------- confirm / cancel / manage
    def confirm(self, sid: Optional[int] = None) -> dict[str, Any]:
        s = self.get(sid) if sid else self.pending()
        if not s:
            return {"status": "no_pending", "message": tr("ماكو جدولة بانتظار التأكيد.", "No schedule is waiting for confirmation.")}
        if s.status != "pending":
            return {"status": "not_pending", "schedule": self.public(s),
                    "message": tr(f"هاي الجدولة {status_label(s.status)}.", f"This schedule is {status_label(s.status).lower()}.")}
        nxt = compute_next_run(s.frequency, s.day, s.start_date)
        if nxt is None:
            s.status = "cancelled"
            self.db.commit()
            return {"status": "expired", "schedule": self.public(s),
                    "message": tr("التاريخ فات، نعيد الجدولة؟", "That date has passed. Shall we schedule it again?")}
        s.status = "active"
        s.next_run_at = to_utc_naive(nxt)
        d = self.e.draft
        if d and d.get("pending_schedule") == s.id:
            self.e.clear_draft()
        self.db.commit()
        pub = self.public(s)
        if s.kind == "reminder":
            msg = tr(f"تم تفعيل التذكير. راح أذكّرك {pub['next_run_display']}.",
                     f"Reminder set. I'll remind you {pub['next_run_display']}.")
        else:
            msg = tr(f"تم تفعيل الدفعة المجدولة. أول مرة {pub['next_run_display']}، وراح أذكّرك قبلها بيوم.",
                     f"Scheduled payment is active. First run {pub['next_run_display']}; I'll remind you a day before.")
        return {"status": "activated", "schedule": pub, "message": msg}

    def cancel(self, sid: Optional[int] = None) -> dict[str, Any]:
        s = self.get(sid) if sid else self.pending()
        if not s:
            had = bool(self.e.draft and self.e.draft.get("mode") == "schedule")
            self.e.clear_draft()
            self.db.commit()
            return ({"status": "cancelled", "message": tr("تم الإلغاء.", "Cancelled.")} if had
                    else {"status": "nothing", "message": tr("ماكو جدولة حتى ألغيها.", "There is no schedule to cancel.")})
        if s.status in ("cancelled", "completed"):
            return {"status": "not_pending", "schedule": self.public(s),
                    "message": tr(f"هاي الجدولة {status_label(s.status)}.", f"This schedule is {status_label(s.status).lower()}.")}
        was_active = s.status in ("active", "paused")
        s.status = "cancelled"
        d = self.e.draft
        if d and d.get("pending_schedule") == s.id:
            self.e.clear_draft()
        self.db.commit()
        title = self.public(s)["title"]
        msg = (tr(f"وقّفت {title} نهائياً.", f"Stopped {title} for good.") if was_active
               else tr("تم الإلغاء وما انجدول شي.", "Cancelled; nothing was scheduled."))
        return {"status": "cancelled", "schedule": self.public(s), "message": msg}

    def set_paused(self, sid: int, paused: bool) -> dict[str, Any]:
        s = self.get(sid)
        if not s or s.status not in ("active", "paused"):
            return {"status": "not_found", "message": tr("ما لكيت هاي الجدولة.", "I couldn't find that schedule.")}
        if paused:
            s.status = "paused"
            msg = tr(f"وقّفت {self.public(s)['title']} مؤقتاً.", f"Paused {self.public(s)['title']}.")
        else:
            s.status = "active"
            nxt = compute_next_run(s.frequency, s.day, s.start_date)
            if nxt is None:
                s.status = "completed"
            else:
                s.next_run_at = to_utc_naive(nxt)
            msg = tr(f"رجعت فعّلت {self.public(s)['title']}. المرة الجاية {self.public(s)['next_run_display']}.",
                     f"Resumed {self.public(s)['title']}. Next run {self.public(s)['next_run_display']}.")
        self.db.commit()
        return {"status": s.status, "schedule": self.public(s), "message": msg}

    def run_now(self, sid: int) -> dict[str, Any]:
        """Demo helper: execute the next occurrence immediately."""
        s = self.get(sid)
        if not s or s.status not in ("active", "paused"):
            return {"status": "not_found", "message": tr("ما لكيت هاي الجدولة.", "I couldn't find that schedule.")}
        res = execute_schedule(self.db, s)
        self.db.refresh(self.user)
        return {**res, "schedule": self.public(s), "balance": self.user.balance}

    # ---------------------------------------------------------------- display
    def public(self, s: Schedule) -> dict[str, Any]:
        svc = SERVICES.get(s.service) if s.service else None
        f = s.fields or {}
        amount_display = ""
        lines: list[dict[str, str]] = []
        if s.kind == "reminder":
            title = tr("تذكير: ", "Reminder: ") + s.note if s.note else tr("تذكير", "Reminder")
            icon = "bell"
        else:
            tmp = Transaction(service=s.service, fields=f, amount=float(f.get("amount") or 0),
                              currency=svc.currency if svc else "IQD")
            title = self.e.title(tmp)
            icon = svc.icon if svc else "list"
            if f.get("amount"):
                amount_display = fmt_money(float(f["amount"]), svc.currency if svc else "IQD")
            elif f.get("auto_amount"):
                amount_display = tr("المبلغ المستحق كل مرة", "Whatever is due each time")
            if s.service == "transfer":
                lines.append({"label": tr("المستلم", "Receiver"), "value": disp(f.get("recipient_name")) or tr("مستلم جديد", "New receiver")})
                lines.append({"label": tr("رقم المحفظة", "Wallet number"), "value": _fmt_phone(f.get("wallet", ""))})
            elif svc:
                for fld in svc.fields:
                    if fld.key != "amount" and fld.key in f:
                        lines.append({"label": fld.label_t, "value": _fmt_phone(f[fld.key]) if fld.type == "phone" else disp(f[fld.key])})
            lines.append({"label": tr("المبلغ", "Amount"), "value": amount_display or "—", "kind": "amount"})
        timing = describe_timing(s.frequency, s.day, s.start_date)
        lines.append({"label": tr("التكرار", "Repeats"), "value": timing})
        return {
            "id": s.id, "kind": s.kind, "service": s.service, "service_name": svc.name_t if svc else tr("تذكير", "Reminder"),
            "icon": icon, "title": title, "note": s.note, "amount_display": amount_display,
            "frequency": s.frequency, "frequency_label": freq_label(s.frequency),
            "timing": timing, "status": s.status, "status_label": status_label(s.status),
            "next_run_at": iso(s.next_run_at),
            "next_run_display": fmt_local(s.next_run_at) if s.status in ("pending", "active") else "—",
            "last_run_at": iso(s.last_run_at), "last_status": s.last_status, "runs": s.runs,
            "lines": lines, "source": s.source,
        }


def _fmt_phone(p: str) -> str:
    return f"{p[:4]} {p[4:7]} {p[7:]}" if p and len(p) == 11 else (p or "")


# --------------------------------------------------------------------------- execution

def execute_schedule(db: Session, s: Schedule, now_local: Optional[datetime] = None) -> dict[str, Any]:
    """Run one occurrence and advance the schedule. Safe against double execution."""
    now_local = now_local or local_now()
    old_next = s.next_run_at
    nxt = None if s.frequency == "once" else compute_next_run(s.frequency, s.day, s.start_date, now_local)
    claimed = db.execute(
        update(Schedule).where(Schedule.id == s.id, Schedule.next_run_at.is_(old_next) if old_next is None
                               else Schedule.next_run_at == old_next)
        .values(next_run_at=to_utc_naive(nxt) if nxt else None, last_run_at=utcnow())
    ).rowcount
    if not claimed:
        db.rollback()
        return {"status": "skipped", "message": "already running"}
    db.commit()
    db.refresh(s)
    user = db.get(User, s.user_id)
    run_key = iso(old_next) or iso(utcnow())
    pub_engine = ActionEngine(db, user)
    title = _both(lambda: ScheduleManager(pub_engine).public(s)["title"])

    if s.kind == "reminder":
        notify(db, user.id, "reminder", both(f"تذكير: {s.note}", f"Reminder: {s.note}"),
               both("هذا التذكير اللي طلبته.", "This is the reminder you asked for."),
               key=f"reminder:{s.id}:{run_key}", meta={"schedule_id": s.id})
        status, message = "done", f"Reminder: {s.note}"
    else:
        fields = {k: v for k, v in (s.fields or {}).items()
                  if k not in ("recipient_name", "is_new_recipient", "auto_amount")}
        engine = ActionEngine(db, user)
        res = engine.prepare(s.service, fields, merge=False, source="scheduled")
        if res["status"] == "ready":
            tx = db.get(Transaction, res["action"]["id"])
            tx.schedule_id = s.id
            db.commit()
            done = engine.confirm(tx.id)  # the standing order itself was confirmed by the user
            if done["status"] == "completed":
                status = "done"
                body = _both(lambda: engine._result_message(tx))
                message = body["en"]
                notify(db, user.id, "schedule_done", both(f"تم تنفيذ {title['ar']}", f"Done: {title['en']}"), body,
                       key=f"done:{s.id}:{run_key}", meta={"schedule_id": s.id, "tx_id": tx.id})
            else:
                status, message = "failed", done["message"]
                body = both(done["message"], done["message"])
        elif res["status"] == "insufficient":
            status = "failed"
            body = _both(lambda: tr(f"ما قدرت أنفّذ {title['ar']} لأن رصيدك ما يكفي ({fmt_iqd(user.balance)}).",
                                    f"I couldn't run {title['en']}: your balance is not enough ({fmt_iqd(user.balance)})."))
            message = body["en"]
        elif s.service == "bill_payment" and res.get("awaiting") == "amount":
            status = "skipped"
            body = both(f"ما نفّذت {title['ar']} لأن ماكو مبلغ مستحق على الفاتورة هالمرة.",
                        f"Skipped {title['en']}: nothing is due on the bill this time.")
            message = body["en"]
        else:
            status = "failed"
            body = both(f"ما قدرت أنفّذ {title['ar']}: {res.get('message', '')}", f"I couldn't run {title['en']}.")
            message = body["en"]
        if status == "failed":
            notify(db, user.id, "schedule_failed", both(f"ما تم تنفيذ {title['ar']}", f"Not done: {title['en']}"), body,
                   key=f"failed:{s.id}:{run_key}", meta={"schedule_id": s.id})
        elif status == "skipped":
            notify(db, user.id, "schedule_skipped", both(f"ما احتجنا ننفذ {title['ar']}", f"Not needed: {title['en']}"),
                   body, key=f"skipped:{s.id}:{run_key}", meta={"schedule_id": s.id})

    s.runs += 1
    s.last_status = status
    if nxt is None:
        s.status = "completed"
    db.commit()
    log.info("schedule %s run: %s", s.id, status)
    return {"status": status, "message": message}


def generate_reminders(db: Session, now_local: Optional[datetime] = None) -> int:
    """Bill-due and upcoming-run reminders. Idempotent (deduplicated by key)."""
    now_local = now_local or local_now()
    st = get_settings()
    created = 0
    for b in db.scalars(select(Bill).where(Bill.status == "due", Bill.amount_due > 0)).all():
        try:
            due = date.fromisoformat(b.due_date)
        except (TypeError, ValueError):
            continue
        days = (due - now_local.date()).days
        biller_en = _both(lambda: disp(b.biller))["en"]
        amt = _both(lambda: fmt_iqd(b.amount_due))
        if days < 0:
            n = notify(db, b.user_id, "bill_overdue", both(f"فاتورة {b.biller} متأخرة", f"{biller_en} bill is overdue"),
                       both(f"المبلغ المستحق {amt['ar']}. تكدر تكول للمساعد: «ادفع فاتورة {b.biller}».",
                            f"{amt['en']} is due. You can tell the assistant: «pay the {biller_en} bill»."),
                       key=f"overdue:{b.id}:{b.due_date}", meta={"bill_id": b.id, "biller": b.biller})
        elif days <= st.bill_reminder_days:
            when = {0: "اليوم", 1: "باجر", 2: "بعد يومين"}.get(days, f"بعد {days} أيام")
            when_en = {0: "today", 1: "tomorrow"}.get(days, f"in {days} days")
            n = notify(db, b.user_id, "bill_due", both(f"فاتورة {b.biller} تستحق {when}", f"{biller_en} bill is due {when_en}"),
                       both(f"المبلغ {amt['ar']}. كول للمساعد: «ادفع فاتورة {b.biller}» وهو يكمّلها.",
                            f"Amount {amt['en']}. Tell the assistant «pay the {biller_en} bill» and it handles the rest."),
                       key=f"bill:{b.id}:{b.due_date}", meta={"bill_id": b.id, "biller": b.biller})
        else:
            n = None
        created += 1 if n else 0
    horizon = to_utc_naive(now_local + timedelta(hours=24))
    for s in db.scalars(select(Schedule).where(Schedule.status == "active", Schedule.next_run_at.is_not(None),
                                               Schedule.next_run_at <= horizon)).all():
        if s.kind == "reminder":
            continue
        user = db.get(User, s.user_id)
        sm = ScheduleManager(ActionEngine(db, user))
        ar = _both(lambda: sm.public(s))
        pa, pe = ar["ar"], ar["en"]
        n = notify(db, s.user_id, "schedule_upcoming",
                   both(f"تذكير: {pa['title']}" + (f" بمبلغ {pa['amount_display']}" if pa["amount_display"] else ""),
                        f"Coming up: {pe['title']}" + (f" of {pe['amount_display']}" if pe["amount_display"] else "")),
                   both(f"راح تتنفذ {pa['next_run_display']}. إذا تريد توقفها كول للمساعد «وقّف الدفعة».",
                        f"It runs {pe['next_run_display']}. To stop it, tell the assistant «stop the payment»."),
                   key=f"upcoming:{s.id}:{iso(s.next_run_at)}", meta={"schedule_id": s.id})
        created += 1 if n else 0
    return created


def run_scheduler(db: Session, now_local: Optional[datetime] = None) -> dict[str, int]:
    now_local = now_local or local_now()
    due = db.scalars(select(Schedule).where(Schedule.status == "active", Schedule.next_run_at.is_not(None),
                                            Schedule.next_run_at <= to_utc_naive(now_local))).all()
    executed = 0
    for s in due:
        try:
            if execute_schedule(db, s, now_local)["status"] != "skipped":
                executed += 1
        except Exception:  # one bad schedule must not stop the others
            db.rollback()
            log.exception("schedule %s failed", s.id)
    reminders = generate_reminders(db, now_local)
    return {"executed": executed, "reminders": reminders}

