"""Arabic (Iraqi dialect) text normalisation and parsing helpers.

Used both by the validation layer (to clean whatever the LLM / user typed) and by the
offline rule-based agent. Everything here is pure and side-effect free.
"""
from __future__ import annotations

import re
from difflib import SequenceMatcher
from typing import Iterable, Optional

_DIACRITICS = re.compile(r"[ؐ-ًؚ-ٰٟۖ-ۭـ]")
_DIGITS = str.maketrans("٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹", "01234567890123456789")


def to_ascii_digits(text: str) -> str:
    return (text or "").translate(_DIGITS).replace("٬", ",").replace("٫", ".").replace("،", ",")


def normalize(text: str) -> str:
    """Lower-case, strip diacritics/tatweel, unify Arabic letter variants and punctuation."""
    s = to_ascii_digits(str(text or ""))
    s = _DIACRITICS.sub("", s)
    s = re.sub("[إأآٱ]", "ا", s)
    for a, b in (("ى", "ي"), ("ة", "ه"), ("ؤ", "و"), ("ئ", "ي"), ("ڤ", "ف"), ("گ", "ك"),
                 ("چ", "ج"), ("ک", "ك"), ("ی", "ي"), ("پ", "ب")):
        s = s.replace(a, b)
    s = s.lower()
    s = re.sub(r"(?<=\d),(?=\d{3}\b)", "", s)  # 25,000 -> 25000
    s = re.sub(r"[^\w\s.+$]", " ", s)
    s = s.replace("_", " ")
    s = re.sub(r"(?<!\d)\.|\.(?!\d)", " ", s)  # keep only decimal points
    return re.sub(r"\s+", " ", s).strip()


# --------------------------------------------------------------------------- phrases

_PREFIX = r"(?:^|\s)(?:[وبلفك])?(?:ال|ل)?"


def phrase_in(text_norm: str, phrase: str) -> bool:
    """True if `phrase` occurs in normalised text as whole words.

    Tolerates Arabic attached prefixes on the first word (و ب ل ف ك + ال), so
    "بتركيا" / "للاردن" / "لعلي" match "تركيا" / "الاردن" / "علي".
    """
    p = normalize(phrase)
    if not p:
        return False
    if p.startswith("ال") and len(p) > 3:
        p = p[2:]
    pattern = _PREFIX + re.escape(p) + r"(?=\s|$)"
    return re.search(pattern, text_norm) is not None


def similarity(a: str, b: str) -> float:
    return SequenceMatcher(None, normalize(a), normalize(b)).ratio()


def match_choice(value: str, options: Iterable, synonyms: Optional[dict] = None,
                 threshold: float = 0.78) -> Optional[str]:
    """Map free text onto one of `options` using exact, phrase, synonym and fuzzy matching."""
    options = list(options)
    synonyms = synonyms or {}
    v = normalize(str(value))
    if not v:
        return None
    # exact
    for opt in options:
        if normalize(str(opt)) == v:
            return opt
        for syn in synonyms.get(opt, []):
            if normalize(syn) == v:
                return opt
    # phrase contained in text (longest phrase wins)
    best, best_len = None, 0
    for opt in options:
        for cand in [str(opt), *synonyms.get(opt, [])]:
            if phrase_in(v, cand) and len(cand) > best_len:
                best, best_len = opt, len(cand)
    if best is not None:
        return best
    # fuzzy
    scored = []
    for opt in options:
        for cand in [str(opt), *synonyms.get(opt, [])]:
            scored.append((similarity(v, cand), opt))
    scored.sort(key=lambda x: x[0], reverse=True)
    if scored and scored[0][0] >= threshold:
        return scored[0][1]
    return None


def find_choice_in_text(text_norm: str, options: Iterable, synonyms: Optional[dict] = None) -> Optional[str]:
    """Like match_choice but only phrase matching (no fuzzy) — for scanning whole sentences."""
    synonyms = synonyms or {}
    best, best_len = None, 0
    for opt in options:
        for cand in [str(opt), *synonyms.get(opt, [])]:
            if phrase_in(text_norm, cand) and len(cand) > best_len:
                best, best_len = opt, len(cand)
    return best


# --------------------------------------------------------------------------- phones

def to_local_phone(digits: str) -> Optional[str]:
    """Normalise an Iraqi mobile number to 07XXXXXXXXX, or None."""
    d = re.sub(r"\D", "", to_ascii_digits(digits or ""))
    if d.startswith("00964"):
        d = d[5:]
    elif d.startswith("964"):
        d = d[3:]
    if len(d) == 10 and d.startswith("7"):
        d = "0" + d
    if len(d) == 11 and d.startswith("07"):
        return d
    return None


def extract_phone(text: str) -> tuple[Optional[str], str]:
    """Find an Iraqi mobile number inside free text (digits may be split by spaces/dashes).

    Returns (phone, text_without_phone).
    """
    t = to_ascii_digits(text or "")
    groups = list(re.finditer(r"\+?\d+", t))
    for i in range(len(groups)):
        acc = ""
        for j in range(i, min(i + 6, len(groups))):
            if j > i and t[groups[j - 1].end():groups[j].start()].strip(" -") != "":
                break
            acc += re.sub(r"\D", "", groups[j].group())
            phone = to_local_phone(acc)
            if phone:
                return phone, (t[:groups[i].start()] + " " + t[groups[j].end():]).strip()
            if len(acc) > 14:
                break
    return None, t


def carrier_from_phone(phone: str) -> Optional[str]:
    if not phone or len(phone) < 3:
        return None
    return {"077": "آسياسيل", "078": "زين", "079": "زين", "075": "كورك"}.get(phone[:3])


# --------------------------------------------------------------------------- amounts

_UNITS = {
    "صفر": 0, "واحد": 1, "وحده": 1, "اثنين": 2, "اثنان": 2, "ثنين": 2, "اثنتين": 2, "تنين": 2,
    "ثلاث": 3, "ثلاثه": 3, "تلاث": 3, "تلاثه": 3, "اربع": 4, "اربعه": 4, "خمس": 5, "خمسه": 5,
    "ست": 6, "سته": 6, "سبع": 7, "سبعه": 7, "ثمان": 8, "ثماني": 8, "ثمانيه": 8, "ثمن": 8,
    "ثمنيه": 8, "تمن": 8, "تسع": 9, "تسعه": 9, "عشر": 10, "عشره": 10,
}
_TEENS = {
    "احدعش": 11, "احدعشر": 11, "حدعش": 11, "اثنعش": 12, "اثناعش": 12, "ثنعش": 12, "اثنعشر": 12,
    "ثلطعش": 13, "ثلاثطعش": 13, "تلطعش": 13, "ثلثطعش": 13, "اربعطعش": 14, "اربعتعش": 14,
    "خمسطعش": 15, "خمستعش": 15, "سطعش": 16, "ستطعش": 16, "سبعطعش": 17, "سبعتعش": 17,
    "ثمنطعش": 18, "ثمانطعش": 18, "تسعطعش": 19, "تسعتعش": 19,
}
_TENS = {
    "عشرين": 20, "ثلاثين": 30, "تلاثين": 30, "اربعين": 40, "خمسين": 50, "ستين": 60,
    "سبعين": 70, "ثمانين": 80, "ثمنين": 80, "تسعين": 90,
}
_HUNDREDS = {
    "ميه": 100, "ميت": 100, "مئه": 100, "مائه": 100, "ميتين": 200, "مئتين": 200, "مئتان": 200,
    "ميتان": 200, "ثلاثميه": 300, "تلثميه": 300, "ثلثميه": 300, "تلاثميه": 300, "اربعميه": 400,
    "خمسميه": 500, "ستميه": 600, "سبعميه": 700, "ثمنميه": 800, "ثمانميه": 800, "تسعميه": 900,
}
_THOUSAND = {"الف", "الاف", "الوف", "الآف", "thousand", "thousands", "k"}
_MILLION = {"مليون", "ملايين", "ملاين", "million", "millions"}
_HALF = {"نص", "نصف", "half"}
_QUARTER = {"ربع", "quarter"}
_NUM_RE = re.compile(r"\d+(?:\.\d+)?")


def _hundreds_value(tok: str) -> Optional[int]:
    if tok in _HUNDREDS:
        return _HUNDREDS[tok]
    for suffix in ("ميه", "مئه", "مائه"):
        if tok.endswith(suffix) and tok[: -len(suffix)] in _UNITS:
            return _UNITS[tok[: -len(suffix)]] * 100
    return None


def _is_num_token(tok: str) -> bool:
    return bool(
        _NUM_RE.fullmatch(tok)
        or tok in _UNITS or tok in _TEENS or tok in _TENS
        or _hundreds_value(tok) is not None
        or tok in _THOUSAND or tok in _MILLION or tok in _HALF or tok in _QUARTER
        or tok in ("الفين", "الفان", "مليونين")
    )


def _strip_prefix(tok: str) -> Optional[str]:
    if _is_num_token(tok):
        return tok
    for p in ("وب", "بال", "و", "ب", "ل"):
        if tok.startswith(p) and _is_num_token(tok[len(p):]):
            return tok[len(p):]
    return None


def _eval_run(run: list[str]) -> float:
    total, current, last_mult = 0.0, 0.0, 1.0
    for t in run:
        if _NUM_RE.fullmatch(t):
            current += float(t)
        elif t in _UNITS:
            current += _UNITS[t]
        elif t in _TEENS:
            current += _TEENS[t]
        elif t in _TENS:
            current += _TENS[t]
        elif _hundreds_value(t) is not None:
            v = _hundreds_value(t)
            if v == 100 and 0 < current < 10:
                current *= 100
            else:
                current += v
        elif t in _HALF or t in _QUARTER:
            frac = 0.5 if t in _HALF else 0.25
            if total > 0 and current == 0:
                total += last_mult * frac
            else:
                current += frac
        elif t in _THOUSAND:
            current = (current or 1) * 1000
            total += current
            current, last_mult = 0, 1000
        elif t in ("الفين", "الفان"):
            total += 2000
            last_mult = 1000
        elif t in _MILLION:
            current = (current or 1) * 1_000_000
            total += current
            current, last_mult = 0, 1_000_000
        elif t == "مليونين":
            total += 2_000_000
            last_mult = 1_000_000
    return total + current


_EN_UNITS = {w: i for i, w in enumerate(
    "zero one two three four five six seven eight nine ten eleven twelve thirteen fourteen fifteen sixteen "
    "seventeen eighteen nineteen".split())}
_EN_TENS = {w: 10 * (i + 2) for i, w in enumerate("twenty thirty forty fifty sixty seventy eighty ninety".split())}
_EN_NUM = {**_EN_UNITS, **_EN_TENS}


def _english_number_words(n: str) -> str:
    """English number words to digits, scale words kept: "twenty five thousand" -> "25 thousand",
    "two hundred and fifty" -> "250", "a hundred" -> "100"."""
    out: list[str] = []
    cur: Optional[int] = None
    toks = n.split()
    for i, tok in enumerate(toks):
        parts = tok.split("-")
        if len(parts) > 1 and all(x in _EN_NUM for x in parts):  # "twenty-five"
            cur = (cur or 0) + sum(_EN_NUM[x] for x in parts)
            continue
        if tok in _EN_NUM:
            cur = (cur or 0) + _EN_NUM[tok]
            continue
        if tok in ("hundred", "hundreds") and (cur is not None or (out and out[-1] == "a")):
            if cur is None:
                out.pop()
            cur = (cur or 1) * 100
            continue
        if tok == "and" and cur is not None and i + 1 < len(toks) and toks[i + 1] in _EN_NUM:
            continue
        if tok in ("thousand", "thousands", "million", "millions") and cur is None and out and out[-1] == "a":
            out.pop()
            if out and out[-1] == "half":  # "half a million" -> 500000
                out[-1] = str(500 if tok.startswith("thousand") else 500_000)
                continue
            cur = 1
        if cur is not None:
            out.append(str(cur))
            cur = None
        out.append(tok)
    if cur is not None:
        out.append(str(cur))
    res = " ".join(out)
    # "one and a half million" -> 1500000, "two and a half thousand" -> 2500
    return re.sub(r"(?<![\d.,])(\d+) and a half (thousand|million)s?",
                  lambda m: str(int((int(m.group(1)) + 0.5) * (1000 if m.group(2) == "thousand" else 1_000_000))), res)


def parse_amount(text) -> Optional[float]:
    """Parse an amount from digits and/or Iraqi Arabic number words.

    Examples: "25 الف" -> 25000, "خمسة وعشرين الف" -> 25000, "ربع مليون" -> 250000,
    "مليون ونص" -> 1500000, "200 دولار" -> 200, "25k" -> 25000.
    """
    if isinstance(text, bool):
        return None
    if isinstance(text, (int, float)):
        return float(text) if text > 0 else None
    n = _english_number_words(normalize(str(text)))
    n = re.sub(r"(\d)\s*k\b", r"\1 الف", n)
    n = re.sub(r"(\d)\s*m\b", r"\1 مليون", n)
    runs: list[list[str]] = []
    cur: list[str] = []
    for tok in n.split():
        core = _strip_prefix(tok)
        if core is not None:
            cur.append(core)
        elif tok == "و" and cur:
            continue
        else:
            if cur:
                runs.append(cur)
                cur = []
    if cur:
        runs.append(cur)
    # several numbers in one sentence: the one with a scale word (الف / مليون / نص / ربع) is the amount
    scaled = [r for r in runs if any(t in _THOUSAND or t in _MILLION or t in _HALF or t in _QUARTER
                                     or t in ("الفين", "الفان", "مليونين") for t in r)]
    for run in scaled + [r for r in runs if r not in scaled]:
        value = _eval_run(run)
        if value >= 1:
            return value
    return None


def detect_currency(text: str) -> Optional[str]:
    n = normalize(text)
    if "$" in n or re.search(r"(?:^|\s)\S{0,3}(دولار|usd|dollar)", n):
        return "USD"
    if re.search(r"(?:^|\s)\S{0,3}(دينار|iqd)", n):
        return "IQD"
    return None


# --------------------------------------------------------------------------- cards

def luhn_ok(number: str) -> bool:
    digits = [int(c) for c in re.sub(r"\D", "", number)]
    if not 13 <= len(digits) <= 19:
        return False
    checksum = 0
    for i, d in enumerate(reversed(digits)):
        if i % 2 == 1:
            d *= 2
            if d > 9:
                d -= 9
        checksum += d
    return checksum % 10 == 0
